import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст Пресвятій Богородиці перед іконою «Услишательниця»","e":"Akathist to the Theotokos before her icon “She Who Hears”","secs":[{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Бо́жієй Ма́тері і Цари́ці, непреста́нно у Престо́ла Си́на Своєго́ моля́щейся о нас, с любо́вію благода́рственная прино́сим пі́нія. Ти же, я́ко Всеми́лостивая Засту́пниця всіх с ві́рою к Тебі́ притека́ющих, от вся́ких нас бід свободи́, да зове́м Ті:","Ра́дуйся, Всеблага́я Влади́чице, моле́ній на́ших ско́рая Усли́шательнице."]},{"h":"Ікос 1","ps":["А́нгельський собо́р на небесі́ немо́лчно воспіва́єть Тя, Влади́чице, і ми земноро́днії, притека́юще к іко́ні Твоє́й, «Усли́шательниця» імену́ємой, із глубини́ се́рдця взива́єм Ті:","Ра́дуйся, я́ко о Тебі́ ра́дується А́нгельський собо́р і челові́чеський род.","Ра́дуйся, я́ко сла́ва Твоя́ превосхо́дить похвали́ небе́сния і земни́я.","Ра́дуйся, ми́лость Свою́ чрез чудотво́рния іко́ни Твоя́ нам сви́ше посила́ющая.","Ра́дуйся, Всеблага́я на́ша Наста́внице, любо́вію Твоє́ю нас к Себі́ привлекающая.","Ра́дуйся, істоча́ющая вели́кия ми́лості і щедро́ти лю́б'ящим Тя.","Ра́дуйся, скоропредстательная Помо́щнице всім призива́ющим Тя.","Ра́дуйся, Всеблага́я Влади́чице, моле́ній на́ших ско́рая Усли́шательнице."]},{"h":"Кондак 2","ps":["Ви́дящи, Всенепоро́чная, благо́є жела́ніє преподо́бнаго Косьми́, взивающаго к Тебі́: «Пресвята́я Богоро́дице! Помолись Си́ну Твоєму́ і Бо́гу, да наста́вить м'я на путь спасе́нія!», благоволи́ла єси́ предста́тельство Своє́ пред Сино́м Свої́м ми́лостиво єму́ яви́ти, да Христу́ воспіва́єть ви́ну: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́в Промишле́ніє Бо́жиє о себі́ преподо́бний Косма́, в ди́внім гла́се от іко́ни Твоєя́, Преми́лостивая, ізшедшем: «Си́не і Бо́же Мой! Научи́ раба́ Твоєго́ Косму́, ка́ко єму́ спасти́ся!», возопи́ к Тебі́, благо́й Усли́шательнице моле́ній на́ших, во умиле́нії серде́чнім такова́я:","Ра́дуйся, Ма́ти Сві́та Невече́рняго і Ду́ха Свята́го селе́ніє.","Ра́дуйся, Неув'яда́ємий Цві́те нетлі́нія і А́нгельських сил ликова́ніє.","Ра́дуйся, ско́рая Усли́шательнице усе́рдно Тебі́ моля́щихся.","Ра́дуйся, непости́дноє упова́ніє к Тебі́ притека́ющих.","Ра́дуйся, безчи́сленния щедро́ти Своя́ всім ми́лостиво подаю́щая.","Ра́дуйся, Купино́ неопа́льно горя́щая, духо́вною ра́достію нас утіша́ющая.","Ра́дуйся, Всеблага́я Влади́чице, моле́ній на́ших ско́рая Усли́шательнице."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго і благода́тію Твоє́ю, Влади́чице, укрепленний святи́й Косма́, єгда́ сли́шаше на моле́ніє Твоє́ ответствующий глас Творця́ своєго́: «В безмо́лвії да послу́жить Мі!», возблагодари Єго́ за благостноє попече́ніє о себі́ пі́снію: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще такову́ю Попечительницю о спасе́нії на́шем і істо́чник неоскудіва́ємий небе́сних дарова́ній, і́ноці Святи́я Гори́ Афо́нськия притека́ющи к пречу́дному о́бразу Твоєму́ \"Усли́шательниця\" іменуємому, благода́рними усти́ вопію́ть Ті, Богоро́дице:","Ра́дуйся, Пресвята́я Ді́во, жре́бієм Свої́м Го́ру Афо́нськую найменовавшая.","Ра́дуйся, Пречи́стая, мно́гими чудеси́ сію́ Святу́ю Го́ру ознаменовавшая.","Ра́дуйся, моли́тву уго́дника Твоєго́ Косьми́ ско́ро услишавшая.","Ра́дуйся, і на́ша усе́рдная моле́нія не отверга́ющая.","Ра́дуйся, іко́ну Твою́ святу́ю ві́рним в по́мощ дарова́вшая.","Ра́дуйся, зна́менії і чудеси́ сію́ просла́вившая.","Ра́дуйся, Всеблага́я Влади́чице, моле́ній на́ших ско́рая Усли́шательнице."]},{"h":"Кондак 4","ps":["Бу́рю внутр імі́яй помишле́ній сумни́тельних, преподо́бний Косма́ див'я́шеся, ви́дів Жену́ ца́рственния красоти́ во оби́телі Ватопедстей, Я́же Сама́ властительно в це́ркві і трапе́зі повелі́нія разли́чная всім сказу́ющи. Позна́в же в Ней Цари́цю Небе́сную, о насельниціх оби́телі пеку́щуюся, во весе́лії се́рдця возопи́ Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше о чуді ско́раго услишанія Пречи́стою Богоро́дицею моле́нія раба́ Своєго́, в оби́телі Зографстей би́вшем, і́ноці Гори́ Афо́нськия ра́довахуся, ви́дівше но́воє явле́ніє милосе́рдія Твоєго́, о Богома́ти. Сего́ ра́ди благода́рственно вопіє́м Ті си́це:","Ра́дуйся, благ вре́менних і ві́чних усе́рдная нам Хода́тайця.","Ра́дуйся, две́рі Ца́рствія Христо́ва ві́рним отверза́ющая.","Ра́дуйся, любо́вію Твоє́ю нас на небеса́ возводя́щая.","Ра́дуйся, благоутро́біє Си́на Своєго́ к нам приклоня́ющая.","Ра́дуйся, Бо́жия ми́лості і любве́ преізобильноє ісполне́ніє.","Ра́дуйся, вопію́щих к Тебі́ ско́роє усли́шаніє.","Ра́дуйся, Всеблага́я Влади́чице, моле́ній на́ших ско́рая Усли́шательнице."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́ся нам, Влади́чице, честна́я Твоя́ іко́на \"Усли́шательниця\", луча́ми чуде́с Твої́х мрак печа́лей і мглу вся́чеських неду́гов і скорбе́й от серде́ць на́ших прогоня́ющая, і наставля́ющая на путь спасе́нія всіх с ві́рою к Тебі́ притека́ющих і вопію́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще то́ки чуде́с, от святи́я іко́ни Твоєя́ «Услишательници» істочаємия, всі і́ноці Гори́ Афо́нськия і окре́стних стран стека́хуся к ней на поклоне́ніє. Ти же, Преблага́я, всім да́ри ми́лости Твоєя́ неоску́дно подає́ши от чудотво́рнаго о́браза Твоєго́, подвиза́я с благодарностію вопи́ти Тебі́:","Ра́дуйся, Ра́досте на́ша і Утіше́ніє.","Ра́дуйся, Покро́в наш і огражде́ніє.","Ра́дуйся, не́мощі на́ша душе́вния і тіле́сния врачу́ющая.","Ра́дуйся, се́рдця на́ша любо́вію Твоє́ю ум'ягча́ющая.","Ра́дуйся, от гріхо́внаго паде́нія нас ізбавля́ющая.","Ра́дуйся, ум наш на небеса́ возводя́щая.","Ра́дуйся, Всеблага́я Влади́чице, моле́ній на́ших ско́рая Усли́шательнице."]},{"h":"Кондак 6","ps":["Воспіва́єм ди́вноє милосе́рдіє Твоє́ к нам і ве́ліє снисхожде́ніє, Пресвята́я Ді́во, не престає́ши бо моли́тися о нас, грі́шних, пред Престо́лом Си́на Твоєго́ і Бо́га на́шего, є́же отврати́ти гнів Єго́, пра́ведно на ни дви́жимий, і поми́ловати всіх ві́рно вопію́щих: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсіява́єть в душа́х на́ших, ско́рбію і уни́нієм омраче́нних, благода́тнаго утіше́нія світ, і се́рдця на́ша весе́лія і ра́дости ісполня́ються, єгда́ Ти, Влади́чице на́ша Преблага́я, вразумля́єши нас вопи́ти к ще́дрому Бо́гу, да ми́лостив бу́деть нам, грі́шним, і прости́ть нам согріше́нія на́ша. Не премолчи́ у́бо, Влади́чице, моля́щися о нас, зову́щих Ті со умиле́нієм:","Ра́дуйся, скорб на́шу в ра́дость претворя́ющая.","Ра́дуйся, неізрече́нную сла́дость ві́рним ізлива́ющая.","Ра́дуйся, духо́вних оче́й на́ших прозрі́ніє.","Ра́дуйся, скорб'я́щих отра́до і увеселе́ніє.","Ра́дуйся, в ско́рбіх і неду́зіх долготерпі́нію нас науча́ющая.","Ра́дуйся, немощни́х благода́тним Покро́вом Твої́м покрива́ющая.","Ра́дуйся, Всеблага́я Влади́чице, моле́ній на́ших ско́рая Усли́шательнице."]},{"h":"Кондак 7","ps":["Хотя́щи яви́ти то́ки ми́лостей і щедро́т от іко́ни Твоєя́ «Усли́шательниця», сію́ не то́кмо в Горі́ Афо́нстій, но і в подо́біїх єя́ но́вия возже́гши світи́льники, во іни́х граді́х і ве́сіх просла́вила єси́, да спаса́ємії Тобо́ю от бід, Си́ну Твоєму́ вопію́ть: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє чу́до милосе́рдія Твоєго́ зрим, Пречи́стая, в явле́нії чудотво́рнаго о́браза Твоєго́, к нему́же припа́дающе і по́мощі от Тебе́ прося́ще, і Тобо́ю вразумля́ємі і наставля́ємі вопіє́м Ті:","Ра́дуйся, те́плая Хода́тайце о живу́щих в жре́бії Твоє́м - Святі́й Горі́ Афо́нстій.","Ра́дуйся, обитающим зді всіх благ Пода́тельниця.","Ра́дуйся, на вся́ком мі́сті призива́ющих Тя спаса́ющая.","Ра́дуйся, от бід і напа́стей всіх заступа́ющая.","Ра́дуйся, іко́нам Свої́м си́лу чудоді́йствовати дарова́вшая.","Ра́дуйся, Лико́м Твої́м нас утіша́ющая.","Ра́дуйся, Всеблага́я Влади́чице, моле́ній на́ших ско́рая Усли́шательнице."]},{"h":"Кондак 8","ps":["Стра́нно і сумнительно неверующим сли́шати, Ма́ти Царя́ Небе́снаго, ка́ко на іко́ну Твою́ святу́ю ві́рнії лю́діє очи́ма свої́ма і умиле́нними душа́ми взира́юще, от скорбе́й ізбавля́ються і от бід сохраня́ються. Ми же, внима́я сло́ву Твоєму́, Влади́чице, рече́нному к первопи́санній іко́ні Твоє́й: «Благода́ть Ро́ждшагося от Мене́ і Моя́ с се́ю іко́ною да бу́деть», - ві́руєм, я́ко і сія́ іко́на Твоя́ «Усли́шательниця» благода́ть Твою́ істоча́єть. Ті́мже благогові́йно покланя́ющеся, лобиза́єм ю, вопію́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Всім ві́рним уті́шительно єсть взира́ти на святу́ю іко́ну Твою́, Влади́чице, на не́йже зрим Тя, на ру́ку Твоє́ю Предві́чнаго Младе́нця Го́спода на́шего Ісу́са Христа́ держа́щую, Єму́же покланя́ющеся боголі́пно я́ко Си́ну Твоєму́ і Бо́гу на́шему, Тебі́, і́стинній Богоро́дице, со умиленнієм глаго́лем:","Ра́дуйся, го́рняго і до́льняго ми́ра Всецари́це.","Ра́дуйся, небесе́ і землі́ Влади́чице.","Ра́дуйся, Путеводи́тельнице к не́бу пе́рвійшая.","Ра́дуйся, со А́нгелом храни́телем - Храни́тельнице на́ша усе́рдная.","Ра́дуйся, лю́б'ящих Си́на Твоєго́ ча́ди Свої́ми іменующая.","Ра́дуйся, моли́тви на́ша прия́тними Бо́гу соделовающая.","Ра́дуйся, Всеблага́я Влади́чице, моле́ній на́ших ско́рая Усли́шательнице."]},{"h":"Кондак 9","ps":["Вся́каго єстества́ а́нгельськаго преви́сшая яви́лася єси́, Пресвята́я Ді́во, Бо́га бо зачала́ єси́ пло́тію, Невмісти́маго во утро́бі Твоє́й вмісти́ла єси́. Ті́мже всі роди́ блажа́ть Тя по до́лгу, благослове́нная Марі́є Богоро́дице, от восто́ка бо і до за́пада хва́льно і́м'я Твоє́, і́ноков же лиці́ Покрови́тельницю Тя свою́ імену́ють, найпа́че же подвиза́ющіїся в жре́бії Твоє́м - Горі́ Афо́нстій, ю́же осо́бим благоволе́нієм Твої́м осенила єси́, мно́гая чудеса́ в ней содіва́ющи і ми́лості Твоя́ бога́тия насе́льником єя́ явля́ющи, да благода́рно вопію́ть о Тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії челові́честії недоумі́ють восхвали́ти по достоя́нію сла́вноє, Влади́чице, іко́ни Твоєя́ явле́ніє і ди́вная чудотворе́нія Твоя́, лю́дем правосла́вним істочаємая. Ми же, неісче́тния чудеса́ іко́ною Твоє́ю явля́ємая ви́дівше, душе́ю і се́рдцем ра́дуяся, Тебі́ глаго́лем:","Ра́дуйся, ра́дость благода́тную нам ізлива́ющая.","Ра́дуйся, утіше́ніє духо́вноє нам подаю́щая.","Ра́дуйся, на небесі́х ца́рствующая і нас до́лі не оставля́ющая.","Ра́дуйся, житіє́ на́ше земно́є во бла́го устроя́ющая.","Ра́дуйся, покая́нієм на́шим две́рі ра́йськія нам отверза́ющая.","Ра́дуйся, ві́чною ра́достію душі́ на́ша озаря́ющая.","Ра́дуйся, Всеблага́я Влади́чице, моле́ній на́ших ско́рая Усли́шательнице."]},{"h":"Кондак 10","ps":["Спасти́ хотя́щи лю́ди Своя́ от обдержа́щих скорбе́й і болі́зней, дарова́ла єси́ нам, Влади́чице, честну́ю іко́ну Твою́ «Усли́шательницю», да ви́дяще явля́ємую Тобо́ю ми́лость, вопіє́м со умиле́нієм Бо́гу, усиновившему нас Тебі́ при Кресті́ Своє́м і дарова́вшему нам такову́ю Путеводительницю на не́бо: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ заступле́нія, Преблагослове́нная Ді́во, і столп крі́пок от лиця́ вра́жия всім подви́жником благоче́стія: Тебі́ бо даде́ся ве́лія си́ла на те́мния си́ли а́дськия. Сего́ ра́ди ві́рнії согла́сно Тебі́ зову́ть:","Ра́дуйся, ма́тернею любо́вію Твоє́ю весь мир христия́нський об'ємлющая.","Ра́дуйся, сострада́нія к стра́ждущим преісполненная.","Ра́дуйся, на стезю́ спасе́нія ві́рних наставля́ющая.","Ра́дуйся, к благоче́стію і цілому́дрію жизнь на́шу направля́ющая.","Ра́дуйся, оби́телей і́ночеських неуси́пная Блюсти́тельниці.","Ра́дуйся, домо́в і семе́йств благочести́вих неуста́нная Храни́тельнице.","Ра́дуйся, Всеблага́я Влади́чице, моле́ній на́ших ско́рая Усли́шательнице."]},{"h":"Кондак 11","ps":["Пі́ніє на́ше, не довлеющеє к досто́йному прославле́нію ми́лостей Твої́х, Преблагослове́нная, оба́че от полноти́ любве́ і усе́рдія Тебі́ приноси́моє, не пре́зри і не отврати́ся от нас, недосто́йних, но помози́ нам, Всеблага́я, покая́нієм очи́ститися от скве́рни гріхо́вния і преуспі́ти в чи́стім і богоуго́днім житії́, да воспомина́я неісче́тная чудотворе́нія Твоя́, вопіє́м Верхо́вному Творцю́ чуде́с Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світопода́тельними луча́ми чуде́с свята́я іко́на Твоя́ немерцаємо сія́єть, Всеми́лостивая Влади́чице, і весь мир христия́нський благода́тно просвіща́єть, прогоня́ющи вся́коє вра́жиє ді́йство си́лою Бо́жиєю, от нея́ ісходя́щею. Сего́ ра́ди гряду́ть к ней от літ дре́вніх на поклоне́ніє правосла́вних собо́ри, умиле́нно воспіва́я пред не́ю благохвале́нія такова́я:","Ра́дуйся, ру́ці Твої́ за ни ко Го́споду простирающая.","Ра́дуйся, непреста́нно Єму́ моля́щаяся о нас.","Ра́дуйся, неду́жним істо́чник ісціле́ній неоску́дний.","Ра́дуйся, разсла́бленним ті́лом і ду́хом врачева́ніє ско́роє.","Ра́дуйся, ніколи́же ві́рних заступле́нієм не оставля́ющая.","Ра́дуйся, во всем упова́ніє на Бо́га імі́ти нас науча́ющая.","Ра́дуйся, Всеблага́я Влади́чице, моле́ній на́ших ско́рая Усли́шательнице."]},{"h":"Кондак 12","ps":["Благода́ть Бо́жия, прича́стная іко́ні Твоє́й, «Услишательницею» нарече́нній, влече́ть к ней всіх скорб'я́щих і обремене́нних, і не тщи отхо́дять они́ от сего́ істо́чника Твої́х ми́лостей і щедро́т: в ско́рбіх отра́ду, в напа́стіх защи́ту, в болі́зніх цільбу́ неоску́дно получа́я, і благода́рственно вопію́ть Си́ну Твоєму́ і Бо́гу хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще чудеса́ Твоя́, Влади́чице, хва́лим Тя, я́ко Живоно́сний Істо́чник благода́ті, я́ко неістощи́мую реку́ чуде́с, і припа́дая усе́рдно ко святі́й іко́ні Твоє́й, лобиза́єм ю с серде́чною любо́вію і мо́лим Тя: воззри́ на ни милосе́рдієм Твої́м, смире́нно принося́щих Ті пі́сні такови́я:","Ра́дуйся, бедствующим блага́я Помо́щнице.","Ра́дуйся, моля́щихся ско́рая Усли́шательнице.","Ра́дуйся, я́ко в сві́тлую ри́зу непоро́чности облещи́ся нам посо́бствуєши.","Ра́дуйся, я́ко срі́тенію Жениха́ Христа́ предуготовля́ти нас тщи́шися.","Ра́дуйся, ста́ти одесну́ю Бо́га на Стра́шнім Суді́ Христо́вом нам хода́тайствующая.","Ра́дуйся, вни́ти в бра́чний черто́г Си́на Твоєго́ і Бо́га на́шего помога́ющая.","Ра́дуйся, Всеблага́я Влади́чице, моле́ній на́ших ско́рая Усли́шательнице."]},{"h":"Кондак 13","ps":["О Преми́лостивая Ма́ти Сладча́йшаго Го́спода на́шего Ісу́са Христа́, во святі́й іко́ні Твоє́й Услишательницею наре́кшаяся! Прийми́ ми́лостиво сіє́ ма́лоє моле́ніє на́ше і іспо́лни во благи́х проше́нія на́ша: да́руй нам вся потре́бная к жи́зні і благоче́стію, ізба́ви нас от бід, болі́зней і печа́лі і Ца́рствія Небе́снаго наслі́дники всіх сотвори́, ві́рно вопію́щих Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельський собо́р на небесі́ немо́лчно воспіва́єть Тя, Влади́чице, і ми земноро́днії, притека́юще к іко́ні Твоє́й, «Усли́шательниця» імену́ємой, із глубини́ се́рдця взива́єм Ті:","Ра́дуйся, я́ко о Тебі́ ра́дується А́нгельський собо́р і челові́чеський род.","Ра́дуйся, я́ко сла́ва Твоя́ превосхо́дить похвали́ небе́сния і земни́я.","Ра́дуйся, ми́лость Свою́ чрез чудотво́рния іко́ни Твоя́ нам сви́ше посила́ющая.","Ра́дуйся, Всеблага́я на́ша Наста́внице, любо́вію Твоє́ю нас к Себі́ привлекающая.","Ра́дуйся, істоча́ющая вели́кия ми́лості і щедро́ти лю́б'ящим Тя.","Ра́дуйся, скоропредстательная Помо́щнице всім призива́ющим Тя.","Ра́дуйся, Всеблага́я Влади́чице, моле́ній на́ших ско́рая Усли́шательнице."]},{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Бо́жієй Ма́тері і Цари́ці, непреста́нно у Престо́ла Си́на Своєго́ моля́щейся о нас, с любо́вію благода́рственная прино́сим пі́нія. Ти же, я́ко Всеми́лостивая Засту́пниця всіх с ві́рою к Тебі́ притека́ющих, от вся́ких нас бід свободи́, да зове́м Ті:","Ра́дуйся, Всеблага́я Влади́чице, моле́ній на́ших ско́рая Усли́шательнице."]},{"h":"Молитва","ps":["О Преблагослове́нная Влади́чице, Присноді́во Богоро́дице, ско́рая Усли́шательнице всіх, к Тебі́ с ві́рою прибіга́ющих! При́зри с висоти́ небе́снаго вели́чія Твоєго́ на нас, к чудотво́рному Твоєму́ о́бразу припа́дающих і, усли́шав смире́нную моли́тву на́шу, умоли́ Си́на Твоєго́ і Бо́га на́шего да сохрани́ть в ми́рі і благоде́нствії страну́ на́шу, да укріпи́ть Це́рков Правосла́вную і непози́блему соблюде́ть ю от неві́рія, єресе́й і раско́ла. Ізба́ви всіх, о Всеблага́я, с ві́рою Тебі́ моля́щихся, от паде́ній гріхо́вних, от наві́та злих челові́к, от бід, скорбе́й і болі́зней. Да́руй нам дух сокруше́нія, смире́ніє се́рдця, чистоту́ помишле́ній, ісправле́ніє гріхо́вния жи́зні і оставле́ніє согріше́ній на́ших; да всі, благода́рні воспіва́юще вели́чія Твоя́, сподо́бимся Небе́снаго Ца́рствія і та́мо со всі́ми святи́ми просла́вим пречестно́є і великолі́поє і́м'я в Тро́йці сла́вимаго Бо́га: Отця́ і Си́на і Свята́го Ду́ха. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Твоєго́ предста́тельства увіре́ніє і милосе́рдія Твоєго́ явле́ніє іко́на Твоя́ «Усли́шательниця» нам, Влади́чице, показа́ся; пред не́юже ду́ші на́ша в моли́тві ізлива́єм і ві́рою Тебі́ вопіє́м: воззри́, Милосе́рдная, на лю́ди Твоя́, вся ско́рбі на́ша і печа́лі утоли́, утіше́ніє благо́є в сердця́ на́ша низпосли́, моле́нія на́ша ско́ро усли́ши і спасе́ніє ві́чноє душа́м на́шим, Пречи́стая, іспроси́."]},{"h":"Кондак, глас 3","ps":["Днесь, Влади́чице, преподо́бний Косма́ к іко́ні Твоє́й с мольбо́ю припаде́ і Тобо́ю ско́ро усли́шан бисть, непреста́нно Тебі́ хвалу́ воздая́. І нам, под свяще́нний покро́в Твой прибега́ющим, да да́руєть Госпо́дь оставле́ніє гріхо́в і ве́лію ми́лость."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Цілителька»","e":"Akathist to the Theotokos before her icon “The Healer”","secs":[{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Пресвяті́й Ді́ві Богоро́диці, яви́вшейся іногда́ кли́рику боля́щу, во є́же ісціли́ти єго́ от болі́зні лю́тия, похва́льноє прино́сим пі́ніє. Ти же, Всеми́лостивая Влади́чице, я́ко іму́щая держа́ву непобіди́мую, от вся́ких бід і скорбе́й, і болі́зней свободи́ ни, зову́щия Ті:","Ра́дуйся, Благода́тная Ціли́тельнице душ і тіле́с на́ших."]},{"h":"Ікос 1","ps":["Арха́нгел Гавриї́л, возвіща́я Пресвяті́й Ді́ві Марі́ї безсі́менноє зача́тіє от Нея́ Си́на Бо́жия, рече́: «Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю, благослове́нна Ти в жена́х»; ми же, грі́шнії, гла́су Арха́нгелову подража́ти дерза́юще, с ві́рою, любо́вію і благогові́нієм вопіє́м пі́нія сицева́я:","Ра́дуйся, от нача́ла віко́во во главу́ на́шего спасе́нія предизбра́нная;","ра́дуйся, многообра́зні от проро́ков предвозвіще́нная.","Ра́дуйся, Неві́сто Неневі́стная, заче́ншая Си́на от Ду́ха Свята́го;","ра́дуйся, Ма́ти, в рождестві́ і по рождестві́ преби́вшая Ді́во.","Ра́дуйся, Оді́ющагося сві́том, я́ко ри́зою, пелена́ми пови́вшая;","ра́дуйся, млеко́м пита́вшая го́рняя і до́льняя благода́тію Своє́ю Пита́ющаго.","Ра́дуйся, на руку́ Твоє́ю носи́вшая Вседержи́теля;","ра́дуйся, о Промисли́телі всея́ тва́рі попече́ніє імі́вшая.","Ра́дуйся, па́че всіх Си́на Твоєго́ возлюби́вшая;","ра́дуйся, па́че всіх от Него́ превознесе́нная.","Ра́дуйся, честні́йшая і сла́внійшая без сравне́нія всіх Небе́сних Сил;","ра́дуйся, преви́шшая вся́каго созда́нія.","Ра́дуйся, Благода́тная Ціли́тельнице душ і тіле́с на́ших."]},{"h":"Кондак 2","ps":["Ви́дяще, Пресвята́я Влади́чице, усе́рдіє і благогові́ніє кли́рика Вике́нтія, на всяк день преклоня́ющаго колі́на пред честни́м Твої́м о́бразом і арха́нгельськоє приві́тствіє Тебі́ принося́щаго, прия́ла єси́ таково́є єго́ благоугожде́ніє і дарова́ла єси́ єму́ во дні болі́зні внеза́пноє і ди́вноє со одра́ воста́ніє. Ті́мже і ми преклоня́єм колі́на душ і тіле́с на́ших пред цільбоно́сним Твої́м о́бразом, Госпоже́ на́ша Богоро́дице, і, помина́юще чу́дноє явле́ніє Твоє́ кли́рику боля́щему, вопіє́м Си́ну Твоєму́ і Бо́гу на́шему: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́в чуде́сноє ісціле́ніє от тя́жкаго неду́га, кли́рик Вике́нтій воста́ с убо́гаго ло́жа своєго́, і́де в це́рков і та́мо пі́сньми хвале́бними просла́ви Тя, Ціли́тельницю всіх боля́щих. Прийми́ у́бо і от нас, Ма́ти Бо́жия, сія́ благохвале́нія:","Ра́дуйся, от врат сме́ртних неісці́льно боля́щих к жи́зні возвраща́ющая;","ра́дуйся, сострада́нія к стра́ждущим преіспо́лненная.","Ра́дуйся, пораже́нних разли́чними неду́ги чуде́сно ісціля́ющая;","ра́дуйся, во вся́ких ско́рбіх і печа́ліх небе́сную отра́ду в сердця́ на́ша ізлива́ющая.","Ра́дуйся, в христия́нських доброді́теліх преуспі́ти нам помога́ющая;","ра́дуйся, любо́вію к Бо́гу і бли́жнім нас воодушевля́ющая.","Ра́дуйся, от растліва́ющих ду́шу і ті́ло собла́знов ми́ра сего́ сохраня́ющая;","ра́дуйся, ско́рая усли́шательнице усе́рдно Тебі́ моля́щихся.","Ра́дуйся, істоча́ющая вели́кия ми́лості і щедро́ти лю́б'ящим Тя;","ра́дуйся, упова́ющим на Тя вся потре́бная в животі́ сем да́рующая.","Ра́дуйся, ублажа́ющих Тя в гро́зний час сме́рти не оставля́ющая;","ра́дуйся, почита́ющих Тя жи́зні ві́чния сподобля́ющая.","Ра́дуйся, Благода́тная Ціли́тельнице душ і тіле́с на́ших."]},{"h":"Кондак 3","ps":["Си́лою, да́нною от Тебе́, Госпоже́ Цари́це і Влади́чице, свята́я іко́на Твоя́ істоча́єть неоску́дно ісціле́нія стра́ждущим от неду́г многоразли́чних с несумні́нною ві́рою к ней притека́ющим, Бо́гу же вопію́щим: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи премно́гую любо́в к ро́ду христия́нському і Ма́тернєє о нем попече́ніє, всім прося́щим у Тебе́ по́мощі і заступле́нія вся́коє благо́є проше́ніє ско́ро ісполня́єши; сего́ ра́ди Тебе́, всемо́щній Засту́пнице і ско́рой Помо́щнице на́шей, прино́сим похвали́ сія́:","Ра́дуйся, скорб'я́щих утіше́ніє;","ра́дуйся, безнаде́жних наде́ждо.","Ра́дуйся, тружда́ющихся по́мощ і укріпле́ніє;","ра́дуйся, ни́щих одія́ніє.","Ра́дуйся, а́лчущих пита́тельнице;","ра́дуйся, оби́димих і гони́мих засту́пнице.","Ра́дуйся, оби́дящих устраши́тельнице;","ра́дуйся, в христия́нськой ві́рі наста́внице.","Ра́дуйся, взиска́ніє поги́бших;","ра́дуйся, спору́чнице спасе́нія грі́шних.","Ра́дуйся, Благода́тная Ціли́тельнице душ і тіле́с на́ших."]},{"h":"Кондак 4","ps":["Бу́рі страсте́й і по́хотей, і іскуше́ній бісо́вських ізба́ви нас, Премилосе́рдая Богоро́дице, укріпи́ і сохрани́ в нас до конця́ жи́зні на́шея ві́ру правосла́вную і пре́данность Святі́й Це́ркві, да возмо́жем невозбра́нно пі́ти Го́споду Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша Госпо́дь на небесі́ Твоя́ о нас моле́нія, Преблага́я Влади́чице, ісполня́єть ско́ро вся́коє проше́ніє Твоє́. Ві́дуще таково́є Ма́тернєє дерзнове́ніє к Си́ну Твоєму́, Го́споду на́шему Ісу́су Христу́, всі к Тебі́ прибіга́єм і усе́рдно мо́лим Тя: предста́тельствуй о нас, многогрі́шних рабі́х Твої́х, пред Всемогу́щим Созда́телем на́шим, да не погуби́ть нас со беззако́ньми на́шими, но да пода́сть нам оставле́ніє прегріше́ній, вопію́щим Тебі́ із глубини́ душі́:","Ра́дуйся, предста́тельнице на́ша пред Бо́гом, мир от бід спаса́ющая;","ра́дуйся, Си́на Твоєго́ на ми́лость к нам недосто́йним преклоня́ющая.","Ра́дуйся, от запале́нія о́гненнаго росо́ю моли́тв Твої́х ізбавля́ющая;","ра́дуйся, уда́ри мо́лнії і гро́ма от глави́ на́шея отводя́щая.","Ра́дуйся, юро́дивую му́дрость ві́ка сего́ посрамля́ющая;","ра́дуйся, путь спасе́нія заблу́ждшим показу́ющая.","Ра́дуйся, грі́шним к Бо́гу дерзнове́ніє да́рующая;","ра́дуйся, ізнемога́ющим в напа́стіх, ско́рбіх і іскуше́ніїх ско́ро помога́ющая.","Ра́дуйся, в пості́, моли́тві і богоми́слії пребива́ющим при́сно спребива́ющая;","ра́дуйся, бла́га земна́я, су́єтная і скоропреходя́щая презира́ти нас науча́ющая.","Ра́дуйся, к небе́сним і ві́чним сокро́вищем уми́ і сердця́ на́ша возводя́щая;","ра́дуйся, єди́ноє на потре́бу ізбира́ти науча́ющая.","Ра́дуйся, Благода́тная Ціли́тельнице душ і тіле́с на́ших."]},{"h":"Кондак 5","ps":["Світ небе́сний озари́ хра́мину боля́щаго кли́рика, єгда́ предста́ла єси́, Преблага́я Влади́чице, дарова́ти єму́ ісціле́ніє от лю́таго неду́га. О Пресвята́я Госпоже́ Богоро́дице, просвіти́ помраче́нния мно́гими гріхми́ ду́ші на́ша і пода́ждь ісціле́ніє боле́знующим тілесе́м на́шим, да, прославля́я Твоя́ ми́лості, вопіє́м ра́достно Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще Тя, Влади́чицю Богоро́дицю, пред огнезра́чним Престо́лом Пресвяти́я Тро́йці стоя́щу і за христия́н моля́щуюся, небе́сния си́ли і всі святі́ї от ві́ка Бо́гу угоди́вшії немо́лчними славосло́вії ублажа́ють Тя. Ми же, грі́шнії, на землі́, любо́вію к Тебі́ подвиза́ємії, дерза́єм воспіва́ти Тебі́ си́це:","Ра́дуйся, Ма́тернею любо́вію весь мир христия́нський об'є́млющая;","ра́дуйся, моли́твами Твої́ми к Си́ну Твоєму́ і Бо́гу нас спаса́ющая.","Ра́дуйся, ізря́дная спобо́рнице веду́щим брань проти́ву іскуше́ній мирськи́х і душевре́дних;","ра́дуйся, наста́внице цілому́дрія і воздержа́нія.","Ра́дуйся, всіх, прибіга́ющих под кров Твой, приє́млющая;","ра́дуйся, от вся́кия зло́би і вражди́ ми́ром і любо́вію огражда́ющая.","Ра́дуйся, подви́жников благоче́стія ко го́рнему Ієрусали́му путеводи́тельнице;","ра́дуйся, душепа́губних єресе́й і раско́лов іскорени́тельнице.","Ра́дуйся, ско́рая в біда́х і печа́ліх Уті́шительнице;","ра́дуйся, всіх ві́рних блага́я Засту́пнице.","Ра́дуйся, Благода́тная Ціли́тельнице душ і тіле́с на́ших."]},{"h":"Кондак 6","ps":["Пропові́дуєть Свята́я Правосла́вная Це́рков мно́жество чуде́с Твої́х і вели́кия Твоя́ ми́лості, Преблага́я Влади́чице, я́ко гра́ди і ве́сі огражда́єши, оби́телі і́ночеськия і жили́ща благочести́вих защища́єши, оби́димих заступа́єши і вся блага́я і душеполе́зная низпосила́єши всім прославля́ющим Тя і пою́щим Си́ну Твоєму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Сві́тло красу́ється, Госпоже́ Богоро́дице, чудотво́рная Твоя́ іко́на, імену́ємая Ціли́тельниця, прогоня́ющи от всіх ві́рних тьму іскуше́ній і напа́стей і оби́льно ісціле́нія істоча́ющи. Сего́ ра́ди во умиле́нії зове́м Ті:","Ра́дуйся, от неісці́льних болі́зней ско́роє ісціле́ніє подаю́щая;","ра́дуйся, от вся́ких бід і скорбе́й ізбавля́ющая.","Ра́дуйся, гріхо́вния стра́сті укроща́ющая;","ра́дуйся, коле́блющихся во ві́рі правосла́вній укріпля́ющая.","Ра́дуйся, утіше́ніє благода́тноє в сердця́ боголюби́вия ізлива́ющая;","ра́дуйся, наде́ждою небе́сних благ ві́рних ду́ші услажда́ющая.","Ра́дуйся, в до́брих ді́ліх преуспіва́ти нам помога́ющая;","ра́дуйся, от ви́димих і неви́димих враг нас защища́ющая.","Ра́дуйся, благода́тію Твоє́ю па́дших возставля́ющая;","ра́дуйся, страх Бо́жий в сердця́ на́ша вселя́ющая.","Ра́дуйся, Благода́тная Ціли́тельнице душ і тіле́с на́ших."]},{"h":"Кондак 7","ps":["Хотя́щи яви́ти милосе́рдіє Твоє́ неізрече́нноє, дарова́ла єси́ нам, преблага́я Богоро́дице Ді́во, чудотво́рную іко́ну Твою́, імену́ємую Ціли́тельниця, да всі, притека́ющії к ней с ві́рою, от болі́зней свобожда́ються і вся́каго утіше́нія сподобля́ються. Сего́ ра́ди вопіє́м о Тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вна і пресла́вна діла́ Твоя́, Пренепоро́чная Влади́чице: всім бо, бога́тим і ни́щим, здра́вим і боля́щим, с прилі́жною моли́твою к цільбоно́сній іко́ні Твоє́й притека́ющим, вся блага́я по коєго́ждо потре́бі і в мі́ру ві́ри і любве́ подає́ши. Ті́мже і ми не таї́м Твої́х благодія́ній, но, благода́рственно прославля́юще ми́лості Твоя́, глаго́лем Ті си́це:","Ра́дуйся, глухи́х сли́шаніє;","ра́дуйся, сліпи́х прозрі́ніє.","Ра́дуйся, німи́х глаго́ланіє;","ра́дуйся, хроми́х хожде́ніє.","Ра́дуйся, прокаже́нних очище́ніє;","ра́дуйся, разсла́бленних укріпле́ніє.","Ра́дуйся, от злих і лука́вих духо́в свобожде́ніє;","ра́дуйся, по Бо́зі на́ше прибі́жище і заступле́ніє.","Ра́дуйся, от нужд, печа́лей і бід непрело́жноє ізбавле́ніє;","ра́дуйся, пристра́стіє к тлі́нному бога́тству іскореня́ющая.","Ра́дуйся, іска́ти бога́тство нетлі́нноє на небесі́ науча́ющая;","ра́дуйся, ум наш в го́рняя вперя́ющая.","Ра́дуйся, Благода́тная Ціли́тельнице душ і тіле́с на́ших."]},{"h":"Кондак 8","ps":["Стра́нники і прише́льці в ми́рі сем ско́рбнем і многом'яте́жнім су́ще, ві́чнаго Небе́снаго Оте́чества взиску́єм і Тебі́, всемо́щную Цари́цю Присноді́ву Богоро́дицю, смире́нно про́сим: путево́дствуй нас по стезя́м спаси́тельних за́повідей Си́на Твоєго́, Христа́ Бо́га на́шего, да, ізбі́гше сіте́й неви́димаго врага́, возмо́жем невозбра́нно воспіва́ти Вседержи́телю Бо́гу піснь: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь мир христия́нський ублажа́єть Тя, Пренепоро́чную Ді́ву, гла́си хвале́бними: всім бо ві́рним, найпа́че же боля́щим, уті́шительно єсть взира́ти на всечестну́ю іко́ну Твою́, Ціли́тельниця імену́ємую. О Пречу́дная Госпоже́ Богоро́дице, прийми́ і на́ша умиле́нная благохвале́нія такова́я:","Ра́дуйся, Ра́досте на́ша;","ра́дуйся, добро́то несказа́нная.","Ра́дуйся, висото́ доброді́телей;","ра́дуйся, глубино́ смиренному́дрія.","Ра́дуйся, неістощи́мий істо́чниче ми́лостей і щедро́т;","ра́дуйся, благоуха́нний Цві́те ді́вства і чистоти́.","Ра́дуйся, ві́ри христия́нськия утвержде́ніє;","ра́дуйся, нече́стія обличе́ніє.","Ра́дуйся, го́рніх сил похвало́;","ра́дуйся, всіх пра́ведних сла́во.","Ра́дуйся, всіх грі́шних упова́ніє;","ра́дуйся, ненаді́ємих наді́яніє.","Ра́дуйся, Благода́тная Ціли́тельнице душ і тіле́с на́ших."]},{"h":"Кондак 9","ps":["Все упова́ніє на Тя возлага́єм, Ма́ти Бо́жия, і в ско́рбіх і болі́зніх ко святі́й іко́ні Твоє́й с благогові́нієм і ві́рою притека́єм, ча́юще от нея́ ско́роє утіше́ніє і ісціле́ніє получи́ти. О Пресвята́я Цари́це Богоро́дице, воззри́ ми́лостивно на нас, смире́нних рабо́в Твої́х, і ускори́ іспо́лнити вся, я́же на по́льзу нам, і в сей жи́зні і в бу́дущей, да, прославля́я Твоє́ благоутро́біє, воспіва́єм Творцю́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії не возмо́гуть досто́йно восхвали́ти Тя, Пречи́стую Ді́ву, честні́йшую херуви́м і сла́внійшую без сравне́нія серафи́м, безсі́менно ро́ждшую Спа́са душ на́ших. Ми же, а́ще і не́мощни єсьми́, оба́че, любо́вію к Тебі́ побіжда́ємі, отверза́єм недосто́йния уста́ своя́ на похвали́ Тебі́ сицеви́я:","Ра́дуйся, уми́ челові́чеськими і а́нгельськими непостижи́мая та́йно;","ра́дуйся, чистото́ю А́нгелов превозше́дшая.","Ра́дуйся, чуде́с Христо́вих нача́ло;","ра́дуйся, всіх проро́честв ісполне́ніє.","Ра́дуйся, ді́вство і рождество́ в себі́ чу́дно сочета́вшая;","ра́дуйся, во обою́ непоро́чно і свя́то Себе́ сохра́ньшая.","Ра́дуйся, Ма́ти Си́на Бо́жия і Бо́га Ви́шняго;","ра́дуйся, па́дшему челові́честву отве́рзшая вход в ца́рствіє го́рнєє.","Ра́дуйся, ти́хоє приста́нище от бур пла́вающим по мо́рю жите́йському;","ра́дуйся, Бо́гом дарова́нная отра́до стра́ждущим.","Ра́дуйся, сія́ющая благода́тію і сла́вою преди́вних зна́меній і чуде́с;","ра́дуйся, приє́млющая похвале́ніє людськи́х слове́с.","Ра́дуйся, Благода́тная Ціли́тельнице душ і тіле́с на́ших."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ род челові́чеський от беззако́ній і ві́чния му́ки человіколю́бець Госпо́дь, Тя, Ма́тер Свою́, дарова́ в по́мощ, покро́в і защи́ту ві́рующим в Него́. Прославля́юще таково́є Созда́теля на́шего безмі́рноє милосе́рдіє о нас, грі́шних, благода́рственним се́рдцем і усти́ вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ необори́мая і заступле́ніє крі́пкоє, Богоро́дице Ді́во, всім с моли́твою к Тебі́ прибега́ющим. Ті́мже у́бо і нас, недосто́йних, огради́ от лю́тих болі́зней і от вся́каго зла́го обстоя́нія і пода́ждь во всіх ді́ліх благовре́менную по́мощ і укріпле́ніє взива́ющим Ті:","Ра́дуйся, Засту́пнице на́ша і похвало́;","ра́дуйся, Храни́тельнице на́ша і утвержде́ніє.","Ра́дуйся, Отра́до на́ша і ди́вноє о нас попече́ніє;","ра́дуйся, ізві́стноє прибі́жище на́ше во всіх ско́рбних обстоя́ніїх.","Ра́дуйся, младе́нцев воспита́ніє;","ра́дуйся, ю́них наста́внице цілому́дрія.","Ра́дуйся, супру́гом любо́в і согла́сіє да́рующая;","ра́дуйся, благогові́йних ста́рцев к ми́рной кончи́ні житія́ приводя́щая.","Ра́дуйся, ві́рних па́стирей Святи́я Це́ркве укріпля́ющая і вразумля́ющая;","ра́дуйся, в і́ночеськом о́бразе подвиза́ющимся хода́тайце ві́чнаго ра́дованія.","Ра́дуйся, в ми́рі благочести́во живу́щих не оставля́ющая Свої́м заступле́нієм;","ра́дуйся, всім христия́ном преди́вноє вспоможе́ніє.","Ра́дуйся, Благода́тная Ціли́тельнице душ і тіле́с на́ших."]},{"h":"Кондак 11","ps":["Пі́нія і мольби́ всеумиле́нния, ни́ні на́ми приноси́мия пред цільбоно́сним Твої́м о́бразом, прийми́, Присноді́во Богоро́дице, і сподо́би до конця́ жи́зні на́шея Єди́ному Бо́гу воспіва́ти: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рне сія́єть чудотво́рная іко́на Твоя́, Ма́ти Бо́жия, істоча́ющи ві́рним то́ки ісціле́ній благода́тних і наставля́ющи блужда́ющих во тьмі гріхо́в на сві́тлий путь доброді́телей і спасе́нія. Сего́ ра́ди вопіє́м Ті хвале́бния пі́сні такови́я:","Ра́дуйся, осіне́нієм Твоєя́ іко́ни си́лу вра́жию от всіх прогоня́ющая;","ра́дуйся, всім прибега́ющим в ско́рбіх, ну́ждах і болі́зніх ско́роє утіше́ніє і ісціле́ніє подава́ющая.","Ра́дуйся, чу́до чуде́с, Одиги́тріє Влади́чице, на путь спасе́нія наставля́ющая;","ра́дуйся, ми́рноє устроє́ніє обурева́ємим напа́стьми да́рующая.","Ра́дуйся, чистото́ю Твоє́ю чи́стому житію́ нас науча́ющая;","ра́дуйся, лука́вих, го́рдих і гнівли́вих люде́й вразумля́ющая.","Ра́дуйся, пра́вую ві́ру і страх Бо́жий в нас вселя́ющая;","ра́дуйся, сві́том Христо́ва уче́нія тьму неві́рія прогоня́ющая.","Ра́дуйся, смуще́нія помишле́ній сумни́тельних удаля́ющая;","ра́дуйся, всіх духо́вних даро́в ще́драя пода́тельнице.","Ра́дуйся, благоче́стія наста́внице;","ра́дуйся, ми́ра хода́тайце.","Ра́дуйся, Благода́тная Ціли́тельнице душ і тіле́с на́ших."]},{"h":"Кондак 12","ps":["Благода́тію і щедро́тами Твої́ми, Премилосе́рдая Влади́чице, не оставля́єши христия́н правосла́вних, да́рующи скорб'я́щим утіше́ніє, оби́димим заступле́ніє, боля́щим ісціле́ніє і всім су́щим в біда́х многоразли́чних ізбавле́ніє; сего́ ра́ди, прославля́юще Тя, благода́рственно вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоя́ неізрече́нния ми́лості і чудеса́, явля́ємая нам недосто́йним, преклоня́єм колі́на пред цільбоно́сним Твої́м о́бразом, Богоро́дице Присноді́во, і мо́лим Тя усе́рдно: пода́ждь нам мир, тишину́ і благу́ю христия́нськую кончи́ну і не оста́ви без Твоєя́ по́мощі і заступле́нія во второ́м прише́ствії Си́на Твоєго́ і Бо́га на́шего всіх принося́щих Ті со умиле́нієм сія́ похвали́:","Ра́дуйся, в уни́ніє і отча́яніє впа́дших наде́ждою спасе́нія укріпля́ющая;","ра́дуйся, у́зи гріхо́вния разріша́ющая.","Ра́дуйся, пра́ведний на нас гнів Бо́жий на ми́лость прелага́ющая;","ра́дуйся, земно́є житіє́ на́ше до́брі устроя́ющая.","Ра́дуйся, от опа́сних обстоя́ній нас ізбавля́ющая;","ра́дуйся, в час кончи́ни всім ві́рним ско́рая Помо́щнице.","Ра́дуйся, чту́щих Тя на мита́рствах возду́шних заступа́ющая;","ра́дуйся, любо́в к Тебі́ іму́щим врата́ ра́йськая отверза́ющая.","Ра́дуйся, прославля́ющих Тя ві́чнаго блаже́нства в Ца́рствії Небе́снім сподобля́ющая;","ра́дуйся, не чту́щих Тя пред всі́ми посрамля́ющая.","Ра́дуйся, держа́вная Скоропомо́щнице на́ша во дні тя́жких іспита́ній;","ра́дуйся, я́ко во дні сві́тлия нам сора́дуєшися.","Ра́дуйся, Благода́тная Ціли́тельнице душ і тіле́с на́ших."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти сладча́йшаго Го́спода на́шего Ісу́са Христа́, ми́лостивно прийми́ сіє́ ма́лоє моле́ніє на́ше, ізба́ви нас от вся́кия напа́сти, болі́зні і внеза́пния сме́рти і сподо́би нас наслі́дниками би́ти Ца́рствія Небе́снаго і со всі́ми святи́ми воспіва́ти Си́ну Твоєму́ і Бо́гу на́шему: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгел Гавриї́л, возвіща́я Пресвяті́й Ді́ві Марі́ї безсі́менноє зача́тіє от Нея́ Си́на Бо́жия, рече́: «Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю, благослове́нна Ти в жена́х»; ми же, грі́шнії, гла́су Арха́нгелову подража́ти дерза́юще, с ві́рою, любо́вію і благогові́нієм вопіє́м пі́нія сицева́я:","Ра́дуйся, от нача́ла віко́во во главу́ на́шего спасе́нія предизбра́нная;","ра́дуйся, многообра́зні от проро́ков предвозвіще́нная.","Ра́дуйся, Неві́сто Неневі́стная, заче́ншая Си́на от Ду́ха Свята́го;","ра́дуйся, Ма́ти, в рождестві́ і по рождестві́ преби́вшая Ді́во.","Ра́дуйся, Оді́ющагося сві́том, я́ко ри́зою, пелена́ми пови́вшая;","ра́дуйся, млеко́м пита́вшая го́рняя і до́льняя благода́тію Своє́ю Пита́ющаго.","Ра́дуйся, на руку́ Твоє́ю носи́вшая Вседержи́теля;","ра́дуйся, о Промисли́телі всея́ тва́рі попече́ніє імі́вшая.","Ра́дуйся, па́че всіх Си́на Твоєго́ возлюби́вшая;","ра́дуйся, па́че всіх от Него́ превознесе́нная.","Ра́дуйся, честні́йшая і сла́внійшая без сравне́нія всіх Небе́сних Сил;","ра́дуйся, преви́шшая вся́каго созда́нія.","Ра́дуйся, Благода́тная Ціли́тельнице душ і тіле́с на́ших."]},{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Пресвяті́й Ді́ві Богоро́диці, яви́вшейся іногда́ кли́рику боля́щу, во є́же ісціли́ти єго́ от болі́зні лю́тия, похва́льноє прино́сим пі́ніє. Ти же, Всеми́лостивая Влади́чице, я́ко іму́щая держа́ву непобіди́мую, от вся́ких бід і скорбе́й, і болі́зней свободи́ ни, зову́щия Ті:","Ра́дуйся, Благода́тная Ціли́тельнице душ і тіле́с на́ших."]},{"h":"Молитва","ps":["О Пресвята́я Госпоже́ Цари́це Богоро́дице, ви́сшая всіх небе́сних сил і святі́йшая всіх святи́х! Припа́даєм і покланя́ємся Тебі́ пред всечестни́м і цільбоно́сним о́бразом Твої́м, воспомина́юще ди́вноє явле́ніє Твоє́ боля́щему кли́рику Вике́нтію, і усе́рдно мо́лим Тя, всеси́льную ро́да на́шего засту́пницю і помо́щницю: я́коже дре́вле подала́ ісціле́ніє тому́ кли́рику, та́ко і ни́ні ісціли́ на́ша ду́ші і тілеса́, боле́знующия ра́нами гріхо́в і страсте́й многоразли́чних, ізба́ви нас от вся́ких напа́стей, бід, скорбе́й і ві́чнаго осужде́нія, сохрани́ от душепа́губних уче́ній і безве́рія, от льсти́вих і на́глих нападе́ній неви́димих враго́в, пода́ждь нам христия́нськую кончи́ну, безболі́зненну, ми́рну, непости́дну, Святи́х Та́їн прича́стну. І сподо́би нас на нелицеприя́тнім суди́щі Христо́ві ста́ти одесну́ю Всепра́веднаго Судії́ і блаже́нний глас Єго́ усли́шати: «Прийді́те, благослове́ннії Отця́ Моєго́, наслі́дуйте угото́ванноє вам Ца́рствіє от сложе́нія ми́ра». Амі́нь."]},{"h":"Тропар, глас 1","ps":["Любо́вію, Чи́стая Ді́во,Твою́ святу́ю іко́ну почита́ющим, / і Бо́жию Тя і́стинную Ма́тер прославля́ющим, / і ві́рно поклоня́ющим Ті ся / Ціли́тельниця яви́ся, / вся́коє зло і болі́зні от сих удаля́ющая, // я́ко Всемогу́щая."]},{"h":"Інший тропар, глас 4","ps":["Я́ко пресві́тлая звізда́, просія́ Боже́ственними чудеси́ святи́й Твой о́браз, Ціли́тельнице. Пода́ждь у́бо і нам, Богоро́дице Марі́є, ісціле́ніє неду́гов душе́вних і тіле́сних, спасе́ніє і ве́лію ми́лость."]},{"h":"Кондак, глас 6","ps":["Предста́тельство христия́н непости́дноє, хода́тайство ко Творцю́ непрело́жноє, не пре́зри грі́шних моле́ній гла́си, но предвари́, я́ко Блага́я, на по́мощ нас, ві́рно зову́щих Ті; ускори́ на моли́тву і потщи́ся на умоле́ніє, предста́тельствующи при́сно, Богоро́дице, чту́щих Тя."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Милостива»","e":"Akathist to the Theotokos before her icon “The Merciful”","secs":[{"h":"Кондак 1","ps":["Ізбра́нная от всіх родо́в Ді́во Ма́ти Го́спода Бо́га Ви́шняго, в лучеза́рней сла́ві Небе́сній преви́ше Херуви́мов і Серафи́мов Цари́це Влади́чице, приклони́ ми́лость Твою́ к нам грі́шним, утоли́ печа́ль серде́ць на́ших; простри́ над на́ми покро́в Твой честни́й, посіти́ ско́рбную жизнь на́шу, не і́мами бо іни́я по́мощі, не і́мами бо іни́я наде́жди ра́зві Тебе́, Ма́ти ро́да на́шего. В стра́хі і в тре́петі пред вели́чієм милосе́рдія Твоєго́, коленопрекло́ньше, хода́тайства Твоєго́ пред безсме́ртним Си́ном Твої́м про́сим, со умиле́нієм зову́ще:","Ра́дуйся, Ми́лостивая Ма́ти Бо́жия, ми́лості Твоя́ на нас ізлива́ющая."]},{"h":"Ікос 1","ps":["Арха́нгел благові́стник с Небесе́ по́слан бисть пра́ведному Іоаки́му ра́дость рождества́ твоєго́ возвісти́ти, і возра́довавшеся ста́рець святи́й, вели́чіє Твоє́ в ми́рі Бо́жиєм прови́дя, ті́мже і ми Богоро́дице, с ним ра́достно вопіє́м Тебі́:","Ра́дуйся, всего́ ми́ра Влади́чице;","ра́дуйся, А́нгелов цари́це.","Ра́дуйся, Пречи́стая;","ра́дуйся, всіх цвіто́в благоуха́ннейшая.","Ра́дуйся, любвеоби́льная;","ра́дуйся, кро́тости і милосе́рдію науча́ющая.","Ра́дуйся, покро́в Твой святи́й над всі́ми на́ми простира́ющая;","ра́дуйся, Ді́во світоза́рная.","Ра́дуйся, Ми́лостивая Ма́ти Бо́жия, ми́лості Твоя́ на нас ізлива́ющая."]},{"h":"Кондак 2","ps":["Ви́дяще Тя на о́блаціх, честни́й покро́в Твой простира́ющую, і тім нас соблюда́ющую, благода́рственно вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум наш обурева́ємий плотськи́ми помишле́ніями, око́ви земни́я сокруши́ти тща́шеся. Немощни́я і ліни́вия во греха́х на́ших валя́ємся, но сле́зно к Твоєму́ милосе́рдію взива́єм: воздви́гни із бе́здни гріхо́вния, наста́ви нас на путь спасе́нія, да со а́нгели Тебі́, Ма́ти Пречи́стая, прославля́єм:","Ра́дуйся, покро́ве на́ше і спасе́ніє;","ра́дуйся, ко благоче́стію нас наставля́єши.","Ра́дуйся, грі́шников моли́твеннице;","ра́дуйся, воздиха́ній на́ших не отверга́ющая;","Ра́дуйся, на́ші сле́зи утира́ющая;","ра́дуйся, Ма́ти милосе́рдія.","Ра́дуйся, Живоприє́мний Істо́чниці;","ра́дуйся, мно́гіє не́мощі на́ші ісціля́ющая.","Ра́дуйся, Ми́лостивая Ма́ти Бо́жия, ми́лості Твоя́ на нас ізлива́ющая."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго храня́ше Тя, єгда́ младе́нчеськими стопа́ми твори́ла єси́ восхожде́ніє лі́ствиці хра́ма Госпо́дня і ми, грі́шнії, упова́я на Ма́тернюю ми́лость Твою́, го́рестно мо́лим: возведи́ нас по лі́ствице спасе́нія; да прибли́зимся ко Престо́лу сла́ви Бо́жия, благода́рственно зову́щи: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще се́рдце всіх дів чисті́йшеє і ра́зум, устремле́нний в Го́рнеє, Ді́во Марі́є, в хра́мі Бо́жиєм пребива́юще, о земно́м не помишля́я, все существо́ своє́ к восприя́тію Царя́ царе́й пригото́вила єси́. Си́ли Небе́сния пред чистото́ю Твоє́ю преклоня́ються, і весь род челові́чеський ра́достную піснь Тебі́ возсила́єть:","Ра́дуйся, Пречи́стая Ді́во всіх дів чисті́йшая;","ра́дуйся, ра́зум плотськи́м гріхо́м не повреди́вшая.","Ра́дуйся, кро́ткая лампа́да всему́ ми́ру сія́ющая;","ра́дуйся, се́рдце Твоє́ всіх серде́ць чисті́йшеє.","Ра́дуйся, Богоізбра́нная отрокови́це;","ра́дуйся, красото́ неізрече́нная і неопи́санная.","Ра́дуйся, украше́ніє всего́ Не́ба і землі́;","ра́дуйся, всім святи́м ра́дость.","Ра́дуйся, Ми́лостивая Ма́ти Бо́жия, ми́лості Твоя́ на нас ізлива́ющая."]},{"h":"Кондак 4","ps":["Бу́ри отча́янниє в сердця́х на́ших претерпіва́я, во греха́х житіє́ своє́ іжди́вшії к Тебі́, Богоро́дице прибіга́єм і смире́нно мо́лим: пода́й нам си́лу ду́ха, пода́й нам кро́тость і смире́ніє, терпі́ніє і му́дрость к перенесе́нію всіх скорбе́й на́ших, да воспої́м Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Смиренному́дренно Ти приняла́ благу́ю вість арха́нгелом Гавриї́лом принесе́нную і, уразумі́в час сей святи́й, рекла́ єси́: «Се раба́ Госпо́дня, бу́ди мі по глаго́лу Твоєму́», – о, Пресвята́я Ді́во, научи́ і нас храни́ти поко́рность во́лі Бо́жієй і безро́потно перенести́ низпосила́ємия нам Бо́гом іспита́нія, да очи́стяться ду́ші на́ша огне́м страда́ній; да ізмету́ться із серде́ць на́ших вся скве́рни гріхо́в на́ших; восста́нем бо́дри і чи́сти се́рдцем, возсила́я Бо́гу благода́рственния восхвале́нія: благодари́м Тя Бо́же, Царю́ Небесі́ і землі́, вся прему́дростію Твоє́ю стро́яй і сокрове́нная челові́ков я́ві предві́дий, се досто́йноє по діло́м на́шим приє́млем. Да бу́деть над на́ми свята́я во́ля Твоя́. Тебі́ же, Преблагослове́нная Ді́во, Бо́га всіх ро́ждшая, умиле́нно прославля́єм:","Ра́дуйся, смире́нная раба́ Госпо́дня;","ра́дуйся, нас приме́ром Свої́м ободря́ющая.","Ра́дуйся, Ді́во Пресвята́я;","ра́дуйся, ю́ность Свою́ Бо́гу посвяти́вшая.","Ра́дуйся, кро́тость неізглаго́ланная;","ра́дуйся, столп ві́ри непоколеби́мий.","Ра́дуйся, упова́ніє всіх конце́в землі́;","ра́дуйся, любві́ мо́ре неізмери́моє.","Ра́дуйся, Ми́лостивая Ма́ти Бо́жия, ми́лості Твоя́ на нас ізлива́ющая."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ волхва́м на небесі́ яви́вшася, і ди́вним верте́п озари́вшая, показа́ Царя́ сла́ви в я́сліх лежа́ща; і с ним Ма́тер Єго́, Ді́ву чи́стую і святу́ю, в се́рдці Своє́м пі́сні а́нгелом слага́ющую. О, Ді́во кро́тости і смире́нія, вознеси́ Го́споду і на́ше славосло́віє: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще волхви́ сла́ву предві́чнаго младе́нця Христа́, нас ра́ди пло́тію ро́ждшагося, возда́ли Єму́ Бо́жеськоє поклоне́ніє. А́нгел же Госпо́день ста́рцю Іо́сифу яви́ся, повелі́в безсме́ртноє Отроча́ і Ма́тер Єго́ во Єги́пет от я́рости І́родовой спасти́. Со умиле́нієм помишля́я, Богоро́дице, о многотру́дном путі́ Твоє́м, ми, грі́шнії, смире́нно к Тебі́ прибіга́єм: облегчи́ наш земни́й путь, скорб'я́ми іспо́лненний, подими́ па́дающих ду́хом, поддержи́ сла́бих і боля́щих, простри́ ру́ку спасе́нія унива́ющим, укріпи́ Правосла́віє в страні́ на́шей, кро́вію істека́ющеє. О, Пресвята́я, Всепі́тая Ді́во Богоро́дице, бу́ди ми́лостива ни́ні к нам грі́шним о греха́х свої́х пла́чущим; умоли́ Си́на Твоєго́ ізли́ти ми́лость Єго́ на нас грі́шних і немощни́х: да ра́достно во умиле́нії серде́ць на́ших вопіє́м Тебі́:","Ра́дуйся, Богоро́дице, матери́нськия ско́рби утоля́ющая;","ра́дуйся, вдови́ць і си́рих покрива́ющая.","Ра́дуйся, люде́й Твої́х спасе́ніє;","ра́дуйся, моли́твенников похвало́.","Ра́дуйся, ста́рцев утіше́ніє;","ра́дуйся, ю́ности ободре́ніє.","Ра́дуйся, убо́гих призрі́ніє;","ра́дуйся, всему́ ми́ру весе́ліє.","Ра́дуйся, Ми́лостивая Ма́ти Бо́жия, ми́лості Твоя́ на нас ізлива́ющая."]},{"h":"Кондак 6","ps":["Про́повідь любві́, кро́тости і всепроще́нія ми́рові возвіща́ющая со Христо́м, Си́ном Твої́м, все го́рести земни́є претерпі́вшая. Апо́стола Іоа́нна і с ним весь род христия́нський Своєму́ матери́нському се́рдцю усинови́вшая. О, Присноді́ва Пренепоро́чная, бу́ди нам Ма́терію на́шею Небе́сною, утіше́нія і матери́нськаго тепла́ нужда́ющихся, да со благодаре́нієм зове́м Го́споду: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́вши всей вселе́нній, я́ко ди́вний благоуха́нний храм Бо́жий, іспо́лненний Боже́ственния сла́ви і благода́ті, о, Ді́во Ма́ти Пречи́стая, Цари́ця Небе́сная, Цари́ця челові́ков і а́нгелов, апо́столов і му́чеников; бу́ди і нам путево́дною звіздо́ю во мра́кі ско́рбних дній на́ших, возвесели́ сердця́ на́ша, тьмо́ю страсте́й об'я́тия; возста́ви си́ли на́ші во страстя́х ізся́кшия; умно́жи ві́ру на́шу, укріпи́ наде́жду на́шу і согрі́й огне́м пла́менния любві́ ожесточе́нния і озло́бленния ду́ші на́ша, да зове́м Ті со умиле́нієм:","Ра́дуйся, Ма́ти ро́да христия́нського;","ра́дуйся, страни́ на́шея защи́тнице.","Ра́дуйся, призива́ющим Тя ско́рая помо́щнице;","ра́дуйся, грі́шников упова́ніє.","Ра́дуйся, пра́ведних весе́ліє;","ра́дуйся, па́че всіх світи́л сія́ющая.","Ра́дуйся, єди́на благослове́нная.","Ра́дуйся, Ми́лостивая Ма́ти Бо́жия, ми́лості Твоя́ на нас ізлива́ющая."]},{"h":"Кондак 7","ps":["Хотя́щи с Си́ном твої́м єдиноро́дним до кре́стния сме́рті неразлу́чно би́ти, Ти возпосле́довала єси́ неви́нному Страда́льцю до са́мия Голго́фи і у подно́жія Креста́ сли́шала во́пли со́нмища раз'яре́нного, і в молча́нії страда́ла єси́. І Тебі́ само́й ду́шу Твою́ напо́лни сія́ скорб вели́кая. Ми же, удивля́яся Твоєму́ неізрече́нному матери́нському му́жеству, зове́м: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую вість арха́нгел Госпо́день возвісти́ Тебі́, Богоро́дице, о Воскресе́нії Си́на Твоєго́; с ним же і вся во́їнства Небе́сния велегла́сно сла́в'ять безсме́ртнаго Христа́. Сподо́би і нас, Христе́ Бо́же, сра́доватися ни́ні Ма́тері Твоє́й, умиле́нно восклиця́я:","Ра́дуйся, Благода́тная, я́ко Госпо́дь с Тобо́ю;","ра́дуйся, Ді́во чи́стая.","Ра́дуйся, сла́ва бо Госпо́дня на Тебі́ возсія́;","ра́дуйся, о возста́нії Рождества́ Твоєго́.","Ра́дуйся, незаходи́мая заря́ І́стини;","ра́дуйся, путево́дная звізда́.","Ра́дуйся, к пра́вді Бо́жієй веду́щая нас;","ра́дуйся, ду́ші на́ші умиротворя́ющая.","Ра́дуйся, Ми́лостивая Ма́ти Бо́жия, ми́лості Твоя́ на нас ізлива́ющая."]},{"h":"Кондак 8","ps":["Вели́коє і пресла́вноє та́їнство вознесе́нієм Твої́м, Христе́ Бо́же, ми́ру яви́вий і одесну́ю Бо́га Отця́ сідя́й і нам, живу́щим на землі́, о селе́ніях ра́йських скорб'я́щим, низпосли́ Уті́шителя, Ду́ха І́стини і всели́ в ни, Жизнода́вче, моли́твами Ма́тері Твоєя́, да зове́м: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь наш земни́й путь іспита́ній і скорбе́й преіспо́лненний, но к Тебі́ вопіє́м, Богоро́дице Ді́во, умилосе́рдися над на́ми, Боже́ственная на́ша покрови́тельнице, і приюти́ нас под Твої́м честни́м покро́вом, укріпи́ ста́рцев немощни́х, уврачу́й боля́щих, наси́ти нас а́лчущих, напої́ нас жа́ждущих, воодушеви́ ю́ношей к сві́тлим по́двигам стрем'я́щимся, вразуми́ роди́телей воспита́нію діте́й свої́х, сохрани́ младе́нцев от вся́кия біди́, осіни́ благода́тію Твоє́ю на́ших па́стирей духо́вних, вознеси́ на́ші моли́тви ко Престо́лу Всеви́шняго, да славосло́вим Тя Ма́тер Бо́жию зову́ще:","Ра́дуйся, Отра́да на́ша і утіше́ніє;","ра́дуйся, скорб'я́щих сві́тлая ра́дость.","Ра́дуйся, Ма́ти всім і́щущим спасе́ніє;","ра́дуйся, огражде́ніє ді́вства.","Ра́дуйся, пра́вди Небе́сния побо́рнице;","ра́дуйся, неістощи́мий істо́чниче святи́ні.","Ра́дуйся, благода́тію нас пита́ющая;","ра́дуйся, непреста́нная хода́тайце о душа́х на́ших.","Ра́дуйся, Ми́лостивая Ма́ти Бо́жия, ми́лості Твоя́ на нас ізлива́ющая."]},{"h":"Кондак 9","ps":["«Всяк, і́же призове́ть і́м'я Госпо́днє, спасе́ться, і на вся́ку плоть ізлію́ от Ду́ха Моєго́», –рече́ Госпо́дь. На Тебі́ же, Ма́ти Бо́жия, ізлія́ся благода́ть Свята́го Ду́ха преви́ше вся́кия мі́ри. Зане́ Творця́ і Зижди́теля на́шего вмісти́ла єси́. Ізле́й же і на на́ші стра́ждущия ду́ші ми́лость Си́на Твоєго́, да облегче́нним се́рдцем вопіє́м: Аллилу́я."]},{"h":"Ікос 9","ps":["Святі́ї апо́столи, нічто́ земно́є не помишля́я, с благогові́нієм і тре́петом сла́в'ять пресла́вноє Твоє́ Успе́ніє. Цар бо ца́рствующих і Госпо́дь госпо́дствующих, соше́д на зе́млю, восприя́т святу́ю Твою́ ду́шу, і во вели́кой сла́ві вознесе́ Єя́ на Не́бо, іді́же угото́ва одесну́ю Престо́ла Своєго́ оби́тель Тебі́. Ми же к Твоєму́ милосе́рдію, Богоро́дице, взива́єм: пода́ждь прию́ть нам бездо́мним, собери́ воєди́но всіх нас, пошли́ нам мир і благослове́ніє, да поє́м Тебі́:","Ра́дуйся, нас погиба́ющих спаса́ющая;","ра́дуйся, за нас моля́щаяся.","Ра́дуйся, Боже́ственний покро́в рабо́м Твої́м;","ра́дуйся, люде́й твої́х спасе́ніє.","Ра́дуйся, моли́твенников похвало́;","ра́дуйся, сві́тлий лик Твой от нас не отвраща́ющая.","Ра́дуйся, по Успе́нії Своє́м мир не оставля́ющая;","ра́дуйся, я́ко Тобо́ю род христия́нський хва́литься.","Ра́дуйся, Ми́лостивая Ма́ти Бо́жия, ми́лості Твоя́ на нас ізлива́ющая."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ мир, Па́стир До́брий всіх ко спасе́нію зову́щий і всяк к себі́ привлека́ющий; пра́ведния люб'я́й і грі́шния ми́луяй, спаси́ нас грі́шних моли́твами Богоро́диці, да поє́м: Аллилу́я."]},{"h":"Ікос 10","ps":["Покро́в і предста́тельство всіх ка́ющихся грі́шников, прийми́ і на́ше покая́ніє о, Всеблага́я Ді́во Марі́є, ум'ягчи́ сердця́ на́ша, ісціли́ болі́зненноє блужда́ніє умо́в на́ших, низве́ргни го́рдость на́шу в пучи́ну смире́нія, подими́ го́ре о́чі на́ша, земле́ю ско́ванния; разомкни́ уста́ на́ша, да воспоє́м славосло́віє сіє́:","Ра́дуйся, Живоно́сний Істо́чниче;","ра́дуйся, нас росо́ю живи́тельной окропля́єши.","Ра́дуйся, гла́сом моля́щихся вне́млющая;","ра́дуйся, погиба́ющим ру́ку спасе́нія простира́ющая.","Ра́дуйся, ско́рби челові́чеськой стра́ждущая;","ра́дуйся, я́ко утіше́ніє Твоє́ нам подає́ши.","Ра́дуйся, прекра́сний цві́те ра́йський;","ра́дуйся, двер на́шего спасе́нія.","Ра́дуйся, Ми́лостивая Ма́ти Бо́жия, ми́лості Твоя́ на нас ізлива́ющая."]},{"h":"Кондак 11","ps":["А́нгельськоє пі́ніє сопровожда́єть пра́ведних, отходя́щих после сме́рті. Ка́ко же і ми, грі́шнії, обря́щем спасе́ніє, ка́ко предста́нем пред Судіє́ю пра́ведним; но на Тя, Богоро́дице, наді́ющіїся умиле́нно про́сим: спаси́ Твої́м Матери́нським предста́тельством ду́ші на́ша пою́щия: Аллилу́я."]},{"h":"Ікос 11","ps":["Пою́щи о ми́лості Твоє́й, Благода́тная между́ жена́ми, єди́на благослове́нная, Спаси́теля ми́рові дарова́вшая, і тім ві́чную сла́ву і поклоне́ніє стяжа́вшая, бу́ди хода́тайцею і засту́пницею о нас, грі́шних, і рци Си́ну Твоєму́: Го́споди, покри́й їх ми́лостивим про́мислом Твої́м і іспо́лни їх сердца́ ра́дости і утіше́нія, ми же благода́рнії Тебе́, Влади́чице, восклиця́єм:","Ра́дуйся, Сві́те Небе́сний неугаси́мий;","ра́дуйся, із Тебе́ бо возсія́ Со́лнце пра́вди, Христо́с Бог наш.","Ра́дуйся, непостижи́мая та́йна Боговоплоще́нія;","ра́дуйся, невмісти́маго Бо́га вмісти́вшая.","Ра́дуйся, одесну́ю Бо́га Си́на Твоєго́ сідя́щая;","ра́дуйся, Сил Небе́сних преви́сшая.","Ра́дуйся, прости́х умо́в утіше́ніє;","ра́дуйся, возводя́щая грі́шников на Не́бо.","Ра́дуйся, Ми́лостивая Ма́ти Бо́жия, ми́лості Твоя́ на нас ізлива́ющая."]},{"h":"Кондак 12","ps":["Благода́ть Си́на Твоєго́ ми́рові яви́ла єси́ Присноді́во Пренепоро́чная, спаси́ і нас грі́шних, зову́щих о ми́лості Твоє́й: Аллилу́я."]},{"h":"Ікос 12","ps":["О, Всеми́лостивая Ма́ти Бо́жия, Ти ізлива́єши Матери́нськую любо́в Твою́ на всіх к Тебі́ притека́ющих, і на́ші сердца́ любо́вію Твоє́ю наполня́єши. Ка́ко ми, грі́шнії, возблагодари́м Теб'я́ за Твої́ неізрече́нния ми́лости к нам недосто́йним ді́тем Твої́м; дай нам с благогові́нієм і со смире́нієм воспі́ти Тебі́:","Ра́дуйся, сердца́ на́ші любо́вію соєдиня́ющая;","ра́дуйся, єди́ними усти́ і єди́ним се́рдцем пі́ти Си́на Твоєго́ нас науча́ющая.","Ра́дуйся, умиле́ніє і ра́дость в ду́ші на́ша ізлива́ющая;","ра́дуйся, і ненави́дящих нас возлюби́ти науча́ющая.","Ра́дуйся, любо́вію ду́ші на́ша от гріхо́в і болі́зней очища́ющая;","ра́дуйся, на Тебі́ бо на́ше упова́ніє.","Ра́дуйся, і на землі́ ра́йськоє блаже́нство лю́б'ящим Тя подаю́щая;","ра́дуйся, благода́тную сла́дость в сердця́ моля́щихся Тебі́ влага́єши.","Ра́дуйся, Ми́лостивая Ма́ти Бо́жия, ми́лості Твоя́ на нас ізлива́ющая."]},{"h":"Кондак 13","ps":["О, всепі́тая Ма́ти, о Ма́ти благода́ті іспо́лненная. Прийми́ на́ші сле́зния моли́тви к Тебі́, є́же в ни́нішнєє вре́м'я на милосе́рдіє Твоє́ дерза́юще, із глубини́ душе́вния Тебі́ прино́сим піснь: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгел благові́стник с Небесе́ по́слан бисть пра́ведному Іоаки́му ра́дость рождества́ твоєго́ возвісти́ти, і возра́довавшеся ста́рець святи́й, вели́чіє Твоє́ в ми́рі Бо́жиєм прови́дя, ті́мже і ми Богоро́дице, с ним ра́достно вопіє́м Тебі́:","Ра́дуйся, всего́ ми́ра Влади́чице;","ра́дуйся, А́нгелов цари́це.","Ра́дуйся, Пречи́стая;","ра́дуйся, всіх цвіто́в благоуха́ннейшая.","Ра́дуйся, любвеоби́льная;","ра́дуйся, кро́тости і милосе́рдію науча́ющая.","Ра́дуйся, покро́в Твой святи́й над всі́ми на́ми простира́ющая;","ра́дуйся, Ді́во світоза́рная.","Ра́дуйся, Ми́лостивая Ма́ти Бо́жия, ми́лості Твоя́ на нас ізлива́ющая."]},{"h":"Кондак 1","ps":["Ізбра́нная от всіх родо́в Ді́во Ма́ти Го́спода Бо́га Ви́шняго, в лучеза́рней сла́ві Небе́сній преви́ше Херуви́мов і Серафи́мов Цари́це Влади́чице, приклони́ ми́лость Твою́ к нам грі́шним, утоли́ печа́ль серде́ць на́ших; простри́ над на́ми покро́в Твой честни́й, посіти́ ско́рбную жизнь на́шу, не і́мами бо іни́я по́мощі, не і́мами бо іни́я наде́жди ра́зві Тебе́, Ма́ти ро́да на́шего. В стра́хі і в тре́петі пред вели́чієм милосе́рдія Твоєго́, коленопрекло́ньше, хода́тайства Твоєго́ пред безсме́ртним Си́ном Твої́м про́сим, со умиле́нієм зову́ще:","Ра́дуйся, Ми́лостивая Ма́ти Бо́жия, ми́лості Твоя́ на нас ізлива́ющая."]},{"h":"Молитва","ps":["О, Засту́пниці ми́ра Ма́ти всепі́тая. Со стра́хом, ві́рою і любо́вію припа́даєм пред честно́ю іко́ною Твоє́ю і усе́рдно мо́лим Тя: не отврати́ лиця́ Твоєго́ от прибіга́ющих к Тебі́. Умоли́, ми́лостивая Ма́ти, Си́на Твоєго́ і Бо́га на́шего, сладча́йшаго Го́спода Ісу́са Христа́, да сохрани́ть страну́ на́шу в ми́рі, да утверди́ть держа́ву на́шу в благоде́нствії і да ізба́вить нас от междоусо́бния бра́ні, да укріпи́ть на́шу Правосла́вную Це́рков і нези́блему сохрани́ть ю от неві́рія і раско́ла, і єресе́й. Не і́мами бо ми іни́я по́мощі, ра́зві Тебе́, Пречи́стая Ді́ва. Ти бо єси́ всеси́льная христия́ном засту́пнице пред Бо́гом, пра́ведний гнів Єго́ ум'ягча́ющая. Ізба́ви всіх Тебі́ моля́щихся от паде́ній гріхо́вних, от наві́тов злих челові́к, от гла́да, от скорбе́й. Да́руй нам дух сокруше́нія, смире́нія се́рдця, чистоту́ помишле́ній, ісправле́ніє согріше́ній на́ших, да всі благода́рно воспіва́юще вели́чія Твоя́, сподо́бимся Небе́снаго Ца́рствія, і та́мо со всі́ми святи́ми просла́вим пречестно́є і великолі́поє і́м'я в Тро́йці Єди́наго Бо́га – Отця́ і Си́на і Свята́го Ду́ха. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Притеце́м, лю́діє, со дерзнове́нієм к Ми́лостивій Цари́це Богоро́дице, і умиле́нно воззове́м к Ней: ниспосли́, Влади́чице, ми́лості Твоя́ бога́тия, сохраня́я во здра́вії і благоде́нствії грі́шния раби́ Твоя́. Боля́щия ісціли́, скорб'я́щия уті́ши і бе́дствующим помози́. І сподо́би нас, Преми́лостивая, благоче́стно житіє́ сіє́ земно́є сконча́ти, христия́нськую непости́дную кончи́ну получи́ти і Небе́сноє Ца́рствіє унаслі́довати. Град наш ізба́ви от вся́каго зла́го обстоя́нія, огражда́я Твої́м ми́лостивим заступле́нієм. Ми́рові мир да́руй і спасе́ніє душа́м на́шим іспроси́."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, і чтим о́браз Твой святи́й, і́мже болі́зні на́ша врачу́єши і ду́ші к Бо́гу возво́диши."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Донська»","e":"Akathist to the Theotokos before her icon “Don”","secs":[{"h":"Кондак 1","ps":["Взбра́нней Воєво́ді побіди́тельная, я́ко ізба́вльшеся от злих, благода́рственная воспису́єм Ті раби́ Твої́, Богоро́дице, но, я́ко іму́щая держа́ву непобіди́мую, от вся́ких нас бід свободи́, да зове́м Ті:","Ра́дуйся, Влади́чице, Засту́пнице ві́рних преблага́я і ско́рая."]},{"h":"Ікос 1","ps":["Арха́нгела благові́стіє сли́шавши Пречи́стая, кро́тостію прия́т во́лю Го́спода Своєго́ і во смире́нії се́рдця отвіща́: \"Се Раба́ Госпо́дня, бу́ди Мні по глаго́лу твоєму́\". Ми же, див'я́щеся, ка́ко Син Бо́жий Син Ді́ви бива́єть, с Гавриї́лом Благода́тную пі́сньми си́ми почита́єм:","Ра́дуйся, Отрокови́це, от всіх родо́в Бо́гом ізбра́нная;","ра́дуйся, ски́ніє, Ду́хом Святи́м осіне́нная.","Ра́дуйся, живоно́сная оби́тель Сві́та Боже́ственнаго;","ра́дуйся, Ма́ти Бо́жия, Спа́са ми́ру ро́ждшая.","Ра́дуйся, Всепі́тая, я́ко сотвори́ Ті вели́чіє Си́льний;","ра́дуйся, я́ко і в сла́ві іко́н Твої́х вели́чіє сіє́ явле́но бисть.","Ра́дуйся, я́ко Тобо́ю, Благода́тная, Неви́димий нам приобщи́ся;","ра́дуйся, я́ко чудотво́рними іко́нами Твої́ми благода́ть і ми́лость нам істочи́ся.","Ра́дуйся, Влади́чице, Засту́пнице ві́рних преблага́я і ско́рая."]},{"h":"Кондак 2","ps":["Ви́дяще Тя, Богоро́дице, на об'я́тіїх Свої́х Младе́нця Христа́ держа́щую і главо́ю к пречи́стому ли́ку Єго́ кро́тці прини́кшую, разуміва́єм боже́ственную любо́в Твою́ і непреста́нноє о ми́рі хода́тайство. Ві́руєм, я́ко і́маши ве́ліє дерзнове́ніє ко благосе́рдію Влади́ки, Єму́же, да́вшему нам Тя благу́ю Засту́пницю, благода́рственно поє́м: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум немощни́й не мо́жеть пости́гнути глубину́ смире́ннаго служе́нія Твоєго́, Госпоже́, Іскупи́телю на́шему, не іме́вшему на землі́, гді главу́ подклони́ти. Єгда́ же при́йде вели́кий і тре́петний день страда́ній Си́на Твоєго́, Богома́ти, ору́жіє сме́ртноє про́йде ду́шу Твою́. Сего́ ра́ди се́рдцем соболе́знующе, глаго́лем Ті такова́я:","Ра́дуйся, незло́бивая А́гнице, верте́п і бі́гство смире́нно приі́мшая;","ра́дуйся, Богоприї́мця Симео́на ско́рбноє прорече́ніє в се́рдці начерта́вшая.","Ра́дуйся, поноше́нію Си́на Бо́жия сострада́вшая;","ра́дуйся, кре́стний путь Єго́ слеза́ми ороси́вшая.","Ра́дуйся, му́ки Єго́ кре́стния се́рдцем раздели́вшая;","ра́дуйся, Кресту́ предстоя́нієм соверше́нство любве́ Твоєя́ яви́вшая.","Ра́дуйся, гро́бу Си́на Твоєго́ благосе́рдий плач прине́сшая;","ра́дуйся, Воскресе́нієм Єго́ па́че всіх обра́дованная.","Ра́дуйся, Влади́чице, Засту́пнице ві́рних преблага́я і ско́рая."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго соді́ла Тя, Благода́тная, істо́чник неоскудева́ющ утіше́нія бе́дствующим: мно́гі бо ско́рби претерпі́вши, мо́жеши і іскуша́ємим помощі́. Лю́дем ру́ським, лю́ті стра́ждущим от наше́ствія ага́рян, благоволи́ла єси́ яви́ти о́браз Твой в зна́меніє ми́лости Твоєя́ ко Оте́честву на́шему, в защи́ту от враг ви́димих і неви́димих, ї́хже по́мощію Бо́жиєю побіжда́юще, Спаси́телю Бо́гу воспіва́ху: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще Тя Подвигополо́жницю, ше́ствующую по стопа́м Влади́ки Христа́, му́жества ісполня́хуся первосвяти́теліє Моско́встії і подви́жници благоче́стія землі́ Ру́ськия. Біди́ і напа́сти претерпіва́юще, сі́ї уча́ху лю́ди ду́хом Го́сподеві рабо́тати, ві́дуще, я́ко си́ла Бо́жія в не́мощі соверша́ється. Ми же, ви́дяще ві́ру оте́ць на́ших і явле́ніє благода́ті, претвори́вшия злоумишле́нія во нра́ви до́брия, досто́йно Тя, Наста́вницю ві́рних, ублажа́єм:","Ра́дуйся, насажде́ніє ві́ри і благоче́стія;","ра́дуйся, о́бразе несокруши́маго терпі́нія.","Ра́дуйся, ду́ха уни́нія і боя́зні отгна́ніє;","ра́дуйся, ду́ха ра́зума і крі́пости стяжа́ніє.","Ра́дуйся, близ Донськи́х струй чу́дно іко́ну Твою́ яви́вшая;","ра́дуйся, рі́ки слез наро́дних є́ю ізсуши́вшая.","Ра́дуйся, до́блести бога́тство нам вручи́вшая;","ра́дуйся, моли́твенников землі́ Ру́ськия возрасти́вшая.","Ра́дуйся, Влади́чице, Засту́пнице ві́рних преблага́я і ско́рая."]},{"h":"Кондак 4","ps":["Бу́ря превели́каго наше́ствія ага́рянскаго потрясе́ зе́млю Ру́ськую, но не возмо́же пла́мень угаси́ти ві́ри в покро́в Твой, Богома́ти Пречи́стая. Вели́кий печа́льник землі́ на́шея преподо́бний Се́ргій, призва́в на по́мощ Святу́ю Тро́йцю і Тя, Влади́чице, со упова́нієм благослови́ свята́го кня́зя Дими́трія с дружи́ною в похо́д проти́ву ага́рян і предрече́ єму́ побі́ду, ті́мже научи́ всіх пі́ти всеси́льному Бо́гу, в Тро́йці сла́вимому: Аллилу́я."]},{"h":"Ікос 4","ps":["Ви́дя іко́ну Богома́тере, на по́ли бра́ні от Донськи́х преді́л прише́дшую, і, приї́м посла́ніє от Се́ргия преподо́бнаго с напу́тієм: \"Да помо́жеть ті Бог і Свята́я Богоро́диця\", возра́довася князь Дими́трій, я́ко Сама́ Влади́чиця гряде́ть на супоста́ти, і, воспряну́в ду́хом, с наде́ждею поведе́ во́їни своя́ на тьмочи́сленная по́лчища і побі́ду одержа́. Іко́на же Твоя́, Влади́чице, молнієно́сним блиста́нієм зра́ка Твоєго́ враги́ устраша́ющи, зало́г побі́ди явля́ше. Сего́ ра́ди благода́рственно і ра́достно поє́м Ті похва́льная сія́:","Ра́дуйся, Ма́ти Го́спода Сил, Небе́сная Воєво́до;","ра́дуйся, землі́ Ру́ськия от ві́ка по́моще і покро́ве.","Ра́дуйся, во́їном му́жества неодоли́маго дарова́ніє;","ра́дуйся, врага́ іско́ннаго гро́зноє низверже́ніє.","Ра́дуйся, во́їнов-і́ноков на по́двиг ра́тний ізбра́вшая і укріпи́вшая;","ра́дуйся, Оте́чество на́ше от і́га ага́рянськаго свободи́вшая.","Ра́дуйся, в явле́нії іко́ни Твоєя́ луча́ми Со́лнця пра́вди ві́рних осія́вшая;","ра́дуйся, пресла́вную побі́ду правосла́вно Тя чту́щим дарова́вшая.","Ра́дуйся, Влади́чице, Засту́пнице ві́рних преблага́я і ско́рая."]},{"h":"Кондак 5","ps":["Богоявле́нною звіздо́ю возсія́ іко́на Твоя́ пресві́тлая, озаря́ющи у́тро бра́ні і возвіща́ющи благослове́ніє Бо́жиє ратобо́рцем, на брань жесто́кую с ага́ряни подви́гшимся. Весь день той предстоя́ху Се́ргій преподо́бний і і́ноці мно́зі в моли́тві неотсту́пней ко Святі́й Тро́йці. Ве́черу же би́вшу, побі́ду ста́рець ду́хом позна́в, ра́достно сію́ провозгласи́ і благода́рственноє пі́ніє соверши́ всеще́дрому Бо́гу, призива́я і нас велегла́сно воспі́ти Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя очи́ма ві́ри тече́ніє би́тви і моли́твою ратобо́рці укріпля́я, пойме́нно помина́ше преподо́бний Се́ргій вожди́ і во́їни убіє́нния. Ми же, іму́ще заві́т єго́ па́м'ять о такови́х осо́бо твори́ти і ві́дуще си́лу моли́тви, побі́ду ору́жію принося́щия, із глубини́ се́рдця воззове́м Бо́жієй Ма́тері, всемо́щній Покрови́тельнице ду́шу свою́ полага́ющих за дру́ги своя́:","Ра́дуйся, меч гні́ва Бо́жия на проде́рзия направля́ющая;","ра́дуйся, із пра́вди віне́ць побі́ди соплета́ющая.","Ра́дуйся, с хра́брими непреобори́мо спобора́ющая;","ра́дуйся, к подвиго́м во бра́ніх дух возвиша́ющая.","Ра́дуйся, ура́ненних Свої́м попече́нієм не оставля́ющая;","ра́дуйся, убіє́нних к ві́чному поко́ю управля́ющая.","Ра́дуйся, вдови́ць і обезча́дствованних благода́тно утіша́ющая;","ра́дуйся, Воєво́до ізря́дная, непобіди́мо держа́вствующая.","Ра́дуйся, Влади́чице, Засту́пнице ві́рних преблага́я і ско́рая."]},{"h":"Кондак 6","ps":["Провозві́стник спасе́нія Москви́ от внеза́пнаго наше́ствія ага́рянскаго яви́ся о́браз Твой, Засту́пнице ско́рая. Неприя́телем во град вни́ти уже́ гото́вим, с ві́рою і сле́зним моле́нієм обнесо́ша єго́ лю́діє по стіна́м і сто́гнам гра́да і поста́виша посреді́ во́їнства в похо́дней це́рквице Се́ргия преподо́бнаго і, в моли́тві приліжа́ще, усе́рдно взива́ху Всеми́лостивому Спа́су: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́вшу со́лнцю, узрі́ша стрегу́щії во́їни, я́ко опусті́ стан ага́рянський: но́щію страх внеза́пу нападе́ на ня от ні́кия ве́лія си́ли і, смути́вшеся, неудержи́мо біжа́ша да́же до преді́л землі́ Ру́ськия і всі ізгибо́ша. О преди́вная Засту́пнице на́ша! Твої́ми моли́твами ско́роє ізбавле́ніє сіє́ бисть. Да іспо́лниться же дре́вній храм, возви́сивийся на мі́сті, іді́же стоя́ше чудотво́рний о́браз Твой Донськи́й, гла́са хвали́ сея́:","Ра́дуйся, свіще́ неугаси́мая, ві́ри огнь воспламеня́ющая;","ра́дуйся, гра́ду Москві́ стра́же неусипа́ющая.","Ра́дуйся, упова́ющих на по́мощ Твою́ не посрамля́ющая;","ра́дуйся, плач ві́рних вско́рі в ра́дость претворя́ющая.","Ра́дуйся, в бі́гство враги́ обраща́ющая;","ра́дуйся, призива́ющим Тя по́мощ подаю́щая.","Ра́дуйся, со святи́телі і преподо́бними град наш огражда́ющая;","ра́дуйся, і́ноков под сі́нію іко́ни Твоєя́ учрежда́ющая.","Ра́дуйся, Влади́чице, Засту́пнице ві́рних преблага́я і ско́рая."]},{"h":"Кондак 7","ps":["Восхоті́вши огради́ти зе́млю Ру́ськую, держа́вная Покрови́тельнице на́ша, мно́гажди ко́зні ага́рян і про́чих іноплеме́нник разоря́ше, преді́ли страни́ на́шея храня́щи і побі́ди ди́вния да́же без кро́ве подаю́щи. Благоволи́, о Ма́ти Бо́жия, в ми́рі глубо́ці і сою́зі любве́ вселе́нную сохрани́ти, Тебі́ бо даде́ся благода́ть всеми́рнаго заступле́нія пред Влади́кою всіх, Єго́же во́їнства Небе́сная сла́в'ять, пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго стра́жа неуси́пнаго гра́да Москви́ досто́йно почти́ти хотя́ще, собо́рний храм лю́діє благочести́вії в Донсте́й оби́телі сооруди́ша і на стіні́ хра́ма живописа́ша іко́ну Твою́, Богома́ти, в боже́ственноє огражде́ніє страни́ на́шея, я́ко да отвні́ находя́щії вразі́ отраже́ні бу́дуть неотсту́пними моли́твами Твої́ми. Тебі́ же, я́ко су́щей с на́ми, со упова́нієм глаго́лем:","Ра́дуйся, Бо́га Жива́го одушевле́нний хра́мі;","ра́дуйся, Ма́ти ми́ра, укроща́ющая см'яте́ній во́лни.","Ра́дуйся, нощни́х бді́ній і моле́бних пі́ній ско́роє сли́шаніє;","ра́дуйся, до́броє приста́нище душа́м, спасе́нія і́щущим.","Ра́дуйся, іко́ну Твою́, я́ко зна́м'я побі́д, дарова́вшая;","ра́дуйся, страну́ Ру́ськую достоя́ніє Своє́ ізбра́вшая.","Ра́дуйся, бра́ней прекраще́нієм мир і ра́дость принося́щая;","ра́дуйся, ко благоче́стію страну́ на́шу приводя́щая.","Ра́дуйся, Влади́чице, Засту́пнице ві́рних преблага́я і ско́рая."]},{"h":"Кондак 8","ps":["Разсі́яшася ту́чі напа́стей моли́твами Твої́ми, Засту́пнице всеблага́я. Те́плая заря́ покая́нія, восходя́щи, предваря́єть то́ки благода́ті, призива́ющи к по́двигу, є́же ві́ровати пра́во і жи́ти свя́то. Простри́ же покро́в Твой, о Благода́тная Ма́ти, на всіх гряду́щих у́зьким, но вожделі́нним путе́м Христо́вих за́повідей, да всі позна́ють, я́ко с на́ми Бог, Єму́же поє́м: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь мир стра́ждеть гріх ра́ди челові́чеських, во зло єго́ поверга́ющих. В Тебі́, Ма́ти ро́да христия́нськаго, нача́ло о́бщаго ізбавле́нія бисть, ісполне́ніє вся́кия доброді́телі. Да́руй же нам узрі́ти, Богому́драя Ді́во, в Єва́нгелії Си́на Твоєго́ світ Боже́ственний, да отве́ргше го́реч гріха́, сла́дость благоче́стія обря́щем, взива́юще Ті сицева́я:","Ра́дуйся, благода́ті живоно́сний істо́чниче;","ра́дуйся, заблу́ждшим путево́дний світи́льниче.","Ра́дуйся, сле́зне ка́ющимся обновле́ніє подаю́щая;","ра́дуйся, ходи́ти в зако́ні Госпо́дні наставля́ющая.","Ра́дуйся, моли́тві те́плій науча́ющая;","ра́дуйся, по́двигу поста́ вспомоществу́ющая.","Ра́дуйся, гріхо́вния по́мисли вла́стно от нас отгоня́ющая;","ра́дуйся, братолю́бієм те́мную зло́бу побіжда́ти наставля́ющая.","Ра́дуйся, Влади́чице, Засту́пнице ві́рних преблага́я і ско́рая."]},{"h":"Кондак 9","ps":["Всіх немощни́х крі́посте, печа́льних ра́дованіє, стра́ждущих посіще́ніє, ві́рних дерзнове́ніє Ти єси́, Пречи́стая Влади́чице Богоро́дице, всіх притека́ющих под сінь Креста́ Госпо́дня ко спасе́нію приво́диши, да позна́вше Христа́, Бо́жию Си́лу і Бо́жию Прему́дрость, воспою́ть Єму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії пости́гнути не мо́гуть, человіколюби́вая Ма́ти, бе́здну щедро́т Твої́х, на злостра́ждущия і безпомо́щния ізлива́ємих. І ми, сла́дость утіше́нія в ну́ждах позна́вше, благословля́єм Тя с ві́рою і честву́єм с любо́вію, моле́нія вознося́ще пред о́бразом Твої́м сицева́я:","Ра́дуйся, в ско́рбіх земни́х во́лю Бо́жию смире́нно приі́мшая;","ра́дуйся, обурева́ємих в ти́хоє приста́нище вводя́щая.","Ра́дуйся, боля́щих милосе́рдая Ціли́тельнице;","ра́дуйся, вдов і сиро́т незри́мая Пита́тельнице.","Ра́дуйся, стра́ждущих любо́вію окружа́ющая;","ра́дуйся, долгонеду́жних сла́дости ра́йстій приобща́ющая.","Ра́дуйся, чад Свої́х от враг необори́мо защища́ющая;","ра́дуйся, я́ко слеза́ми ра́дости іко́на Твоя́ украша́ється.","Ра́дуйся, Влади́чице, Засту́пнице ві́рних преблага́я і ско́рая."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ мир, Син Бо́жий із Тебе́, Ді́во, пло́тію облече́ся і єстество́ на́ше па́дшеє обнови́. Ди́вноє Бо́жиє смотре́ніє о нас Тобо́ю, Ді́во, ісполня́ється, я́ко Ти єси́ воі́стину поги́бших взиска́ніє і грі́шних ісправле́ніє, і Тобо́ю от отча́янія ізба́влени, дерза́єм с весе́лієм пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ несокруши́мая Це́ркві Христо́ві, Всенепоро́чная Ді́во, ві́рния бо во іскуше́ніїх укріпля́єши, ми́ром і любо́вію огражда́єши. Сего́ ра́ди і гла́си моли́твеннії не умолка́ють зову́щих Ті:","Ра́дуйся, от купі́лі креще́нія блага́я Путеводи́тельнице;","ра́дуйся, цілому́дрія ю́них Огради́тельнице.","Ра́дуйся, ма́терем многотру́дним ізря́дная Помо́щнице;","ра́дуйся, чад непокори́вих му́драя Наста́внице.","Ра́дуйся, в сиротствеі ди́вноє утіше́ніє;","ра́дуйся, вражду́ющих неча́ємоє примире́ніє.","Ра́дуйся, беззако́ннующих сві́том пра́вди просвіща́ющая;","ра́дуйся, гріхи́ на́ша в мо́рі милосе́рдія потопля́ющая.","Ра́дуйся, Влади́чице, Засту́пнице ві́рних преблага́я і ско́рая."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє прино́сим Ті, вмісти́вшей іпоста́сноє Сло́во Бо́жиє. Син Твой, А́гнець Бо́жий, взе́мляй гріхи́ ми́ра, закала́ється і дає́ться в снідь ві́рним. Сподо́би нас, Ма́ти Бо́жия, досто́йно причаща́тися Пречи́стих Ті́ла і Кро́ве Єго́, да спасе́ніє улучи́вше, воспоє́м Жизнода́вцю: Аллилу́я."]},{"h":"Ікос 11","ps":["Дщи Отця́ Небе́снаго, Ма́ти Си́на Бо́жия, Неві́сто Ду́ха Свята́го, неісчерпа́ємоє мо́ре даро́в боже́ственних Ти єси́, Всесвята́я Ді́во. Умоли́ Человіколю́бця Го́спода откри́ти нам істо́чник всеоживля́ющия благода́ті, да очище́нним се́рдцем потщі́мся возрасти́ти плоди́ Ду́ха, в ра́дості і весе́лії зову́ще Ті:","Ра́дуйся, плодо́в Ду́ха Свята́го стяжа́ніє всеці́лоє;","ра́дуйся, ра́достію духо́вною упоє́ніє пречу́дноє.","Ра́дуйся, ми́ра непоколеби́маго дарова́ніє благонаде́жноє;","ра́дуйся, бла́гості і любве́ ісполне́ніє преми́рноє.","Ра́дуйся, милосе́рдія насажде́ніє неув'яда́ємоє;","ра́дуйся, ві́ри живи́я утвержде́ніє несокруши́моє.","Ра́дуйся, кро́тости Наста́внице несравне́нная;","ра́дуйся, вражди́ разруша́ющая средості́ніє.","Ра́дуйся, Влади́чице, Засту́пнице ві́рних преблага́я і ско́рая."]},{"h":"Кондак 12","ps":["Благода́тную по́мощ мно́гажди явля́ла єси́, Цари́це Небе́сная, чрез чудотво́рний о́браз Твой, от сме́рти ско́рия і неізбі́жния ізима́ющи. Та́ко о́браз всечистна́го Успе́нія Твоєго́, на обра́тней страні́ іко́ни Донськи́я от літ дре́влих пи́санний, зна́меніє єсть вся́кому подвиза́ющемуся, да не убої́ться сме́рті, но, взира́я, ка́ко душа́ Твоя́ приє́млеться в ру́ці Бо́га жива́го, с наде́ждею предає́ть себі́ в час сме́ртний Судії́ всіх Бо́гу, вопія́ Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Тя, в моли́твах неусипа́ющую Богоро́дицю, Святі́й Тро́йці предстоя́щую, вопіє́м Ті: пробуди́ нас сві́том живоно́снаго Успе́нія Твоєго́ от смертоно́снаго сна нераде́нія о спасе́нії душі́ і іспроси́ нам с Го́сподем примире́ніє. Єгда́ же приспі́єть жа́тва сме́ртная житію́ на́шему, огради́ нас всеси́льним предста́тельством Твої́м от духо́в зло́би, да Тобо́ю води́ми, дости́гнем Ца́рствія Небе́снаго, іді́же незаходи́моє Со́лнце пра́вди невече́рній світ сла́ви Боже́ственния ізлива́єть. О Всесвята́я Ді́во, от Херуви́м воспіва́ємая, прийми́ от нас, недосто́йних, похвали́ сія́:","Ра́дуйся, обра́дованная, во успе́нії Твоє́м нас не оставля́ющая;","ра́дуйся, Ма́ти всепі́тая, одесну́ю Бо́га предстоя́щая.","Ра́дуйся, го́рняго ми́ра красото́ боголі́пная;","ра́дуйся, кла́дезю богоми́слія неісчерпа́ємий.","Ра́дуйся, любве́ боже́ственния неугаси́мий світи́льниче;","ра́дуйся, гріхо́вних уз ско́рая Ріши́тельнице.","Ра́дуйся, возду́шних мита́рств безбі́дноє прехожде́ніє;","ра́дуйся, блага́я Врата́рнице, две́рей ра́йських отверзе́ніє.","Ра́дуйся, Влади́чице, Засту́пнице ві́рних преблага́я і ско́рая."]},{"h":"Кондак 13","ps":["О всеми́лостивая Влади́чице Богоро́дице, страни́ на́шея ди́вная Засту́пнице, оби́димих прибі́жище, грі́шних спасе́ніє! Оте́чество на́ше от враг защити́, вселе́нную всю ми́ром благослови́, ві́ру правосла́вную укріпи́, крест коєму́ждо со упова́нієм понести́ помози́, в любві́ і согла́сії всіх нас соблюди́ і в ра́дость Го́спода вни́ти сподо́би пою́щих Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгела благові́стіє сли́шавши Пречи́стая, кро́тостію прия́т во́лю Го́спода Своєго́ і во смире́нії се́рдця отвіща́: \"Се Раба́ Госпо́дня, бу́ди Мні по глаго́лу твоєму́\". Ми же, див'я́щеся, ка́ко Син Бо́жий Син Ді́ви бива́єть, с Гавриї́лом Благода́тную пі́сньми си́ми почита́єм:","Ра́дуйся, Отрокови́це, от всіх родо́в Бо́гом ізбра́нная;","ра́дуйся, ски́ніє, Ду́хом Святи́м осіне́нная.","Ра́дуйся, живоно́сная оби́тель Сві́та Боже́ственнаго;","ра́дуйся, Ма́ти Бо́жия, Спа́са ми́ру ро́ждшая.","Ра́дуйся, Всепі́тая, я́ко сотвори́ Ті вели́чіє Си́льний;","ра́дуйся, я́ко і в сла́ві іко́н Твої́х вели́чіє сіє́ явле́но бисть.","Ра́дуйся, я́ко Тобо́ю, Благода́тная, Неви́димий нам приобщи́ся;","ра́дуйся, я́ко чудотво́рними іко́нами Твої́ми благода́ть і ми́лость нам істочи́ся.","Ра́дуйся, Влади́чице, Засту́пнице ві́рних преблага́я і ско́рая."]},{"h":"Кондак 1","ps":["Взбра́нней Воєво́ді побіди́тельная, я́ко ізба́вльшеся от злих, благода́рственная воспису́єм Ті раби́ Твої́, Богоро́дице, но, я́ко іму́щая держа́ву непобіди́мую, от вся́ких нас бід свободи́, да зове́м Ті:","Ра́дуйся, Влади́чице, Засту́пнице ві́рних преблага́я і ско́рая."]},{"h":"Молитва","ps":["О Пресвята́я Влади́чице, Ді́во Богоро́дице, Засту́пнице на́ша блага́я і ско́рая! Воспіва́єм Ті всі благода́рственная за чу́дная діла́ Твоя́. Пісносло́вим от літ дре́вніх неот'є́млемоє заступле́ніє Твоє́ гра́ду Москві́ і страні́ на́шей, чудотво́рним о́бразом Твої́м Донськи́м всегда́ явля́ємоє: в бі́гство обраща́ються полці́ чужди́х, гра́ди і ве́сі невреди́ми сохраня́ються, лю́діє же от лю́тия сме́рті ізбавля́ються, осуша́ються о́чі слезя́щії, умолка́ють стена́нія ві́рних, плач в ра́дость о́бщую претворя́ється. Бу́ди і нам, Пречи́стая Богоро́дице, утіше́ніє в бе́дствіїх, возрожде́ніє наде́жди, о́браз му́жества і істо́чник ми́лости; в ско́рбних обстоя́ніїх неістощи́моє терпі́ніє нам да́руй. Пода́ждь коєму́ждо по проше́нію і ну́жді єго́: младе́нці воспита́й, ю́ния уцілому́дри і стра́ху Бо́жию научи́, унива́ющия обо́дри і немощну́ю ста́рость поддержи́. Ми́лостію посіти́ в болі́зніх і печа́ліх су́щия, зла́я сердца́ ум'ягчи́, братолю́біє укріпи́, ми́ра і любве́ всіх нас іспо́лни. Примири́, Благосе́рдая Ма́ти, вражду́ющия і оправда́й оклевета́нния. Істреби́ поро́ки, да не восхо́дять гріси́ на́ші пред Судіє́ю вся́чеських, да не пости́гнеть нас пра́ведний гнів Бо́жий. Твої́ми моли́твами, всемо́щним Твої́м покро́вом огради́ нас от наше́ствій вра́жиїх, от гла́да, губи́тельства, огня́, меча́ і вся́каго іна́го злострада́нія. Упова́єм моли́твами Твої́ми получи́ти гріхо́в ізглажде́ніє і с Бо́гом примире́ніє. Умоли́ стяжа́ти нам Ца́рствіє Небе́сноє і с ли́ки А́нгелов і святи́х та́мо восхвали́ти пречестно́є і́м'я Святи́я Тро́йці: Отця́, і Си́на, і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Засту́пнице ві́рних Преблага́я і Ско́рая, / Пречи́стая Богоро́дице Ді́во! / Мо́лим Тя пред святи́м і чудотво́рним о́бразом Твої́м, / да, я́коже дре́вле от него́ заступле́ніє Твоє́ / гра́ду Москві́ дарова́ла єси́, / та́ко і ни́ні нас от вся́ких бід і напа́стей ми́лостивно ізба́ви, // і спаси́ ду́ші на́ша, я́ко Милосе́рдая."]},{"h":"Кондак, глас 8","ps":["Взбра́нной Воєво́ді побіди́тельная, / я́ко ізба́вльшеся от злих, / благода́рственная воспису́єм Ті, раби́ Твої́, Богоро́дице, / но, я́ко іму́щая держа́ву непобіди́мую, / от вся́ких нас бід свободи́, да зове́м Ті: // ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / і чтим о́браз Твой святи́й, / і́мже ди́вную побі́ду на ага́ряни // правосла́вним дарова́ла єси́."]},{"h":"Інше величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / і чтим о́браз Твой святи́й, / і́мже заступле́ніє ди́вноє // гра́ду Твоєму́ дарова́ла єси́."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Утіха» або «Розрада»","e":"Akathist to the Theotokos before her icon “Consolation” or “Comfort”","secs":[{"h":"Кондак 1","ps":["Возбра́нних Сил Небе́сних ра́дость і хвале́ніє, всего́ же ро́да челові́ча ісправле́ніє, ублажа́єм Тя, Пречи́стая Ді́во Ма́ти, Ти же, на́ше упова́ніє єди́ноє, низпосли́ душа́м отра́ду благода́тную, да поє́м Тебе́, о́браз ди́вний Твой чту́ще:","Ра́дуйся, Бо́жия Ма́ти, сві́тлая на́ша Отра́до."]},{"h":"Ікос 1","ps":["А́нгелов ли́ци див'я́ться, о́браз афо́нський Твой зря́ще, на не́мже, Пречи́стая Ді́во і Ма́ти, от уст нетлі́нних руко́ю десно́ю десни́цю Младе́нця отво́диши кро́тко. Что сіє́ єсть зна́меніє о́браза? Ми же рече́м, пою́ще такова́я:","Ра́дуйся, Ді́во, Всеви́шняго Ма́ти;","ра́дуйся, ди́вний раю́ благода́ті.","Ра́дуйся, на́ша Отра́до Небе́сная;","ра́дуйся, лю́дем Наде́ждо ізві́стная.","Ра́дуйся, о́браз бо Твой спасе́ніє возвіща́єть всей землі́;","ра́дуйся, взор бо Твой утіше́ніє пребива́ющим во тлі.","Ра́дуйся, сві́те Небе́сний, мглу на́ших дній озаря́яй;","ра́дуйся, цві́те нетлі́нний, тлін на́ших діл оживля́яй.","Ра́дуйся, Ти бо моли́тви к Си́ну за мир твори́ши;","ра́дуйся, я́ко в те́плой моли́тві, а́ки світи́льник, гори́ши.","Ра́дуйся, ра́достно Ті восклиця́єм;","ра́дуйся, пі́сненно Тя воспіва́єм.","Ра́дуйся, Бо́жия Ма́ти, сві́тлая на́ша Отра́до."]},{"h":"Кондак 2","ps":["Недоумі́єть ум до́льній та́йни Твоєя́ разумі́ти, Пречи́стая Богоблаже́нная Ді́во, Ти бо, в ло́но чи́стоє ді́йствієм Ду́ха приї́мши безсі́менно О́тчеє Сло́во, Бо́га челові́ком сочета́єши і піснь повеліва́єши всім пі́ти: Аллилу́я."]},{"h":"Ікос 2","ps":["Го́ру Афо́нськую, Ді́во, Си́ном Ті да́нную в жре́бій, покро́вом Свої́м осіня́ющи сви́ше, храни́ши ди́вно от бід і напа́стей. Благода́тних іко́н Твої́х чудеси́ оби́телі афо́нськия сла́в'яться і гла́си преподо́бними Тя хва́лять:","Ра́дуйся, Ді́во, отра́до в печа́ліх;","ра́дуйся, Скоропослу́шнице в ско́рбіх.","Ра́дуйся, су́щим в путі́ Одиги́тріє;","ра́дуйся, хра́мов свяще́нних Врата́рнице.","Ра́дуйся, до́брая Предвозве́стнице унива́ющим в біді́;","ра́дуйся, ві́рноє утіше́ніє притека́ющим к Тебі́.","Ра́дуйся, бі́дним бога́тство, єлеоно́сная Же́но;","ра́дуйся, чту́щим ака́фист благоволя́щая та́йно.","Ра́дуйся, в ке́ллії ста́рцю ре́кшая \"ра́дуйся\" чу́дно;","ра́дуйся, живоприє́мная Ма́ти.","Ра́дуйся, Тя бо досто́йно єсть пі́ти;","ра́дуйся, Тя бо по до́лгу всі ублажа́єм.","Ра́дуйся, Бо́жия Ма́ти, сві́тлая на́ша Отра́до."]},{"h":"Кондак 3","ps":["Є́вину го́рдую пре́лесть Ді́ви смире́нноє \"бу́ди\" в оча́х Милосе́рднаго всю упраздня́єть: се Син Бо́жий Син Ді́ви бива́єть і Бог непристу́пний живе́ть с челові́ки, ті́мже благода́рственноє пі́ніє немо́лчними усти́ возсила́єм: Аллилу́я."]},{"h":"Ікос 3","ps":["Ликостоя́ще над мо́рем, сві́том моли́тви сія́ють пред Бо́гом святи́ні Афо́на, і я́ві Бо́жия Ма́тере сла́ва Афо́на святи́я глави́ осіня́єть, к пі́нію на вся́кий час призива́ющи пусти́нники, Ю воспіва́ющія:","Ра́дуйся, сла́во пусти́нь вожделі́нних;","ра́дуйся, чу́до висо́т поднебе́сних.","Ра́дуйся, гор і холмо́в осіне́ніє;","ра́дуйся, скал і стремни́н освяще́ніє.","Ра́дуйся, Є́юже открива́ється путь в Небе́сния страни́;","ра́дуйся, Є́юже отверза́ється рай нетлі́нния весни́.","Ра́дуйся, кри́не в юдо́лі, благоуха́нная ра́досте;","ра́дуйся, цві́те кра́сний, приснотеку́щая сла́досте.","Ра́дуйся, сві́та восто́че, до́ли землі́ озари́вий;","ра́дуйся, жи́зні пото́че, во́ду живу́ю яви́вий.","Ра́дуйся, гла́се немо́лчних моле́ній;","ра́дуйся, щі́те свяще́нних селе́ній.","Ра́дуйся, Бо́жия Ма́ти, сві́тлая на́ша Отра́до."]},{"h":"Кондак 4","ps":["О челові́честім ро́де, є́же спасти́ ни, о Ді́во, в моли́твах пред Си́ном Сладча́йшим стої́ши; о Ма́ти, лю́дем блага́я Отра́до, Ти зри́ши бе́здну гріхо́в на́ших лю́тих, ми же, в ро́ві істлі́нія пове́рженнії, не смі́єм возвісти́ очеса́ і воспі́ти: Аллилу́я."]},{"h":"Ікос 4","ps":["Ватопе́дськая оби́тель сла́виться о́бразом чу́дним, єму́же єсть дре́внєє і́м'я Отра́да. О нем преда́ніє ста́рець блаже́нних храни́ть благода́тную ди́вную по́вість, во сла́ву Богоро́диці Засту́пниці, да сли́шаще сію́, поє́м Пречи́стій:","Ра́дуйся, ми́ра блага́я Отра́до;","ра́дуйся, ві́рним стіно́ і огра́до.","Ра́дуйся, чу́до чуде́с несказа́нноє;","ра́дуйся, Не́бо небе́с осія́нноє.","Ра́дуйся, безмо́лвіє лю́б'ящим кра́ю жела́ній;","ра́дуйся, безм'яте́жія і́щущим раю́ жела́нний.","Ра́дуйся, я́ко Тобо́ю вся́ка душа́ ожива́єть;","ра́дуйся, я́ко Тобо́ю ме́ртвенний ум воскреса́єть.","Ра́дуйся, ві́ри горни́ло, і́мже неві́ріє та́єть;","ра́дуйся, та́йная си́ло, я́же от тлі возставля́єть.","Ра́дуйся, сла́во отше́льников тре́звенних;","ра́дуйся, крі́посте і́ноков бо́дренних.","Ра́дуйся, Бо́жия Ма́ти, сві́тлая на́ша Отра́до."]},{"h":"Кондак 5","ps":["Ро́ждшая жизнь всему́ ми́ру, я́вльшая ми́лости бе́здну, о Ді́во Пречи́стая, о́ком ясне́йшим зри́ши на́ших печа́лей пучи́ну, сли́шиши гла́си земни́х воздиха́ній, ско́ро на по́мощ к нам притека́єши, і учи́ши нас пі́ти Всеблаго́му: Аллилу́я."]},{"h":"Ікос 5","ps":["А́лчуще зла́та і кро́ве, де́рзько разбо́йници с мо́ря оби́тель святу́ю в нощі́ облага́ють, да зіло́ зау́тра, врато́м отворе́нним, уби́вше мона́хов, расхи́тять святи́ні. Ти же, неуси́пная Засту́пнице, уді́л Свой защища́єши, да сла́вить Тя:","Ра́дуйся, Ватопе́да отра́до;","ра́дуйся, вра́жиїм ко́знем прегра́до.","Ра́дуйся, за́мислов злих обличе́ніє;","ра́дуйся, лю́тих враго́в отраже́ніє.","Ра́дуйся, я́ко не усипа́єши, Свой спаса́ющи уді́л;","ра́дуйся, я́ко отвраща́єши ту́чі смертоно́сних стріл.","Ра́дуйся, крі́посте чту́щих свя́тость іко́н Твої́х чу́дних;","ра́дуйся, сто́лпе пою́щих сла́ву чуде́с Твої́х мно́гих.","Ра́дуйся, кро́тких побі́до і пораже́ніє го́рдих;","ра́дуйся, пра́вих защи́то і посрамле́ніє лжи́вих.","Ра́дуйся, Ти бо єси́ заблу́ждших корми́ло;","ра́дуйся, Ти бо єси́ моли́тви кади́ло.","Ра́дуйся, Бо́жия Ма́ти, сві́тлая на́ша Отра́до."]},{"h":"Кондак 6","ps":["Ді́вственний взор Твой, блага́я Ма́ти, пото́ки любве́ і щедро́т ізлива́єть: Ти нас храни́ши в ісхо́діх і вхо́діх, спаса́єши ві́рних на су́ші і в мо́рі, а́ще то́кмо і́скра покая́нія возника́єть в се́рдці, є́же воспіва́ти: Аллилу́я."]},{"h":"Ікос 6","ps":["О́бщія моли́тви в час у́тра і́ноці соверши́вше, отидо́ша в ке́ллії до Литургі́ї, оба́че ігу́мен оби́телі, в хра́мі єди́н моля́ся, от іко́ни Твоєя́ Отра́ди глас сли́ша: \"Врат не отверза́йте днесь\". Тре́петом же об'я́т сий, си́це ста́рець восклиця́ше:","Ра́дуйся, Ді́во, я́ко єси́ стра́жа святи́ні;","ра́дуйся, я́ко дом Твой спаса́єши ни́ні.","Ра́дуйся, щі́те зау́тра і но́щію;","ра́дуйся, гро́зная си́лою мно́гою.","Ра́дуйся, я́ко милосе́рдієм Твої́м щади́ши грі́шния;","ра́дуйся, я́ко поража́єши востаю́щия на ни си́льния.","Ра́дуйся, ві́нче наде́жди, знаменова́ніє ми́ра;","ра́дуйся, же́зле побі́ди, обітова́ніє сла́ви.","Ра́дуйся, чи́стий сапфи́рі, подо́бний виді́нію не́ба;","ра́дуйся, сві́тлий престо́ле і колесни́це Царе́ва.","Ра́дуйся, я́ко глас Твой сла́док уши́ма;","ра́дуйся, я́ко о́браз Твой красе́н очи́ма.","Ра́дуйся, Бо́жия Ма́ти, сві́тлая на́ша Отра́до."]},{"h":"Кондак 7","ps":["Син Челові́чеський близ єсть, Суд Єго́ Стра́шний при две́ріх, — віща́єть нам глас богоно́сних Писа́ній, оба́че неради́м о кончи́ні, ліни́вії су́ще, і гро́зним глаго́лом не вне́млем, всі бо в суєті́ пови́ннії во́лею, оба́че с ві́рою і любо́вію к Тебі́, Богома́ти, прибіга́юще, вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Тре́петно ста́рець ігу́мен к о́бразу взор свой возво́дить і ви́дить: се ли́ци пред ним ожива́ють, і Ді́ві гро́зний Младе́нець руко́ю уста́ загражда́єть, глаго́ля: О Ма́ти, не провещава́й, да нака́жуться. Ста́рець же, ужаса́яся, поє́ть Пречи́стій та́ко:","Ра́дуйся, Ді́во, Влади́чице ми́ра;","ра́дуйся, Не́ба Цари́це блага́я.","Ра́дуйся, я́ко Бо́жий гнів утоля́єши;","ра́дуйся, я́ко гро́зний суд отвраща́єши.","Ра́дуйся, Ма́ти всемилосе́рдная, ізбавле́ніє от бід;","ра́дуйся, по́моще благода́тная, упова́ніє душа́м.","Ра́дуйся, Ти бо печа́лі на́ша отго́ниши ско́ро;","ра́дуйся, Ти бо болі́зні грі́шних врачу́єши ди́вно.","Ра́дуйся, я́коже у́тро, світ пролива́ющая ти́хий;","ра́дуйся, я́коже со́лнце, согріва́ющая хла́дния ду́ші.","Ра́дуйся, чу́дная Отрокови́це;","ра́дуйся, ди́вная Богоневі́сто.","Ра́дуйся, Бо́жия Ма́ти, сві́тлая на́ша Отра́до."]},{"h":"Кондак 8","ps":["Єдиноми́сленно, Ді́во, взо́ри к Тебі́ обраща́єм, Ти бо в день воздая́нія нас не оставля́єши; простри́ у́бо нам ще́друю Свою́ ру́ку, гріхми́ бо падо́хом до а́дськия бе́здни, і кто нас ізба́вить от гряду́щих мук, кто же нас утверди́ть, во є́же пі́ти: Аллилу́я."]},{"h":"Ікос 8","ps":["Ма́ти отво́дить десни́цю сла́дкаго Си́на і, ма́ло лице́ отклоня́ющи, ста́рцю глаго́леть: \"На сті́ни бра́тія вся да вихо́дить і лю́тих разбо́йников да отража́єть!\" Ста́рець же всю бра́тію глаша́єть і, ви́дівше всі чу́до, воспіва́ють:","Ра́дуйся, Ма́ти блага́я Христо́ва;","ра́дуйся, ти́хой пусти́ні Покро́ве.","Ра́дуйся, а́ще і не ві́ми, ки́їми Тя хвале́бними возвели́чим словеси́;","ра́дуйся, а́ще і не ві́ми, ки́я благода́тния принесе́м Ті похвали́.","Ра́дуйся, я́ко Світ преві́чний но́сиши неопали́мо;","ра́дуйся, я́ко Огнь іпоста́сний держи́ши непостижи́мо.","Ра́дуйся, Тя бо і́мами необори́мую сті́ну;","ра́дуйся, Тя бо всі ві́ми ми́лости ве́лію бе́здну.","Ра́дуйся, Херуви́мов честні́йшая;","ра́дуйся, Серафи́мов сла́внійшая.","Ра́дуйся, Бо́жия Ма́ти, сві́тлая на́ша Отра́до."]},{"h":"Кондак 9","ps":["І́ов, страда́лець пред Бо́гом, му́дренно нас поуча́єть, глаго́ля: се, благоче́стіє — му́дрость і бла́го всім уходя́щим от ми́ра і сла́достний по́двиг моли́тви под'є́мшим, і́мже помога́єть Богоро́диця і в моли́твах укріпля́єть, во є́же зва́ти: Аллилу́я."]},{"h":"Ікос 9","ps":["Ра́достно в хра́мі сем зря́ще спи́сок с іко́ни Отра́ди афо́нських оби́телей дар драгоці́нний, в моли́тві ми́сленно соєдині́мся с хвале́бними ли́ки афо́нських отце́в, і́же от го́рних висо́т, преви́ше о́блак су́щих, Пречи́стую нас пі́ти призива́ють:","Ра́дуйся, стран і наро́дов святи́не;","ра́дуйся, всіх христия́н благости́не.","Ра́дуйся, Огнь во утро́бу приі́мшая;","ра́дуйся, Сло́во по пло́ті яви́вшая.","Ра́дуйся, о́блаче сві́та ле́гкий, в мир прине́сший Христа́;","ра́дуйся, лі́ствице, веду́щая от землі́ в Небеса́.","Ра́дуйся, ста́мно ма́нни а́лчущим сла́дкия пи́щі;","ра́дуйся, ча́ше злата́я жа́ждущим но́ваго пи́ва.","Ра́дуйся, ти́хая А́нгелов сла́во;","ра́дуйся, лю́дем блага́я отра́до.","Ра́дуйся, ви́шнєє Не́бо, світ озаря́ющеє ві́рним;","ра́дуйся, ту́чная ни́во, всім веселя́щая ду́ші.","Ра́дуйся, Бо́жия Ма́ти, сві́тлая на́ша Отра́до."]},{"h":"Кондак 10","ps":["Ум к Небесі́ устреми́вше, чу́вства возне́сше над тле́ном, о, коль вожделі́нно спасти́ся от ми́ра, іму́ще єди́но ду́ха стремле́ніє ко го́рнім, єди́ну се́рдця наде́жду на Бо́га. Помога́й нам, Ді́во Богоро́дице, і в путь веди́ нас пра́вий, є́же пі́ти: Аллилу́я."]},{"h":"Ікос 10","ps":["О́браз честни́й провожда́я в путь от Афо́на на сі́вер в покро́в благода́тний оби́телі но́вия, в зало́г Небе́сния по́мощі гра́ду, честни́й схимона́х святого́рець віща́єть: Се благослове́ніє Влади́чиці! Молі́теся, і ві́руйте, і по́йте:","Ра́дуйся, я́ко єси́ нам покро́в благода́тний;","ра́дуйся, я́ко єси́ нам зало́г упова́ній.","Ра́дуйся, су́щим в біда́х утіше́ніє;","ра́дуйся, су́щим в греха́х умиле́ніє.","Ра́дуйся, я́ко в час гні́ва Бо́жия укріпля́єши сердца́;","ра́дуйся, я́ко в день іспита́нія умудря́єши уми́.","Ра́дуйся, я́ко злих наві́тов ту́чі от нас отвраща́єши;","ра́дуйся, я́ко в го́ди бі́дствій от поги́белі нас ізима́єши.","Ра́дуйся, я́ко во дні бур безбо́жних Ти єси́ нам єди́ная при́стань;","ра́дуйся, я́ко мудрова́ній ло́жних нас ізбавля́єши при́сно.","Ра́дуйся, в жи́зні нам ти́хая ра́досте;","ра́дуйся, во ві́чності ра́йськая сла́во.","Ра́дуйся, Бо́жия Ма́ти, сві́тлая на́ша Отра́до."]},{"h":"Кондак 11","ps":["Те́мния си́ли в ми́рі си́лою і сла́вою владі́ють і сві́та Христо́ва позна́ти не мо́гуть, но ві́рним то́кмо моли́тва єсть си́ла, їм сле́зи — зало́г і побі́ди, і сла́ви. О Ді́во Ма́ти, даждь нам ту́чу сле́зную і бо́дрственний нам вітр возве́й, пою́щим: Аллилу́я."]},{"h":"Ікос 11","ps":["Ра́дость на ли́цях сія́єть, глас вопіє́ть от Афо́на: Влади́чиця ше́ствуєть к вам, ісході́те, сріта́йте Ді́ву Небе́с со свіща́ми, сріта́йте же па́че Сію́ со слеза́ми ра́дости, любве́ і умиле́нія і пра́зднуйте, і сві́тлим гла́сом по́йте:","Ра́дуйся, Киво́те освяще́нний;","ра́дуйся, Престо́ле вознесе́нний.","Ра́дуйся, го́рних чино́во воспіва́ніє;","ра́дуйся, а́дових сил трепета́ніє.","Ра́дуйся, я́ко єси́ весе́ліє челові́чеським сердця́м;","ра́дуйся, я́ко єси́ спасе́ніє соврати́вшимся душа́м.","Ра́дуйся, я́ко глас Твой пресла́дкий ві́чную ра́дость віща́єть;","ра́дуйся, я́ко взор Твой прети́хий нам тишину́ обіща́єть.","Ра́дуйся, я́ко Си́на і Бо́га Ти умоля́єши о лю́діх;","ра́дуйся, я́ко ра́йських черто́гов Ти нам отверза́єши две́рі.","Ра́дуйся, хра́мино Ду́ха Свята́го;","ра́дуйся, ски́ніє Бо́га Жива́го.","Ра́дуйся, Бо́жия Ма́ти, сві́тлая на́ша Отра́до."]},{"h":"Кондак 12","ps":["А́нгельськи днесь воспіва́єм піснь благода́тній Марі́ї: Сія́ бо єсть сла́дость, і рай, і блаже́нство, отра́да в час іспита́ній і гні́ва, наде́жда блаже́нств безконе́чних по сме́рті. Ра́дуйся у́бо, Засту́пнице усе́рдная, і ра́дость подава́й нам пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Да защити́ть Богома́ти о́бразом ди́вним Отра́ди моли́тви опло́т — монасти́р сей і хра́ми, да во вік не уга́снеть лампа́да пред ли́ком спаси́тельним Ді́ви, со́нми же мона́хов гла́сом ра́дости с миря́ни немо́лчно взива́ють:","Ра́дуйся, хра́мі, світлі́йшій Сіо́на;","ра́дуйся, сві́те і сла́во Афо́на.","Ра́дуйся, і́ноков мисль непреста́нная;","ра́дуйся, ді́вственних піснь неумо́лчная.","Ра́дуйся, я́ко ро́су утіше́нія посила́єши во дні;","ра́дуйся, я́ко сле́зи умиле́нія історга́єши в нощі́.","Ра́дуйся, ди́вноє і́м'я, чудотворя́щеє вта́йні;","ра́дуйся, Бо́жиє ми́ро, в мир ізлія́нноє ще́дро.","Ра́дуйся, я́ко Тобо́ю ліє́ться нам світ безконе́чний;","ра́дуйся, я́ко с Тобо́ю ві́чно Младе́нець предві́чний.","Ра́дуйся, сві́тлосте лю́дем, Тя чту́щим;","ра́дуйся, ра́досте нам, Тя пою́щим.","Ра́дуйся, Бо́жия Ма́ти, сві́тлая на́ша Отра́до."]},{"h":"Кондак 13","ps":["О всепречи́стая Ді́во, сві́тлая на́ша Отра́до, сладча́йшаго Си́на нетлі́нная Ма́ти! От вся́ких бід і скорбе́й огражда́й нас і бу́дущия му́ки ізми́ нас, Блага́я, ра́дости же ві́чния сподо́би нас у го́рняго Престо́ла воспіва́ти: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов ли́ци див'я́ться, о́браз афо́нський Твой зря́ще, на не́мже, Пречи́стая Ді́во і Ма́ти, от уст нетлі́нних руко́ю десно́ю десни́цю Младе́нця отво́диши кро́тко. Что сіє́ єсть зна́меніє о́браза? Ми же рече́м, пою́ще такова́я:","Ра́дуйся, Ді́во, Всеви́шняго Ма́ти;","ра́дуйся, ди́вний раю́ благода́ті.","Ра́дуйся, на́ша Отра́до Небе́сная;","ра́дуйся, лю́дем Наде́ждо ізві́стная.","Ра́дуйся, о́браз бо Твой спасе́ніє возвіща́єть всей землі́;","ра́дуйся, взор бо Твой утіше́ніє пребива́ющим во тлі.","Ра́дуйся, сві́те Небе́сний, мглу на́ших дній озаря́яй;","ра́дуйся, цві́те нетлі́нний, тлін на́ших діл оживля́яй.","Ра́дуйся, Ти бо моли́тви к Си́ну за мир твори́ши;","ра́дуйся, я́ко в те́плой моли́тві, а́ки світи́льник, гори́ши.","Ра́дуйся, ра́достно Ті восклиця́єм;","ра́дуйся, пі́сненно Тя воспіва́єм.","Ра́дуйся, Бо́жия Ма́ти, сві́тлая на́ша Отра́до."]},{"h":"Кондак 1","ps":["Возбра́нних Сил Небе́сних ра́дость і хвале́ніє, всего́ же ро́да челові́ча ісправле́ніє, ублажа́єм Тя, Пречи́стая Ді́во Ма́ти, Ти же, на́ше упова́ніє єди́ноє, низпосли́ душа́м отра́ду благода́тную, да поє́м Тебе́, о́браз ди́вний Твой чту́ще:","Ра́дуйся, Бо́жия Ма́ти, сві́тлая на́ша Отра́до."]},{"h":"Молитва","ps":["О Пресвята́я Влади́чице Госпоже́ Ді́во Богоро́дице, Неві́сто нетлі́нная, Ма́ти благослове́нная, сві́тлая на́ша Отра́до, вожделі́нноє Утіше́ніє! Прийми́ ни́ні дерзнове́нноє і неотсту́пноє моле́ніє сіє́, от грі́шних усте́н і недосто́йних душ Тебі́ приноси́моє пред святи́м і світоза́рним Твої́м о́бразом. Пощади́ ни, ми́лостивая і милосе́рдная і щедролюби́вая на́ша Засту́пнице, і не преда́ждь нас суду́ і гні́ву Си́на Твоєго́ і Спа́са на́шего, Го́спода Ісу́са Христа́, Єму́же без числа́ согріши́хом і пови́нни єсьми́ осужде́нію і пра́ведному Єго́ ізрече́нію, є́же наказа́тися по гріхо́м на́шим, превозше́дшим вся́кую мі́ру Єго́ долготерпі́нія. Прини́кни с висо́т Твої́х го́рніх, іді́же А́нгели тре́петно сла́в'ять Тя, і воззри́ на на́шу до́льнюю нищету́: ка́ко обнища́хом ві́рою, ка́ко бі́дствуєм наде́ждею і оскуді́хом любо́вію, ка́ко умо́м омрачи́хомся, се́рдцем же і чу́встви ожесточи́хомся. Уврачу́й нас моли́твою Твоє́ю, Ді́во Ціле́бнице. Возста́ви ни, па́дшия ду́хом, укріпи́ разсла́бленния умо́м, возбуди́ уни́лия і отча́янния, ісціли́ боля́щия душе́ю і ті́лом. При́зри на град сей [іли́: оби́тель сію́, іли́: весь сію́] і пощади́ єго́ [іли́: ю], Бо́жий отводя́щи Твої́м предста́тельством гнів. Укроти́ го́рдостная стремле́нія люде́й і богоотсту́пная їх шата́нія. Возве́й ти́хоє диха́ніє благода́ті Твоєя́ на см'яте́нния ду́ші і сокруше́нная сердца́. Сохрани́ супру́жеству чистоту́, матери́нству честь, ді́вству благослове́ніє. Низпосли́ под кров жили́щ на́ших освяща́ющий луч боже́ственнаго сві́та, да облича́ться дія́нія неподо́бная і устидя́ться рі́чі ху́льния, і укротя́ться ми́слі зло́бния. О миролюби́вая, бла́гостнейшая і тиша́йшая Ді́во Ма́ти, о паде́ніїх на́ших скорб'я́щая, о спасе́нії на́шем воздиха́ющая! Утоли́ церко́вния бу́ри, умири́ раско́ли, собери́ расточе́нния, обрати́ отпа́дшия і всіх приведи́ в єдине́ніє Святи́я Це́ркве, да єдиноду́шно і єдиному́дренно сла́виться на землі́, я́коже і на Небесі́, єди́ноє святі́йшеє і спаси́тельноє і́м'я Єдиносу́щния Тро́йці, Отця́, і Си́на, і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["К Богоро́диці прилі́жно ни́ні притеце́м, / грі́шнії і смире́ннії, і припаде́м, / в покая́нії зову́ще із глубини́ душі́: / Влади́чице, помози́, на ни милосе́рдовавши, / потщи́ся, погиба́єм от мно́жества прегріше́ній. / Не отврати́ Твоя́ раби́ тщи, // Тя бо і єди́ну наде́жду і́мами."]},{"h":"Кондак, глас 8","ps":["Взбра́нной Воєво́ді побіди́тельная, / я́ко ізба́вльшеся от злих, / благода́рственная воспису́єм Ті, раби́ Твої́, Богоро́дице, / но, я́ко іму́щая держа́ву непобіди́мую, / от вся́ких нас бід свободи́, да зове́м Ті: // Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Поглянь на смирення»","e":"Akathist to the Theotokos before her icon “Look Upon My Humility”","secs":[{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді, Влади́чиці на́шей Богоро́диці, пресла́вним явле́нієм іко́ни Єя́ Святи́я, лю́ди богоспаса́ємаго гра́да Ки́єва ди́вно посетившей, благода́рственноє возглаша́єм пі́ніє. Ти же, я́ко Всеблага́я Засту́пнице ро́да христия́нськаго, от вся́ких нас бід свободи́, і от всіх враг ви́димих і неви́димих защити́, да с ві́рою Тебі́ зове́м:","Ра́дуйся, Пренепоро́чная Богоро́дице Ді́во ПРИ́ЗРИ НА СМИРЕ́НІЄ, с висоти́ небе́сній на смире́ніє рабо́в Твої́х призира́ющая."]},{"h":"Ікос 1","ps":["А́нгелов Цари́це і всея́ тва́рі Влади́чице, Пречи́стая Ді́во Богоро́дице, ми́лостивим явле́нієм нам о́браза Твоєго́ Свята́го, дре́вле богоспаса́ємий град Псков, а ни́ні град Ки́єв благода́тно озари́ла єси́ і струй чуде́с от него́ істочи́ла єси́ ві́рним. Ті́мже со усе́рдієм і любо́вію припа́дающе ко Пречи́стому Твоєму́ о́бразу, умиле́нния моле́нія возсила́єм милосе́рдому Твоєму́ к нам заступле́нію і со стра́хом зове́м:","Ра́дуйся, Цари́це на́ша Преблага́я, Наде́ждо на́ша Богоро́дице;","Ра́дуйся, Прия́телище си́рих і стра́нних Предста́тельнице;","Ра́дуйся, скорб'я́щих Ра́досте і оби́димих Покрови́тельнице;","Ра́дуйся, я́ко зри́ши на́шу біду́, зри́ши на́шу скорб;","Ра́дуйся, помагаєши нам, я́ко немощни́м, окормля́єши нас, я́ко стра́нних;","Ра́дуйся, я́ко не і́мами іни́я по́мощі, ра́зві Тебе́, ні іни́я Предста́тельниці;","Ра́дуйся, я́ко не і́мами Благи́я Уті́шительниці, то́кмо Тебі́, о, Богома́ти!","Ра́дуйся, я́ко да сохранявши нас і покривавши во ві́ки віко́в;","Ра́дуйся, Пренепоро́чная Богоро́дице Ді́во ПРИ́ЗРИ НА СМИРЕ́НІЄ, с висоти́ небе́сній на смире́ніє рабо́в Твої́х призира́ющая."]},{"h":"Кондак 2","ps":["Ви́дящи милосе́рдіє Твоє́ неісче́тноє, Всенепоро́чная Влади́чице, і мно́гая чудеса́, Тобо́ю явле́нная і присноявляємая чрез Святи́я іко́ни Твоя́, ї́миже, я́ко звізда́ми богосві́тлими, весь мир христия́нський украси́ла єси́, велича́єм Тя, возвели́чившую род наш Твої́м благоволе́нієм, і с любо́вію припа́даєм к Чудотво́рному О́бразу Твоєму́, пою́ще Си́ну Твоєму́ Христу́ Бо́гу: АЛЛИЛУ́Я."]},{"h":"Ікос 2","ps":["Ви́діша всі ві́рнії лю́ди Ки́євськия, я́ко Святи́й о́браз Бо́жия Ма́тері чуде́сно отобразися на стеклі киво́та, зіло́ удиви́шася і с благогові́нієм взира́юще на цільбоно́сную іко́ну тіле́снима очи́ма, потща́шася си́це возопи́ти Честні́йшей Херуви́м і Славнейшей без сравне́нія Серафи́м:","Ра́дуйся, я́ко О́браз Твой Честни́й преди́вно, без соді́йствія рук челові́чеських на стеклі киво́та отобразишася;","Ра́дуйся, всіх ві́рних явле́нієм сим зіло́ возра́довавшая і умили́вшая;","Ра́дуйся, Пречи́стая, призира́я на смире́ніє, сли́шиши глас наш і вся очищавши беззако́нія на́ша;","Ра́дуйся, Ді́во, ме́ртва змі́я живоно́сним Рождество́м Твої́м соді́лавшая;","Ра́дуйся, Богороди́тельнице, жизнь нестарі́ющую улучи́ти нам помагаєши моли́твами Твої́ми;","Ра́дуйся, Сло́во О́тчеє ро́ждшая, пла́мень страсте́й на́ших росо́ю моли́тв Твої́х погашающая;","Ра́дуйся, Блага́я Уті́шительнице, Ма́терніми моли́твами Твої́ми бу́ри серде́ць на́ших утишающая;","Ра́дуйся, ісправля́я моли́тви рабо́в Твої́х, разріше́ніє мно́гих на́ших прегріше́ній подаю́щая.","Ра́дуйся, Пренепоро́чная Богоро́дице Ді́во ПРИ́ЗРИ НА СМИРЕ́НІЄ, с висоти́ небе́сній на смире́ніє рабо́в Твої́х призира́ющая."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго соді́ла Тя, Благода́тная, істо́чник неоскудевающ утіше́нія бедствующим. Мно́гі бо ско́рби, претерпі́вши, мо́жеши і іскуша́ємим по́мощі. Лю́дем же на́шим, лю́ті стра́ждущим от неві́рія і заблужде́нія, благоволи́ла єси́ ми́лостивно яви́ти благода́тноє сокро́вище сіє́ - Чудотво́рний О́браз Твой, - во хра́мі Свя́то-Введенськом в зна́меніє ми́лости Твоєя́ ко землі́ на́шей, в защи́ту от враг ви́димих і неви́димих, тім же по́мощію Бо́жиєю подкрепляєми, Спаси́телю Бо́гу пої́м: АЛЛИЛУ́Я."]},{"h":"Ікос 3","ps":["Я́коже дре́вле цар повелі́ при Тихвинськой іко́ні бра́тії поселитися і сла́ву, Тебі́ Пречи́стій, воспіва́ти і о всем ми́рі моли́тву приноси́ти. Та́ко і ни́ні повелі́ митрополи́т Влади́мир оби́телі би́ти і бра́тіям собравшимся пред Твої́м новоявленним чу́дним о́бразом моле́нія о всіх лю́діх приноси́ти і воспіва́ти Ті:","Ра́дуйся, освяти́вшая зе́млю ки́євськую Свої́м явле́нієм;","Ра́дуйся, утесня́ємим осла́бу і свобо́ду да́рующая;","Ра́дуйся, ненака́занних Ми́лостивая Наказательнице;","Ра́дуйся, неразу́мних Прему́драя Вразумительнице;","Ра́дуйся, оби́дящих Всегрозная Устрашительнице;","Ра́дуйся, оби́димим Всеблага́я Засту́пнице;","Ра́дуйся, ду́ха уни́нія і боя́зні отгна́ніє.","Ра́дуйся, Пренепоро́чная Богоро́дице Ді́во ПРИ́ЗРИ НА СМИРЕ́НІЄ, с висоти́ небе́сній на смире́ніє рабо́в Твої́х призира́ющая."]},{"h":"Кондак 4","ps":["Я́ко лучеза́рную звізду́, я́ко но́воє зна́меніє ми́лости Своєя́ яви́ла єси́ ни́ні, Пренепоро́чная Ді́во, ві́рним богоспаса́ємаго гра́да Ки́єва, честну́ю іко́ну Твою́ \"ПРИ́ЗРИ НА СМИРЕ́НІЄ\" в годи́ну но́вих іспита́ній, нестроє́ній і злих развраще́нії врага́ми ві́ри і Оте́чества на́шего воздвиза́ємих, да утверди́ться благоче́стіє і да укріпи́ться ві́ра правосла́вная в лю́діх. Ми же в сем явле́нії уразумі́в зна́меніє ве́лія попече́нія Бо́жия о мі́сті сем, со тре́петом і благогові́нієм глаго́лем Ті, Цари́це Небесе́ і землі́: \"Ти єси́ нам щит непобіди́мий і стіна́ необори́мая\" восхваля́ющих Тя і воспіва́ющих Бо́гу піснь: АЛЛИЛУ́Я."]},{"h":"Ікос 4","ps":["Сли́шавше о дивном чудеси́ явле́нія Святи́я іко́ни Твоєя́ во гра́ді Ки́єве, Преблагослове́нная Цари́це Не́ба і землі́, всі лю́діє подвиго́шася во храм Твой взира́юще і див'яще чудеси́ сему́ і со благогові́нієм і ра́достію поклоня́шеся Чудотво́рному О́бразу Твоєму́ і хвалебне зову́ще Ті:","Ра́дуйся, Обрі́тшая благода́ть у Бо́га і бо́льше А́нгелов і всіх святи́х возвели́ченная;","Ра́дуйся, Ма́ти Бо́жия, крі́пкаго во бра́ніх Христа́ ро́ждшая, ізбавля́ющая нас от печа́лей і лю́тих нападе́ній вра́жиїх;","Ра́дуйся, ро́ждшая Живода́вця Христа́ несказа́нно, ме́ртвих нас душа́ми оживотворяющая; ра́достію осія́нную. Во виді́нії сем уразумі́в Тя, Ма́тер Ра́дуйся, Влади́чице, освяща́ющая оскверне́нния се́рдця на́ша, я́же Пресвято́є Сло́во ро́ждшая;","Ра́дуйся, Ми́лостивая, простирающая нам ру́ку по́мощі, да спаса́ємий, ви́ну ублажа́єм Тя;","Ра́дуйся, Ді́во Богора́дованная, кропле́нієм ми́лости Твоєя́ погашающая у́гліє страсте́й на́ших;","Ра́дуйся, уга́сший світи́льник серде́ць на́ших возжига́ющая;","Ра́дуйся, сотворя́ющая ми́лостива нам Судію́, Си́на Твоєго́;","Ра́дуйся, нечи́стих страсте́й нас свобожда́ющая і сла́ви ві́чния сподобля́ющая.","Ра́дуйся, Пренепоро́чная Богоро́дице Ді́во ПРИ́ЗРИ НА СМИРЕ́НІЄ, с висоти́ небе́сній на смире́ніє рабо́в Твої́х призира́ющая."]},{"h":"Кондак 5","ps":["Єгда́ яви́ся чу́до от іко́ни Твоєя́, ві́рнії возра́довашася, а неві́рнії удивля́хуся \"ка́ко сіє́ мо́жеть би́ти\" і ізучаху сіє́ і познава́ху си́лу Пречи́стия і по недолзе вре́мені возгласи́ша привселюдно я́ко сіє́ нерукотворно би́ша, ми же па́ки і па́ки ми́лості Твоє́й дивля́хуся, я́ко да на́шу недосто́йную моли́тву при́зрить Госпо́дь, Цар Сла́ви і послу́шаєть проше́нія всіх с ві́рою призива́ющих і́м'я Твоє́ Свято́є, і Си́ну же Твоєму́ зову́щих: АЛЛИЛУ́Я."]},{"h":"Ікос 5","ps":["Возсія́ нам благода́ть світоза́рная от чудотво́рния іко́ни Твоєя́, Богоізбра́нная Отрокови́це, пред Не́ю же со слеза́ми припа́дающе, моли́мтися: отжени́ о́блак наше́дших на ни іскуше́ній і бід, да вопіє́м Ті ра́достно:","Ра́дуйся, Всепі́тая, Двер Небе́сная, отверза́ющая нам двер спасе́нія;","Ра́дуйся, Чи́стая, ру́ку по́мощі нам простирающая і із глубини́ болі́зней возводя́щая;","Ра́дуйся, Святі́йшая, Світ Невеще́ственний ро́ждшая, тьми страсте́й нас свобожда́ющая;","Ра́дуйся, А́нгелов Ра́досте, пра́ведников Добро́та, ві́рних Наде́жда і на́ше соблюде́ніє;","Ра́дуйся, Мо́сте к Жи́зні Несостарі́ющейся приводя́щий, ві́рою і любо́вію Тя велича́ющий;","Ра́дуйся, вознося́щая рог ві́рних, пою́щих Тя, Ді́во, і поклоняющихся честно́му о́бразу Твоєму́;","Ра́дуйся, наставля́ющая к доброді́телі Небе́снаго Ца́рствія і поко́я Боже́ственнаго;","Ра́дуйся, ру́ку по́мощі нам подаю́щая і ко приста́нищу спаси́тельному направля́ющая.","Ра́дуйся, Пренепоро́чная Богоро́дице Ді́во ПРИ́ЗРИ НА СМИРЕ́НІЄ, с висоти́ небе́сній на смире́ніє рабо́в Твої́х призира́ющая."]},{"h":"Кондак 6","ps":["Пропові́дник неізрече́нних чуде́с Твої́х, Ма́ти Бо́жия, яви́ся святи́й храм Твой во гра́ді Ки́єве, в нем бо ди́вноє Бо́жиє смотре́ніє о нас Тобо́ю, Ді́во чи́стая, іспо́лнися. Єгда́ сокрове́нноє жела́ніє се́рдця на́шего украси́ти пречу́дний лик Твой, Цари́це Небе́сная, драгоці́нним вінце́м із ка́меней честни́х, ми́лостивно усли́шала єси́. Нас же грі́шних і недосто́йних, прилі́жно притека́ющих к пресла́вному о́бразу Твоєму́, в покая́нії зову́щих із глубини́ душі́: \"Влади́чице, спаси́ ни погибающия от мно́жества прегріше́ній на́ших, да ви́ну благодари́м і велича́єм Тя, на́шу ско́рую і ди́вную помо́щницю, поя́ Бо́гу: АЛЛИЛУ́Я\"."]},{"h":"Ікос 6","ps":["Я́коже дре́вле іуде́ї для ски́нії приноша́ху зла́то і сребро́, та́ко і лю́діє на́ші получаху Тобо́ю ісціле́нія, благодаря́ще Тя, приноша́ху Ті сребро́ і зла́то, Пречи́стая Ски́ніє, і по сем о́браз Твой Святи́й украси́ благолі́пними да́ри ри́зою драгою і вінце́м, припа́даєм Ті і со слеза́ми вопіє́м та́ко:","Ра́дуйся, Богоро́дице Ді́во, і рождаєши, і чи́ста по рождестві́ явиласи єси́;","Ра́дуйся, Блага́я, дух сокруше́нія і смире́ніє серде́ць нам подаю́щая, уму́ же чистоту́ і житію́ ісправле́ніє;","Ра́дуйся, Всенепоро́чная, прегріше́ній оставле́ніє і слез істо́чники нам да́рующая;","Ра́дуйся, си́лою моли́тв Твої́х я́зви душ на́ших ісціля́єши;","Ра́дуйся, Ча́ше жи́зні і безсме́ртія, ко врата́м ві́чния жи́зні нас приводя́щая;","Ра́дуйся, Ізбавля́ющая нас от мно́гих бід, скорбе́й і будущего Суда́ Стра́шнаго;","Ра́дуйся, Живоно́сний Істо́чниче нетлі́нія і ра́дости, жаждущия душі́ на́ша напояющая;","Ра́дуйся, Всеми́лостивая, кро́тким сія́нієм Твої́м мрак страсте́й і поро́ков на́ших разгоня́ющая.","Ра́дуйся, Пренепоро́чная Богоро́дице Ді́во ПРИ́ЗРИ НА СМИРЕ́НІЄ, с висоти́ небе́сній на смире́ніє рабо́в Твої́х призира́ющая."]},{"h":"Кондак 7","ps":["Хотя́й долготерпіли́вий Госпо́дь яви́ти Своєго́ Человіколю́бія неізслі́димую щедро́т бе́здну, ізбра́ Тебе́ Єди́ну в Ма́тер Себе́ і сотвори́ Тя лю́дем непреодолі́нноє защище́ніє: да кто от них пра́ведним судо́м Бо́жиїм осужде́нія досто́їн яви́ться, Твої́м оба́че держа́вним покро́вом сохраня́ється на покая́ніє, зови́й: АЛЛИЛУ́Я."]},{"h":"Ікос 7","ps":["Но́вая купі́ль Силоа́мськая па́че о́ния дре́внія, яви́ся, Пречи́стая Влади́чице, храм Свята́го Введе́нія Твоєго́, в нем же всі ві́рнії поклоня́ються чудотво́рній іко́ні Твоє́й і моле́бния пі́нія ви́ну пред То́ю соверша́ють, да не сокри́т бу́деть істо́чник благода́тних врачева́ній всім тре́бующим. Сего́ ра́ди ми не таї́м Твої́х благодія́ній, Всенепоро́чная, но благода́рственні вопіє́м:","Ра́дуйся, А́гнице, ро́ждшая А́гнця, вземлющего гріхи́ ми́ра;","Ра́дуйся, красна́ душе́ю, красна́ ті́лом, красна́ помишле́нієм, Ді́во Пречи́стая, скве́рну душ на́ших очища́ющая;","Ра́дуйся, всіх Освяще́нная Сі́не, ісціле́нія от дланей Твої́х точа́щая нам ви́ну;","Ра́дуйся, Виногра́д Боже́ственний, Кра́сний Грозд ізрасти́вшая, душа́м на́шим даю́щая питіє́ незави́стноє;","Ра́дуйся, Ріко́ Приснотеку́щая ісціле́ній і Мо́ре, вся на́ша стра́сті потопляющеє;","Ра́дуйся, Єди́на Нетлі́нная, в земно́м житії́ сем покро́вом ми́лости Своєя́ нас покрива́ющая;","Ра́дуйся, я́ко ма́терніми моли́твами Твої́ми ізбавля́ємся болі́зненних напа́стей і вся́каго вре́да душе́внаго і тіле́снаго;","Ра́дуйся, Всеблага́я на́ша Наста́внице, за вся благодія́нія Твоя́ благодаре́нію нас науча́ющая.","Ра́дуйся, Пренепоро́чная Богоро́дице Ді́во ПРИ́ЗРИ НА СМИРЕ́НІЄ, с висоти́ небе́сній на смире́ніє рабо́в Твої́х призира́ющая."]},{"h":"Кондак 8","ps":["Все житіє́ на́ше на землі́ болі́зненно і печа́лі іспо́лнено от клевети́, досажде́нія, укоре́нія і іни́х многови́дних бід і напа́стей; немоществу́єть бо ті́ло, ізнемога́єть і дух наш. К Тебі́ у́бо прибіга́єм, Благода́тная, пред Пречи́стим о́бразом Твої́м припа́дающе: іспо́лни ра́дости і весе́лія ско́рбния се́рдця на́ша, да вопіє́м ви́ну Бо́гу: АЛЛИЛУ́Я."]},{"h":"Ікос 8","ps":["Стра́нноє виді́ніє бисть челові́ку ні́коєму, єгда́ стоя́ на моли́тві і за сродницю без покая́нія почи́вшую, моли́тву принося́ща, внеза́пу узрі́ Святи́й о́браз Твой, Влади́чице, на стіні́ явле́нний, а посе́м на том же мі́сті саму́ почи́вшую ви́дів, небе́сною ра́достію осія́нную. Во виді́нії сем уразумі́в Тя, Ма́тер Сві́та, во Ви́шніх пребива́ющую і хода́тайства за живи́х і ме́ртвих Си́ну Твоєму́ ви́ну принося́щую, іспо́лнися духо́вния ра́дости і весе́лія ско́рбноє се́рдце єго́ і возопи́ такова́я:","Ра́дуйся, от принося́щих Тебі́ благода́рния да́ри ли́ка Твоєго́ не отвращающая, і почившим сро́дникам їх загробную участь облегча́ющая;","Ра́дуйся, уповающим на Тя живота́ непости́дний коне́ць да́рующая;","Ра́дуйся, і по сме́рті за отше́дшую на суд Госпо́день ду́шу пред Сино́м Твої́м неотсту́пно хода́тайствующая;","Ра́дуйся, скорб'я́щих роди́телей в лише́нії чад їх утіша́ющая благода́тною Твоє́ю по́мощію;","Ра́дуйся, неуста́нная Моли́твеннице на́ша, ти́хий і безболі́зненний отход із сей юдо́лі пла́ча і ско́рби нам низпосила́ющая;","Ра́дуйся, в гро́зний час сме́рти за ві́рно чту́щих Тя предста́тельствующая і от возду́шних мита́рств ізбавля́ющая;","Ра́дуйся, Ми́лостивая, ми́лость Свою́ нам явля́ющая в день іспита́нія, в о́ньже откри́ються вся діла́ на́ша до́брая же і зла́я;","Ра́дуйся, Милосе́рдая, покая́нія грі́шников не отверга́ющая і от ро́ва поги́белі милосе́рдієм Твої́м ісхища́ющая.","Ра́дуйся, Пренепоро́чная Богоро́дице Ді́во ПРИ́ЗРИ НА СМИРЕ́НІЄ, с висоти́ небе́сній на смире́ніє рабо́в Твої́х призира́ющая."]},{"h":"Кондак 9","ps":["Все єстество́ а́нгельськоє похва́льная пі́сні прино́сить Тебі́, і́стинній Ма́тері Бо́жієй і Засту́пнице всіх приходя́щих к Тебі́ і прося́щих Твоєя́ по́мощі, я́ко тве́рдим і крі́пким Твої́м предста́тельством пра́ведних весели́ши, грі́шних заступа́єши, печа́лі утоля́єши, сро́дником на́шим почившим загробную участь облегча́єши, і мо́лишися о всіх нас, ві́рою зову́щих Си́ну Твоєму́: АЛЛИЛУ́Я."]},{"h":"Ікос 9","ps":["Челові́честії ві́тіії суємудренії недоуміва́ють позна́ти Боже́ственную та́йну Твоєго́ Присноді́вства, Богоро́дице, ніже́ мо́гуть із'яснити си́лу чудотво́рную от іко́н Святи́х Твої́х проістекающую, во ісціле́ніє неду́жних і на вся́кую по́льзу душе́вную і тіле́сную челові́ком. Ми же благоче́стно, Ма́тер і Ді́ву, Тя іспові́дающе, досто́йно хва́лим сла́вний, Влади́чице, іко́ни Твоєя́ пра́здник, ві́рно поклоня́ємся о́бразу Твоєму́ Свято́му і с любо́вію вопіє́м:","Ра́дуйся, Богоневі́сто, Світ ро́ждшая Боже́ственний і Преві́чний;","Ра́дуйся, Ма́ти і Ді́во Преблагослове́нная; Ра́дуйся, ма́терей при́сноє ра́дованіє;","Ра́дуйся, Єди́на Непоро́чная і До́брая в жена́х;","Ра́дуйся, А́нгелов Сла́во, Столп утвержде́нія і Сокро́вище спасе́нія;","Ра́дуйся, Цари́це Небе́сная, істо́чник нетлі́нія і двер покая́нія;","Ра́дуйся, благосе́рдая Ма́ти всіх скорб'я́щих і обремене́нних;","Ра́дуйся, Держа́вная Засту́пнице ро́да християнського.","Ра́дуйся, Пренепоро́чная Богоро́дице Ді́во ПРИ́ЗРИ НА СМИРЕ́НІЄ, с висоти́ небе́сній на смире́ніє рабо́в Твої́х призира́ющая."]},{"h":"Кондак 10","ps":["Спаси́теля па́дшему челові́честву родила́ єси́, Всенепоро́чная Ді́во, і Сего́, я́ко Младе́нця во об'ятіях Твої́х носи́ла єси́. Єго́же Боже́ственноє ізображе́ніє і на честні́й іко́ні Твоє́й нам являвши і мно́гая ми́лості і щедро́ти Твоя́ нам да́руєши. Сего́ ра́ди с ві́рою і любо́вію честву́єм о́браз Чудотво́рний Твой, Влади́чице, і мо́лимся Тебі́ прилі́жно: бу́ди покро́в і защи́та нам в день Су́дний, да Твої́м Ма́тернім предста́тельством поми́луєть нас Судія́ пра́ведний, Син Твой, і сподо́бит десна́го стоя́нія і пі́нія Єму́ со всі́ми ізбра́нними: АЛЛИЛУ́Я."]},{"h":"Ікос 10","ps":["Стіна́ і покро́в єси́ гра́ду Пско́ву даде́ся Свята́я іко́на Твоя́, Цари́це і Влади́чице, мно́гажди град сей от разоре́нія ратного сохрани́ла єси́. І ни́ні нас грі́шних і недосто́йних чад Твої́х ми́лостивно посіти́ла єси́ чу́дним явле́нієм Пречи́стаго Твоєго́ о́браза і благоутро́бно приє́млеши пред Ним возноси́мия Тебі́ от благода́рних серде́ць на́ших моли́тви с пі́нієм такови́м:","Ра́дуйся, я́коже дре́вле іко́ною Успе́нія сла́вний град Ки́єв многократно спаса́ла єси́, та́ко і ни́ні нас пречудною іко́ною Твоє́ю от бід огражда́єши;","Ра́дуйся, Ла́ври Кі́єво-Пече́рськия сла́вная строїтельнице і хра́мов єя́ всечестна́я украсительнице;","Ра́дуйся, Храни́тельнице Ди́вная і іни́х оби́телей святи́х, я́ко Твоє́ю благода́тною си́лою о́ния зиждяться і преуспевають в благоче́стії;","Ра́дуйся, просла́вившая мі́сто явле́нія іко́ни Твоєя́ ди́вним чудоді́йствієм і всім ми́лость преізобильную нам показа́вшая;","Ра́дуйся, Богоневі́сто Пречи́стая, святи́й лик Твой чту́щих от осужде́нія і мук многообра́зних ізбавля́ющая;","Ра́дуйся, Многоми́лостивая Покрови́тельнице на́ша, от пречу́дния іко́ни Твоєя́ ми́лости нам неоску́дно істоча́ющая;","Ра́дуйся, Влади́чице, ма́терніми моли́твами Твої́ми душі́ на́ша от мрачного сна восставляющая к Твоєму́ славосло́вію;","Ра́дуйся, Ра́досте ми́ру, я́ко о Тебі́ ра́дується а́нгельський собо́р і челові́чеський род.","Ра́дуйся, Пренепоро́чная Богоро́дице Ді́во ПРИ́ЗРИ НА СМИРЕ́НІЄ, с висоти́ небе́сній на смире́ніє рабо́в Твої́х призира́ющая."]},{"h":"Кондак 11","ps":["Пі́ніє моле́бноє на́ше с ві́рою і любо́вію возноси́моє, ми́лостивно усли́ши, Госпоже́ Влади́чице, і утро́бу щедро́т Твої́х не затвори́ нам, Всеще́драя Богоро́дице: се бо обнища́вше в до́брих ді́ліх, к сокровищнице ми́лости Твоєя́, - чу́дній іко́ні Твоє́й, - со усе́рдієм притека́єм, Всеблага́я, і припа́дающе к Ней, мо́лимся: сохрани́ ни от тлітво́рних уче́ній, ізба́ви от лука́вих совращеній, спаси́ Оте́чество на́ше от нестроє́ній і злих нападе́ній вра́жиїх, і сподо́би в любві́ і єдиноми́слії со всі́ми ві́рними ча́дами Святи́є Христо́ви Це́ркві, благоприя́тно пі́ти Созда́телю на́шему піснь: АЛЛИЛУ́Я."]},{"h":"Ікос 11","ps":["Сві́тлими луча́ми чуде́с немерцаємо сія́єть Свята́я іко́на Твоя́, Всенепоро́чная Богоро́дице Ді́во, просвещавши бо нас, помраче́нних гріхо́вною мгло́ю і приво́диши к немолчному славосло́вію Твоєго́ Пресвята́го І́мене. Тім же ра́дуємся, ми грі́шнії, іму́ще такови́й зало́г Твоєго́ к нам благоволе́нія, і Тебі́, ско́рой Помо́щнице на́шей, благода́рственно взива́єм:","Ра́дуйся, Цари́це і Влади́чице, сві́том Твої́м небе́сним нас освяща́ющая і под кро́вом Твої́м ви́ну сохраня́ющая;","Ра́дуйся, Благослове́нная і Препросла́вленная, Ма́ти Неіскусому́жная, умервщленния гріха́ми душі́ на́ша оживотворяющая;","Ра́дуйся, Чи́стая і Непоро́чная Ді́во, Ти бо родила́ єси́ Си́на, ізбавляющего нас от іскуше́ній;","Ра́дуйся, Всесла́вная Влади́чице Богоро́дице, от вся́ких ни зол і скорбе́й ісхища́ющая і но́зі на́ша на ка́мене боже́ственнаго спасе́нія поставляющая;","Ра́дуйся, Чи́стая А́гнице, Ді́во, Ма́ти, Отрокови́це, чи́сти ни сотворя́ющая от страсте́й тіле́сних;","Ра́дуйся, я́ко да льсти́ваго ізбавля́ються сіте́й, всі песнослов'ящия Тя, Богора́дованная;","Ра́дуйся, Гора́ Ве́лія, Ю́же Данії́л прови́ді, із Нея́ же Честни́й Ка́мень, - Христо́с, -- пло́тію облече́ся;","Ра́дуйся, Ді́во Чи́стая, Жезл із ко́рене Ієїсеєва, цветовозрастивши нам всеси́льнаго Го́спода;","Ра́дуйся, Пренепоро́чная Богоро́дице Ді́во ПРИ́ЗРИ НА СМИРЕ́НІЄ, с висоти́ небе́сній на смире́ніє рабо́в Твої́х призира́ющая."]},{"h":"Кондак 12","ps":["Благода́ті Бо́жия Свято́є і Непоро́чноє жили́ще, Ма́ти Го́спода Ви́шніх сил, не возгнуша́йся нас грі́шних і недосто́йних, воспіва́ющих ми́лости от всечестни́я іко́ни Твоєя́ нам явле́нния, і Твої́м невече́рнім сія́нієм озари́ на́ша те́мния душі́, приводя́щи к Сві́ту Трисо́лнечнаго Божества́; в Правосла́вії укріпи́ нас, Всеблага́я, і сподо́би до коне́чнаго воздиха́нія на́шего пі́ти немо́лчную піснь Вседержи́телю: АЛЛИЛУ́Я."]},{"h":"Ікос 12","ps":["Пою́ще піснь хвали́ і благодаре́нія Тебі́, Богора́дованная Ді́во, пропові́дуєм велегла́сно вели́чіє чуде́с Твої́х і бога́тство ми́лости Твоєя́, на нас і Оте́честві на́шем явле́нних, і от глубини́ серде́чния прино́сим Тебі́ со смире́нієм похва́льния да́ри сія́:","Ра́дуйся, Правосла́вія Несокруши́мая Крі́посте і Огра́до; Ра́дуйся, Непобіди́мая Воєво́до вожде́й і во́їнств христия́нських;","Ра́дуйся, Нело́жноє Спасе́ніє і Предста́тельнице ми́ра, ро́ждшая Зижди́теля, І́мже от напа́стей і болі́зней спасе́ся мир;","Ра́дуйся, Ми́сленния Две́рі Жи́зні, покая́нія нам две́рі отверза́ющая;","Ра́дуйся, Єди́на Благослове́нная, в час сме́рти те́мния зра́ки лука́вих бісо́в дале́че от нас прогоня́ющая;","Ра́дуйся, Єди́на Милосе́рдая, в стра́шний день Суда́, ві́чния муки́ нас ізбавля́ющая і неізрече́нния сла́ви Си́на Твоєго́ наслі́дники ни показу́ющая;","Ра́дуйся, Всенепоро́чная, ви́ну человіколю́біє Твоє́ явля́ющая і от собла́знов і сіте́й вра́жиїх нас свобожда́ющая;","Ра́дуйся, Пречи́стая, Сотворившая с на́ми зна́меніє во бла́го: да ви́дять ненави́дящії нас і постидя́ться, я́ко Ти вняла єси́ проше́ніям на́шим і уті́шила ни.","Ра́дуйся, Пренепоро́чная Богоро́дице Ді́во ПРИ́ЗРИ НА СМИРЕ́НІЄ, с висоти́ небе́сній на смире́ніє рабо́в Твої́х призира́ющая."]},{"h":"Кондак 13","ps":["О, Всепі́тая Ма́ти Го́спода на́шего Ісу́са Христа́, неісчерпа́ємоє мо́ре Боже́ственних даро́в, Ти єси́, Всесвята́я Ді́во! Я́ко светоподательную лампа́ду, єле́єм ми́лости іспо́лненную, созерца́єм Тя оча́ми ві́ри і кро́тким сія́нієм Твої́м озаряєми, любо́вію же Твоє́ю при́сно согріва́ємії, Тебі́, я́ко благо́й Засту́пниці на́шей, со умиле́нієм глаго́лем: прийми́ благоутро́бно моле́бноє пі́ніє на́ше, пред Чу́дною іко́ною Твоє́ю с ві́рою Тебі́ возноси́моє, і всеси́льними моли́твами Твої́ми умоли́, Влади́чице, ізба́витися нам грі́шним вре́менних бід і ві́чния муки́, да спасе́ннії Тобо́ю просла́вим і в бу́дущей жи́зні Всесвято́є і́м'я Си́на Твоєго́ і Бо́га на́шего, ві́рно зову́ще Єму́: АЛЛИЛУ́Я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Цари́це і всея́ тва́рі Влади́чице, Пречи́стая Ді́во Богоро́дице, ми́лостивим явле́нієм нам о́браза Твоєго́ Свята́го, дре́вле богоспаса́ємий град Псков, а ни́ні град Ки́єв благода́тно озари́ла єси́ і струй чуде́с от него́ істочи́ла єси́ ві́рним. Ті́мже со усе́рдієм і любо́вію припа́дающе ко Пречи́стому Твоєму́ о́бразу, умиле́нния моле́нія возсила́єм милосе́рдому Твоєму́ к нам заступле́нію і со стра́хом зове́м:","Ра́дуйся, Цари́це на́ша Преблага́я, Наде́ждо на́ша Богоро́дице;","Ра́дуйся, Прия́телище си́рих і стра́нних Предста́тельнице;","Ра́дуйся, скорб'я́щих Ра́досте і оби́димих Покрови́тельнице;","Ра́дуйся, я́ко зри́ши на́шу біду́, зри́ши на́шу скорб;","Ра́дуйся, помагаєши нам, я́ко немощни́м, окормля́єши нас, я́ко стра́нних;","Ра́дуйся, я́ко не і́мами іни́я по́мощі, ра́зві Тебе́, ні іни́я Предста́тельниці;","Ра́дуйся, я́ко не і́мами Благи́я Уті́шительниці, то́кмо Тебі́, о, Богома́ти!","Ра́дуйся, я́ко да сохранявши нас і покривавши во ві́ки віко́в;","Ра́дуйся, Пренепоро́чная Богоро́дице Ді́во ПРИ́ЗРИ НА СМИРЕ́НІЄ, с висоти́ небе́сній на смире́ніє рабо́в Твої́х призира́ющая."]},{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді, Влади́чиці на́шей Богоро́диці, пресла́вним явле́нієм іко́ни Єя́ Святи́я, лю́ди богоспаса́ємаго гра́да Ки́єва ди́вно посетившей, благода́рственноє возглаша́єм пі́ніє. Ти же, я́ко Всеблага́я Засту́пнице ро́да христия́нськаго, от вся́ких нас бід свободи́, і от всіх враг ви́димих і неви́димих защити́, да с ві́рою Тебі́ зове́м:","Ра́дуйся, Пренепоро́чная Богоро́дице Ді́во ПРИ́ЗРИ НА СМИРЕ́НІЄ, с висоти́ небе́сній на смире́ніє рабо́в Твої́х призира́ющая."]},{"h":"Молитва","ps":["О, Пресвята́я Госпоже́, Ді́во Богоро́дице, ви́сшая Херуви́м і Честні́йшая Серафи́м, Богоізбра́нная Отрокови́це! При́зри с висоти́ небе́сній ми́лостивним Твої́м о́ком на нас, недосто́йних рабо́в Твої́х, со умиле́нієм і слеза́ми моля́щихся пред Пречи́стим о́бразом Твої́м; не лиши́ нас Твоєго́ заступле́нія і покро́ва Держа́внаго в стра́нствії сем земно́м, многоскорбном і многом'ятежном. Спаси́ нас в поги́белі і ско́рби су́щих, воздви́гни із глубини́ гріхо́вния, просвіти́ ум наш, омраче́нний страстьми́ і уврачу́й я́зви душ і тіле́с на́ших! О, Всеще́драя Ма́ти Человіколюби́ваго Влади́ки! Удиви́ на нас пребога́тия ми́лості Твоя́, укріпи́ немощну́ю во́лю на́шу к ді́ланію за́повідей Христо́вих, ум'ягчи́ окамені́лая се́рдця на́ша любо́вію к Бо́гу і бли́жнім, да́руй нам сокруше́ніє серде́чноє і покая́ніє і́стинноє, да очи́стившеся от скве́рни гріхо́вния, сподо́бимся ми́рния христия́нськия кончи́ни і до́браго отві́та на Стра́шнім і нелицеприятном Суді́ Го́спода на́шего Ісу́са Христа́, Єму́же со Безнача́льним Єго́ Отце́м і Пресвяти́м, Благи́м і Животворя́щим Ду́хом, подоба́єть вся́кая сла́ва, честь і поклоне́ніє, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Необори́мая стіна́ о́браз Твой і істо́чник чуде́с, / я́коже дре́вле от Него́ заступле́ніє Твоє́ гра́ду Пско́ву дарова́ла єси́, / та́ко і ни́ні нас от всіх бід і скорбе́й ми́лостивно ізба́ви / і спаси́ ду́ші на́ша я́ко любвеоби́льная Ма́ти."]},{"h":"Кондак, глас 3","ps":["Пренепоро́чная Ді́во, / отображе́ніє Ли́ка Твоєго́ чту́щих благода́рния да́ри приє́млеши, / живи́м і ме́ртвим помога́єши, / град і страну́ на́шу заступа́єши, / і к Си́на Твоєму́ моли́тви прино́сиши, // і спа́саєши всіх нас."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Богоізбра́нная Отрокови́це, / і чтем святи́я іко́ни Твоєя́ // чуде́сноє отображе́ніє."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Аз єсьм з вами, і ніхто же на вы»","e":"Akathist to the Theotokos before her icon “I Am with You, and No One Shall Be Against You”","secs":[{"h":"Кондак 1","ps":["Ізбра́нной от всіх родо́во Влади́чице ми́ра, Ді́ві Богоро́диці, принесе́м похвальниє да́ри, я́коже і ни́ні, а́ки і пре́жде па́дших возставля́єши, немощни́х укріпля́єши, боля́щих ісціля́єши, от враг ви́димих і неви́димих ізбавля́єши, сомня́щихся вразумля́єши, унива́ющих ободряєши, ві́ровати в Благода́тную си́лу святи́х іко́н Твої́х науча́єши і в благодарности умиле́нним се́рдцем і усти́ пі́ти Тебі́ сподобляєши:","Ра́дуйся, Небе́сная на́ша Ма́ти, Твої́ми словеси́ \"Аз єсьм с ва́ми і нікто́же на ви\" благода́тную си́лу душа́м на́шим да́рующая."]},{"h":"Ікос 1","ps":["А́нгели на небесі́ воспіва́ють вели́чіє і всесовершенства Твоя́, о Ма́ти і Ді́во, я́ко Всемилостивого Бо́га і Спа́са родила́ нам єси́, ми же на землі́, подража́юще їм, грі́шними устна́ми дерза́єм славослав'яще взива́ти к Тебі́ такова́я:","Ра́дуйся, небе́сних непреста́нноє удивле́ніє;","Ра́дуйся, земни́х всера́достноє поклоне́ніє;","Ра́дуйся, зло́би і тьми духо́вния прогоне́ніє;","Ра́дуйся, притека́ющих к Тебі́ ми́ра і любві́ ісполне́ніє;","Ра́дуйся, я́ко о поми́лованії нас, грі́шних, си́на Твоєго́ умоля́єши;","Ра́дуйся, я́ко от іко́ни Твоєя́ ми́лости нам істоча́єши;","Ра́дуйся, Небе́сная на́ша Ма́ти, Твої́ми словеси́ \"Аз єсьм с ва́ми і нікто́же на ви\" благода́тную си́лу душа́м на́шим да́рующая."]},{"h":"Кондак 2","ps":["Ви́дящи очи́ма духо́вними гряду́щия времена́ страшного богоборчества, святи́й пра́ведний Іоа́нн, нарекомий Кронштадтським, благослови́ написа́ніє іко́ни святи́я Твоєя́, Богома́ти. Да бу́деть в по́мощ і заступле́ніє всім в ско́рбі су́щим, припадающим і в наде́жді на спасе́ніє зовущим Си́ну Твоєму́ і Бо́гу на́шему: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зуму челові́чеському іко́на сія́ в просвіще́ніє, я́коже не си́лой своє́ю прогоняєм враго́в, но могу́ществом Бо́жиїм і предста́тельством Богома́тері, точа́щей от іко́н Свої́х чудеси́, да воспоє́м Всемо́щную Засту́пницю на́шу:","Ра́дуйся, па́дающих і ізнемога́ющих ско́роє подкріпле́ніє;","Ра́дуйся, от бісо́в і злих челові́к наде́жноє заступле́ніє;","Ра́дуйся, в час іскуше́ній і недоумі́ній вразумле́ніє;","Ра́дуйся, заблудшим правого путі́ нахожде́ніє;","Ра́дуйся, є́ресі і раско́лов іскорене́ніє;","Ра́дуйся, тьми богоборчества ско́роє прогоне́ніє;","Ра́дуйся, Небе́сная на́ша Ма́ти, Твої́ми словеси́ \"Аз єсьм с ва́ми і нікто́же на ви\" благода́тную си́лу душа́м на́шим да́рующая."]},{"h":"Кондак 3","ps":["Си́ла гоне́нія нечести́вих возста́ на христия́ни і святи́ням їх поруга́шася; прия́вший же святу́ю іко́ну Твою́, Богома́ти, оте́ць Серафи́м, нариця́ємий Вирицький, уберег єя́. Да прибі́гши под кров Цари́ці Небе́сній, монашествующий і всі ві́рнії по́мощію Бо́жиєю укрепляємії со тре́петом і любо́вію воспою́ть Спаси́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи ве́лія чудеса́, їм же ність числа́, явля́ла Пресвята́я Ді́ва чрез святу́ю іко́ну Свою́ по́мощ всім с ві́рою і любо́вію притекающим і зовущим к Ней такова́я:","Ра́дуйся, Цари́це Не́ба і землі́;","Ра́дуйся, Ма́ти Го́спода Ви́шняго;","Ра́дуйся, оби́ліє чуде́с істоча́ющая;","Ра́дуйся, нече́стіє богоборчества облича́ющая;","Ра́дуйся, моля́щихся с ві́рою ско́роє сли́шаніє;","Ра́дуйся, м'ятущихся душ на́ших оти́шіє;","Ра́дуйся, Небе́сная на́ша Ма́ти, Твої́ми словеси́ \"Аз єсьм с ва́ми і нікто́же на ви\" благода́тную си́лу душа́м на́шим да́рующая."]},{"h":"Кондак 4","ps":["Бу́ря богоборчеського нече́стія пронеслась, оскверни́вши святи́ні, і попусти́ Госпо́дь на лю́ди на́ша враже наше́ствіє, да скорб'ями очи́стяться і слеза́ми оми́ються і да, вразумившись, пока́ються і, покаявшись, возопію́ть Спаса́ющему Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша ско́рби людські́я, оте́ць Серафи́м і́же в кельі своє́й по́двиг Саровського ста́рця под'явши, денно і но́щно усе́рдно пред іко́ною Богоро́диці вопія́л такова́я:","Ра́дуйся, я́ко грі́шников к покая́нію предуготовляєши;","Ра́дуйся, ка́ющихся грі́шников неотвергающая;","Ра́дуйся, я́ко Си́на Твоєго́ і Бо́га на́шего умилостивля́єши;","Ра́дуйся, скорб на́шу в ра́дость претворя́ющая;","Ра́дуйся, от враг ви́димих і неви́димих ізбавля́ющая;","Ра́дуйся, я́ко от на́глия сме́рти спаса́єши;","Ра́дуйся, Небе́сная на́ша Ма́ти, Твої́ми словеси́ \"Аз єсьм с ва́ми і нікто́же на ви\" благода́тную си́лу душа́м на́шим да́рующая."]},{"h":"Кондак 5","ps":["Боготе́чную благода́ть ви́дя, істека́ющую от святи́я іко́ни Богома́тері, лю́діє стека́хуся в селе́ніє Вирицю і прийма́ху душ і тіле́с ісціле́ніє, в ра́дості вопіяша Си́ну Пресвяті́й, Пречи́стій, Преблагослове́нній: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діша приявшую от Си́на Твоєго́ і Бо́га на́шего ве́лію благода́тную си́лу ісціле́нія і вспоможе́нія, блага́я Ма́ти, ще́дро ниспосилавши єя́ всім, приходящим к Тебі́ і взивающим Ті такова́я:","Ра́дуйся, умершего отроча́ти воскреше́ніє;","Ра́дуйся, неісці́льних болі́зней врачева́ніє;","Ра́дуйся, тіле́с на́ших здра́віє;","Ра́дуйся, душ на́ших спасе́ніє;","Ра́дуйся, от уз гріхо́вних свобожде́ніє;","Ра́дуйся, ко Го́рнему ми́ру восхожде́ніє;","Ра́дуйся, Небе́сная на́ша Ма́ти, Твої́ми словеси́ \"Аз єсьм с ва́ми і нікто́же на ви\" благода́тную си́лу душа́м на́шим да́рующая."]},{"h":"Кондак 6","ps":["Пропові́дуя ско́роє отше́ствіє своє́ от юдо́лі сей многоскорбной і многом'ятежной, ста́рець предре́кл єси́ но́воє местонахожденіє святи́я іко́ни Богоро́диці, гді в любві́ к Всемилостивому́ Бо́гу в Тро́йці сла́вимому возопію́ть: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсіява́я ра́дость в ско́рбі су́щей ігуме́нії, разрушенную дре́внюю оби́тель свята́го Гео́ргия приявшую і си́лами свої́ми возобновити не могу́щую, дарова́ла єй ве́лію ми́лость: яви́ла єси́ пречу́дно святу́ю іко́ну Свою́, да с тре́петом і любо́вію воспою́ть к Ней такова́я:","Ра́дуйся, нікогда́ же нас по́мощі материнськой лишающая;","Ра́дуйся, лю́б'ящих Тя Боже́ственною любо́вію покрива́ющая;","Ра́дуйся, нестроє́нія жите́йского мо́ря ско́ро разріша́ющая;","Ра́дуйся, Аз єсьм с ва́ми — приходящим к Тебі́ возвіща́ющая;","Ра́дуйся, і нікто́же на ви — ободря́ющая;","Ра́дуйся, су́щих в печа́лі і ско́рби не оставля́ющая;","Ра́дуйся, Небе́сная на́ша Ма́ти, Твої́ми словеси́ \"Аз єсьм с ва́ми і нікто́же на ви\" благода́тную си́лу душа́м на́шим да́рующая."]},{"h":"Кондак 7","ps":["Хотя́щи спасе́нія, узрі́ли лю́діє іко́ну, а́ки Саму́ Цари́цю Небе́сную, прише́дшую со святи́ми Апо́столи Іоа́нном і Іа́ковом в оби́тель свята́го Гео́ргия на пра́здник Похвали́ Пресвято́й Богоро́диці, і возопили во умиле́нії ко Го́споду: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую яви́ла єси́ ми́лость, Богоро́дице Ді́во, чудотво́рною іко́ною Твоє́ю, чудеси́ чрез нея́ істоча́я, помога́я всім с ві́рою к ней притекающим і зовущим Ті обра́дованно такова́я:","Ра́дуйся, си́на Твоєго́ і Бо́га о нас умоляющая;","Ра́дуйся, ка́ющихся грі́шников зіло́ лю́б'ящая;","Ра́дуйся, враго́в Бо́жиїх гро́зно наказу́ющая;","Ра́дуйся, сино́в противле́нія нежданно вразумляющая;","Ра́дуйся, по́лчищ бісо́вських от Русі́ Свято́й ізмета́ющая;","Ра́дуйся, боголюби́вих чад Свої́х защища́ющая;","Ра́дуйся, Небе́сная на́ша Ма́ти, Твої́ми словеси́ \"Аз єсьм с ва́ми і нікто́же на ви\" благода́тную си́лу душа́м на́шим да́рующая."]},{"h":"Кондак 8","ps":["Стра́нно чу́до попече́нія Свя́то-Георгієвськой оби́телі ви́дівши, живу́щия в ней і труждающієся, і на моли́тву в ню приходящия прия́ла єси́, в по́двизіх мона́шеських укріпля́я, от бід і скорбе́й избавля́я і науча́я всіх спаса́ющему тобо́ю Христу́ Бо́гу пі́ти: Аллилу́я."]},{"h":"Ікос 8","ps":["Всім вразумле́ніє яви́ла єси́ гро́зним наказа́нієм послу́шници та́йно біжа́ти із оби́телі хотя́щей і покаявшейся ми́лость яви́ла єси́, да нави́кнуть в час ско́рбних обстоя́ній прибіга́ти к іко́ні Твоє́й святі́й, уми́льно взива́я Тебі́ такова́я:","Ра́дуйся, соверше́ніє безрассудних поступков присекающая;","Ра́дуйся, хотя́щим жа́ти спасе́ніє помога́ющая;","Ра́дуйся, в по́двизіх мона́шеських укріпля́ющая;","Ра́дуйся, па́дающих ско́роє возведе́ніє;","Ра́дуйся, Хода́тайце на́шего спасе́нія,","Ра́дуйся, защи́та на́ша і в доброді́телях вспоможе́ніє;","Ра́дуйся, Небе́сная на́ша Ма́ти, Твої́ми словеси́ \"Аз єсьм с ва́ми і нікто́же на ви\" благода́тную си́лу душа́м на́шим да́рующая."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ восхваля́єть Тя, Го́споди. О Тебі́, Созда́телі, Іскупителе, Царі́ і гряду́щем Судії́ своє́м ра́дующеся, я́ко дарова́л єси́ Ма́тер Свою́ в наде́жноє прибі́жище і заступле́ніє всім вопію́щим Тебі́, і́стинному Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я велері́чивия можа́ху лиш удиви́тися, єгда́ сли́шать глас Бо́жий і Богоро́диці: \"Аз єсьм с ва́ми і нікто́же на ви.\" Ми же положшася на во́лю святу́ю і соверше́нную Бо́жию, да почти́м Тя, Пречи́стая, зва́нії сицеви́ми:","Ра́дуйся, Благого Царя́ Блага́я Ма́ти;","Ра́дуйся, я́ко тщи́шися ове́ць Христо́вих собра́ти;","Ра́дуйся, си́рих і стра́нних защи́тнице;","Ра́дуйся, всіх оби́димих покрови́тельнице;","Ра́дуйся, медото́чная моля́щихся сла́досте;","Ра́дуйся, даро́в і благ ві́чних пода́тельнице;","Ра́дуйся, Небе́сная на́ша Ма́ти, Твої́ми словеси́ \"Аз єсьм с ва́ми і нікто́же на ви\" благода́тную си́лу душа́м на́шим да́рующая."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ мир, неізрече́нноє чу́до обрі́тенія святи́я іко́ни Твоєя́, Влади́чице, возвісти́ла всім городам і весям, да в торжестві́ і сла́ві ви́дящи к ним гряду́щую Тя, в ра́дості возопію́ть Трієди́ному Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ і чистото́ неопи́санная, милосе́рдіє неізрече́нноє і побі́до всепобеждающая, богоізбра́нная Отрокови́це, при́зри на ни, смире́нно ви́ну моля́щихся пред іко́ною Твоє́ю і воспіва́ющих Ті, Благода́тная, си́це:","Ра́дуйся, ми́лости неіссякаємий істо́чниче;","Ра́дуйся, духо́вную жа́жду всім утоля́ющая;","Ра́дуйся, милосе́рдая о нас, грі́шних, предста́тельнице;","Ра́дуйся, непреста́нно за нас Христу́ Бо́гу моля́щаяся;","Ра́дуйся, спасе́нія на́шего наде́жда і прибі́жище;","Ра́дуйся, ми́лостивая о нас пред Бо́гом Хода́тайця;","Ра́дуйся, Небе́сная на́ша Ма́ти, Твої́ми словеси́ \"Аз єсьм с ва́ми і нікто́же на ви\" благода́тную си́лу душа́м на́шим да́рующая."]},{"h":"Кондак 11","ps":["Пі́ніє благода́рственноє прино́сим Ті, раби́ Твої́, Богоро́дице Ді́во, грі́шнії і непотре́бнії, оба́че Ти достославно заступа́єши всіх, обрящихся к Тебі́ і вопію́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Светоподательную свіщу́ іму́ще Тя, Пресвята́я Ма́ти і Ді́во, я́ко просвіща́єши нас сві́том си́на Твоєго́ і дарова́ла єси́ нам іко́ну Свою́ повелительную, да не преткне́мся в но́чі послі́дніх време́н, но, храни́ми тобо́ю, порабо́таєм Го́споду во сві́ті Єго́, упова́юще на Тя такова́я:","Ра́дуйся, язв гріхо́вних ціли́тельнице;","Ра́дуйся, в Ца́рствіє Бо́жиє Путеводи́тельнице;","Ра́дуйся, на ру́ціх Свої́х нося́щая Носящего вся;","Ра́дуйся, злати́я врата́ Небе́снаго Ца́рствія;","Ра́дуйся, сві́том Си́на Твоєго́ нас просвіща́ющая;","Ра́дуйся, зрі́нієм іко́ни Твоє́й нас услажда́ющая;","Ра́дуйся, Небе́сная на́ша Ма́ти, Твої́ми словеси́ \"Аз єсьм с ва́ми і нікто́же на ви\" благода́тную си́лу душа́м на́шим да́рующая."]},{"h":"Кондак 12","ps":["Благода́ть да́ти восхоті́в лю́дем Свої́м, дарова́ла єси́, Влади́чице, нам іко́ну Свою́ і с не́ю обітова́ніє: \"Аз єсьм с ва́ми і нікто́же на ви,\" єго́же не возмо́жеть нікогда́же і нікто́же із враг на́ших ви́димих і неви́димих преступи́ти; да імі́я промишле́ніє таково́є боже́ственноє о нас, вопіє́м Всемилостивому́ Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще о чудесі́х Твої́х, Всемо́щная Влади́чице, зна́єм Тя, те́плую і любвеоби́льную Засту́пницю, к Ней же все притекающиє да не постижені бу́дуть, но всегда́ тобо́ю храни́ми, вопію́ть Ті сицева́я:","Ра́дуйся, в ско́рбіх су́щих Отра́до;","Ра́дуйся, упова́ющих на Го́спода Бо́га Огра́до;","Ра́дуйся, Єя́ же враги́ на́ша трепе́щуть;","Ра́дуйся, я́ко іму́щиє іко́ну Твою́ ликовству́ють;","Ра́дуйся, сла́в'ящих Тя — прославля́ющая;","Ра́дуйся, зе́млю Ру́ськую і всіх, я́же в ми́рі Христо́вом, зіло́ заступа́ющая;","Ра́дуйся, Небе́сная на́ша Ма́ти, Твої́ми словеси́ \"Аз єсьм с ва́ми і нікто́же на ви\" благода́тную си́лу душа́м на́шим да́рующая."]},{"h":"Кондак 13","ps":["Пресвята́я, Пречи́стая, Преблагослове́нная Богоро́дице Ді́во Марі́є, Всеми́лостивая Ма́ти Бо́га і челові́ков, воззри́ на скорбниі душі́ на́ша і умилосе́рдися, Пречи́стая, вознеси́ Твою́ многомощную моли́тву к пра́ведному Судії́ о поми́лованії нас, грі́шних. При́зри на ни, Всепі́тая Богоро́дице, возсія́й просвіще́ніє сердця́м омраче́нним, і озари́ ста́до Твоє́, Пречи́стая, да спаса́ємі тобо́ю, ра́достно воспоє́м Бо́гу: Аллилу́я, аллилу́я, аллилу́я.","​","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели на небесі́ воспіва́ють вели́чіє і всесовершенства Твоя́, о Ма́ти і Ді́во, я́ко Всемилостивого Бо́га і Спа́са родила́ нам єси́, ми же на землі́, подража́юще їм, грі́шними устна́ми дерза́єм славослав'яще взива́ти к Тебі́ такова́я:","Ра́дуйся, небе́сних непреста́нноє удивле́ніє;","Ра́дуйся, земни́х всера́достноє поклоне́ніє;","Ра́дуйся, зло́би і тьми духо́вния прогоне́ніє;","Ра́дуйся, притека́ющих к Тебі́ ми́ра і любві́ ісполне́ніє;","Ра́дуйся, я́ко о поми́лованії нас, грі́шних, си́на Твоєго́ умоля́єши;","Ра́дуйся, я́ко от іко́ни Твоєя́ ми́лости нам істоча́єши;","Ра́дуйся, Небе́сная на́ша Ма́ти, Твої́ми словеси́ \"Аз єсьм с ва́ми і нікто́же на ви\" благода́тную си́лу душа́м на́шим да́рующая."]},{"h":"Кондак 1","ps":["Ізбра́нной от всіх родо́во Влади́чице ми́ра, Ді́ві Богоро́диці, принесе́м похвальниє да́ри, я́коже і ни́ні, а́ки і пре́жде па́дших возставля́єши, немощни́х укріпля́єши, боля́щих ісціля́єши, от враг ви́димих і неви́димих ізбавля́єши, сомня́щихся вразумля́єши, унива́ющих ободряєши, ві́ровати в Благода́тную си́лу святи́х іко́н Твої́х науча́єши і в благодарности умиле́нним се́рдцем і усти́ пі́ти Тебі́ сподобляєши:","Ра́дуйся, Небе́сная на́ша Ма́ти, Твої́ми словеси́ \"Аз єсьм с ва́ми і нікто́же на ви\" благода́тную си́лу душа́м на́шим да́рующая."]},{"h":"Молитва","ps":["О, Всеблага́я Засту́пнице ро́да христия́нськаго, Ма́ти Держа́щаго вся десни́цею Своє́ю Христа́ Бо́га на́шего! Ізле́й на ни ми́лості і щедро́ти Єго́. І да не убої́мся і не устраші́мся враг ви́димих і неви́димих, я́ко рекла́ єси́ уповающим на Тя «Аз єсьм с ва́ми, і нікто́же на ви».","Сохрани́ і́стинную Святу́ю правосла́вную Це́рков і оби́тель на́шу от раско́лов і єресе́й. І положи́ нача́ло покая́нія наро́да на́шего. Возврати́ Святу́ю Русь на дарова́нний єй Бо́гом путь неповрежденной ві́ри, да напо́лниться фимія́мом моли́тв і расцвететь, а́ки крин се́льний. Да поживе́м во благоче́стії і чистоті́, всегда́ храни́мі Тобо́ю от іскуше́нія антихристова, наше́ствія іноплеме́нних, междоусо́бния бра́ні, тру́са, огня́, гла́да і мо́ра; от напра́сния сме́рті, пліне́нія і раздо́ров семе́йних; мона́шеськоє житіє́ укріпи́ і спаси́ ни, Пречи́стая, я́ко упова́єм на Тя по рече́нному Тобо́ю: «Аз єсьм с ва́ми, і нікто́же на ви».","Моли́ся о нас, Пресвята́я Влади́чице Богоро́дице, ко Го́споду Бо́гу на́шему, ми́лующему і спаса́ющему, да не лиши́ть ни защити і Ца́рствія Своєго́ присвоє́нія, і́же і Сам рече́ ві́рним Свої́м: «Аз єсьм с ва́ми, і нікто́же на ви». Єму́ же сла́ва, держа́ва, честь і поклоне́ніє, си́ла і вели́чіє подоба́єть Отцю́ і Си́ну, і Свято́му Ду́ху, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 6","ps":["Влади́чице чи́стая, при́зри, Богоро́дице, / виждь на́ших язв болі́зні, / і умилосе́рдися, Пречи́стая, / і ісціли́ со́вістноє жже́ніє, / Твоє́ю ми́лостію ороша́ющи, / і вопію́щи рабо́м Твої́м: / Аз єсьм с ва́ми, // і нікто́же на ви."]},{"h":"Кондак, глас 6","ps":["При́зри на ни, Всепі́тая Богоро́дице, / возсія́й просвіще́ніє сердця́м омраче́нним, / і озари́ ста́до Твоє́, Пречи́стая: / єли́ко бо хо́щеши і мо́жеши, / я́ко Ма́ти су́щи Зижди́теля Твоєго́, / і возопи́й молящим Тя: / аз єсьм с ва́ми, // і нікто́же на ви."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, і чтим о́браз Твой святи́й, от него́ же істека́єть благода́тная по́мощ всім, с ві́рою притекающим к нему́."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Непорушна Стіна»","e":"Akathist to the Theotokos before her icon “The Unbreakable Wall”","secs":[{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Бо́жієй Ма́тері і Цари́ці, пред пречи́стим Єя́ о́бразом, Неруши́мая Стіно́ іменуємим, благода́рственноє хваленноє пі́ніє прино́сим Тебі́, Благода́тная. Ти же, я́ко іму́щая си́лу непостижи́мую і любо́в несказа́нную, от всіх нас бід і скорбе́й сохрани́, да зове́м Ті:","Ра́дуйся, Богоро́дице, Стіно́ Неруши́мая, Засту́пнице на́ша і утіше́ніє."]},{"h":"Ікос 1","ps":["А́нгел предста́тель по́слан бист от Бо́га к Тебі́, Пречи́стая, благовісти́ти Тебі́ ра́дость всеми́рную, я́ко зачне́ши от Ду́ха Свя́та во утро́бі Твоє́й Бо́га Сло́ва, Спаси́теля ми́ра. Ми же, ві́дуще ісполне́ніє сего́ благові́щенія, ві́руєм, я́ко Госпо́дь Тебі́, Преблагослове́нная, яви́ Стіно́ю Неруши́мою і огражде́ніє нас от всякого гріха́, бід і напа́стей. Сего́ ра́ди ублажа́єм Тя, Богоро́дице, і ра́достно вопіє́м:","Ра́дуйся, я́ко Госпо́дь с Тобо́ю і Тобо́ю с на́ми;","ра́дуйся, я́ко в Ка́ні Галиле́йстій Предста́тельницею к Си́ну Твоєму́ о лю́діх яви́лася єси́.","Ра́дуйся, я́ко омофо́ром Твої́м ширше о́блака покрива́єши ві́рних;","ра́дуйся, я́ко ле́нтієм Твої́м сле́зи стра́ждущих отира́єши.","Ра́дуйся, я́ко воздіва́єши ру́ці Твої́ во огражде́ніє нас от вся́кия скве́рни;","ра́дуйся, я́ко по глаго́лу Твоєму́ ни́ні і при́сно ублажа́єшися.","Ра́дуйся, Богоро́дице, Стіно́ Неруши́мая, Засту́пнице на́ша і утіше́ніє."]},{"h":"Кондак 2","ps":["Прови́дяще проро́ци у́мними очеси́ свої́ми благода́тноє явле́ніє Твоє́, Рождество́ во пло́ті от Тебе́ Си́на Бо́жия провозвісти́ша, да всі сбитіє́ проро́чеських віща́ній позна́вше, благогові́йно взива́ють к Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум благопросвещен імі́юще, Іа́ков, Мойсе́й, Дави́д і други́х мно́жество в словесі́х, виді́ніях, со́ніїх чу́дноє Рождество́ Твоє́ і та́йну Присноді́вства Твоєго́ ізобрази́ша. Ми же, всю си́лу проро́чеських віща́ній разумі́ти не могу́ще, із глубини́ ві́рующих серде́ць на́ших с любо́вію воспіва́єм Тебі́:","Ра́дуйся, Лі́ствице висо́кая, зе́млю с Не́бом совоку́пльшая;","ра́дуйся, Бо́га, на землі́ я́вльшагося, во чре́ві Твоє́м поне́сшая і я́ко Неопали́мая Купина́ нетлі́нною пребива́ющая.","Ра́дуйся, світоно́сний О́блаче, із Него́ же всіх Влади́ка, я́ко дождь на руно́, на зе́млю сни́де;","ра́дуйся, я́ко Живоно́сний Істо́чник, а́лчбу і жа́жду ві́чния пра́вди в лю́діх возгревающая.","Ра́дуйся, Христа́, ма́нну жи́зні, во чре́во Своє́ вмісти́вшая і душі́ на́ша хлі́бом безсме́ртія насища́ющая;","ра́дуйся, чу́дний Же́зле, цвіта́ми доброді́телей ві́рних украша́ющая.","Ра́дуйся, Богоро́дице, Стіно́ Неруши́мая, Засту́пнице на́ша і утіше́ніє."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіни́ Тя, Пречи́стая, соді́лавши Тя Матерю Го́спода, і по Рождестві́ Твоє́м оби́льно пребива́єть в Тебі́, Богома́ти. Ра́дующеся таково́му Бо́жию благоізволе́нію, к Тебі́ би́вшему, всі, восхваля́юще Спаси́теля ми́ра, вопіє́м Єму́ ра́достно: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи в Себі́ оби́льно благода́ть Бо́жию, Ти, Пренепоро́чная, все житіє́ Твоє́ отдала́ єси́ благи́м попече́ніям о Си́ні Твоє́м і Го́споді, вся глаго́ли Єго́ соблюда́ющи в се́рдці Своє́м. Ми же, грі́шнії, ско́рбноє житіє́ Твоє́ на землі́ воспомина́юще, глаго́лем Тебі́ похвали́ такови́я:","Ра́дуйся, Влади́ку вселе́нния во убо́зім верте́пе роди́вшая;","ра́дуйся, во Єги́пет от беззако́ннаго І́рода с Сино́м Твої́м бежавшая.","Ра́дуйся, О́трока Си́на Своєго́ с вели́кою ско́рбію во Ієрусали́мі во дні Па́схи іска́вшая;","ра́дуйся, не́нависть і за́висть к Си́ну Твоєму́ от враго́в Єго́ ско́рбним се́рдцем созерцавшая.","Ра́дуйся, Матери́нським се́рдцем сраспинавшаяся Єму́, єгда́ Кре́стная страда́нія і смерть Єго́ на кресті́ созерцала єси́;","ра́дуйся, во Іоа́нні Богосло́ве си́на Себі́ по глаго́лу Ісу́са обрі́тшая.","Ра́дуйся, Богоро́дице, Стіно́ Неруши́мая, Засту́пнице на́ша і утіше́ніє."]},{"h":"Кондак 4","ps":["Бу́рею наше́ствія іноплеме́нников многократно іспиту́єма страна́ на́ша Россі́йськая, і в тяжелих іспитаніях отці́ на́ші взива́ху о по́мощі ко Пресвято́й Ді́ві Богоро́диці. Та бо, я́ко Неруши́мая Стіно́, Свої́м предста́тельством у Престо́ла Си́на Своєго́ і Бо́га, благода́тно ниспосила́єть си́лу Свою́, і с наде́ждею на по́мощ Богома́тере лю́ди ру́сстії ізгоня́ють по́лчища вра́жеськия от преді́лов россі́йських. Сего́ ра́ди восхваля́юще Богома́тер, ра́достно воспіва́єм Го́споду: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шить і зна́єть весь мир, я́ко Пресвята́я Богоро́диця возжига́єть в сердця́х ру́ських люде́й му́жество, і си́лу на по́двиги і защи́ту оте́чества, бори́маго от іноплеме́нников, подає́ть, і по́мощ Свою́ благода́тную посила́єть всему́ во́їнству ру́ському. Іспові́дующе такову́ю ві́ру на́шу і чуде́сноє заступле́ніє Цари́ці Небе́сния во дні бра́нних наше́ствій на зе́млю на́шу, та́ко воспіва́єм Благода́тній:","Ра́дуйся, наро́ду ру́ському на враго́в поможе́ніє;","ра́дуйся, землі́ на́шей на ізгна́ніє іноплеме́нников благода́тноє подкріпле́ніє.","Ра́дуйся, вожде́й во́їнства ру́ськаго та́йноє вразумле́ніє і умудреніє;","ра́дуйся, ненавистников ро́да челові́чеськаго посрамле́ніє.","Ра́дуйся, пла́мень вражди́ разжигающих гро́зная Наказательнице;","ра́дуйся, всіх пеку́щихся о ми́рі всего́ ми́ра необори́мая Помо́щнице.","Ра́дуйся, Богоро́дице, Стіно́ Неруши́мая, Засту́пнице на́ша і утіше́ніє."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́лася єси́, Присноблаже́нная, всім блуждающим во тьмі страсте́й і поро́ков, Твої́м бо вразумленієм мно́жество і тя́жких грі́шников от беззако́нних діл отвраща́ються і к Бо́гу с покая́нієм прибіга́ють, вопію́ще Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дящи Премилосе́рдая Влади́чиця ги́бель душ мно́гих, во власть гріха́ і скве́рни сатано́ю ісхищенних, по неізрече́нной любві́ к ро́ду челові́чеському предваря́єть їх на по́мощ, от путі́ ги́бельнаго отвраща́єть і на путь спасе́нія наставля́єть. Ра́дующеся ди́вному милосе́рдію Цари́ці Небе́сния, всі ві́рнії та́ко глаго́лють:","Ра́дуйся, путь спасе́нія всім нам показу́ющая;","ра́дуйся, го́рдості і гні́ву сердця́ми на́шими владі́ти возбраня́ющая.","Ра́дуйся, чревоугодником і піяницям строгоє вразумле́ніє;","ра́дуйся, ліни́вим і безвольним крі́пкоє побужде́ніє.","Ра́дуйся, живу́щих блу́дно к покая́нію приводя́щая;","ра́дуйся, грі́шников, к Тебі́ с ві́рою прибіга́ющих, ско́роє ісправле́ніє.","Ра́дуйся, Богоро́дице, Стіно́ Неруши́мая, Засту́пнице на́ша і утіше́ніє."]},{"h":"Кондак 6","ps":["Пропові́дници би́ша чуде́с, от Твої́х іко́н явле́нних, благочести́вії отці́ на́ші, Тобо́ю, Богоро́дице, спасе́нния і от бід і напа́стей ізба́вленния. Ті́мже благодаря́ще Бо́га, такову́ю благу́ю Засту́пницю ро́ду челові́чеському дарова́вшаго, всі немо́лчними усти́ воспіва́ють Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ світ неізреченньй Твоєя́ бла́гости, Благослове́нная, всім скорб'я́щим, пла́чущим, всім нам, во іскуше́нії су́щим, і́бо чрез на́ша сле́зния моли́тви да́рується нам Тобо́ю, Богоро́дице, чуде́сноє от бід ізбавле́ніє. Оба́че не імі́юще слове́с досто́йних восхваля́ти Тя за ми́лості Твоя́ ко всім, грі́шними усти́ восклиця́єм Ті во умиле́нії та́ко:","Ра́дуйся, ско́рби і сле́зи на́ша в ра́дость претворя́ющая;","ра́дуйся, ізнемога́ющим во іскуше́ніях Милосе́рдная Помо́щнице.","Ра́дуйся, до́ми на́ша от огня́ і іни́х разрушеній спаса́ющая;","ра́дуйся, от тате́й і злих люде́й ві́рния огражда́ющая.","Ра́дуйся, клевети́ і ко́зні враго́в на́ших разруша́ющая;","ра́дуйся, страх сме́рти і внеза́пния кончи́ни в душа́х на́ших побіжда́ющая.","Ра́дуйся, Богоро́дице, Стіно́ Неруши́мая, Засту́пнице на́ша і утіше́ніє."]},{"h":"Кондак 7","ps":["Хотя́ Всеми́лостивий Госпо́дь яви́ти Свою́ Боже́ственную любо́в к нам недосто́йним, дарова́ нам Твою́, Богома́ти іко́ну, Стіно́ Неруши́мая імену́ємую, да ви́дящії чудеса́, от святи́я іко́ни би́вшая, всі лю́діє с ві́рою і наде́ждою на чудодейственную Твою́ по́мощ со умиле́нієм взива́ють Істо́чнику чуде́с Го́споду: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє свиді́тельство прису́щия всегда́ Тебі́, Пречи́стая, благода́ті і чуде́сния си́ли показа́ нам Созда́тель, єгда́ ди́вний о́браз Твой, на алтарней стіні́ дре́вняго Софійськаго собо́ра во гра́ді Ки́єве ізображе́нний, де́в'ять столетій неврежде́н сохрани́, по́лчища бо пога́них враго́во ві́ри правосла́вния не дерзну́вше повреди́ти о́браз сей благода́тний, си́лою Твоє́ю охраняємий. Воі́стину і нам, грі́шним і ско́рбним, Стіно́ю Неруши́мою явля́ється свята́я іко́на сія́, всім ві́рним внушающая возглаша́ти Тебі́:","Ра́дуйся, облече́нная в хито́н, сія́ющий сві́том небе́сним;","ра́дуйся, воздія́нієм рук Твої́х пречи́стих непреста́нную моли́тву о всем ми́рі явля́ющая.","Ра́дуйся, я́ко честна́го о́браза Твоєго́ і долгота́ віко́в не повреди́;","ра́дуйся, я́ко о́браз сей і по наше́ствії си́ли вра́жия во всей своє́й лі́поті пребива́єть.","Ра́дуйся, я́ко о́бразом сим се́рдце моля́щихся благогові́йно умиляється;","ра́дуйся, я́ко благода́тная си́ла, сему́ о́бразу Твоєму́ присущая, бі́си устраша́єть.","Ра́дуйся, Богоро́дице, Стіно́ Неруши́мая, Засту́пнице на́ша і утіше́ніє."]},{"h":"Кондак 8","ps":["Стра́нно єсть неверующим сли́шати, я́ко Ти, Богома́ти, о младе́нціх особоє попече́ніє і́маши. Ми же, воспомина́юще сло́ва Го́спода на́шего, ре́кшаго: оста́віте діте́й приходи́ти ко Мні, такови́х бо єсть Ца́рствіє Бо́жиє, с тве́рдою ві́рою іспові́дуєм, я́ко Ти, Пресвята́я Ді́во, Своє́ю любо́вію охраня́єши младе́нцев і їх ма́терей, і вопіє́м Си́ну Твоєму́: Аллилу́я."]},{"h":"Ікос 8","ps":["Всім се́рдцем Твої́м, Цари́це ми́ра, вся́коє Бо́жиє созда́ніє лю́б'яще і о всіх к Си́ну Твоєму́ моли́тви возно́сиши, я́ко Ма́ти по пло́ті Си́на Бо́жия, Ти неті́сно вміща́єши в душе́ Твоє́й ско́рби і труди́ ма́терей. Сего́ ра́ди, я́ко Ма́тері Богомладе́нця Ісу́са, воспіва́єм Ті:","Ра́дуйся, ві́рная Помо́щнице і прибі́жище ма́терей деторождающих;","ра́дуйся, покро́ве і крі́посте младе́нцев.","Ра́дуйся, матери́нськия ско́рби утоля́ющая;","ра́дуйся, всяк во́зраст младе́нчеський сохраня́ющая.","Ра́дуйся, благочести́вих ма́терей во воспита́нії діте́й блага́я Наста́внице;","ра́дуйся, младе́нцев безпомо́щних в болі́зні Ціли́тельнице.","Ра́дуйся, Богоро́дице, Стіно́ Неруши́мая, Засту́пнице на́ша і утіше́ніє."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє і челові́чеськоє воспіва́єть присноді́вственную чистоту́ Твою́, Пренепоро́чная, сего́ ра́ди почита́єм Тя, я́ко неуси́пную Попечительницю непоро́чности дів, чистоти́ вдови́ць, цілому́дрія ю́ношей; і всяк во́зраст люде́й ввіря́єм Тебі́, да сохрани́ши їх в свя́тости, воспіва́ющих Си́ну Твоєму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́я суєму́дреннії не мо́гуть в се́рдці своє́м вмісти́ти і́стину Твоєго́, Богоро́дице, Присноді́вства. Ми же, ві́рующе в си́лу непостижи́мия та́йни, с благогові́нієм восхваля́єм Тя си́це:","Ра́дуйся, я́ко кра́сния і сві́тлия добро́ти Твоєя́ возжела́ Жени́х, красні́йшій па́че всіх сино́в челові́чеських;","ра́дуйся, я́ко сей Жени́х ді́вство і рождество́ в Тебі́ сочета́.","Ра́дуйся, прему́драя Наста́внице непоро́чнаго ді́вства;","ра́дуйся, вдови́ць благочести́вих в безбра́чії соблюда́ющая.","Ра́дуйся, чи́стих дів і вдови́ць рабо́тати во сла́ву Христа́ на бла́го бли́жніх наставля́ющая;","ра́дуйся, всім могу́щим сія́ вмісти́ти на путі́ цілому́дрія споспешствующая.","Ра́дуйся, Богоро́дице, Стіно́ Неруши́мая, Засту́пнице на́ша і утіше́ніє."]},{"h":"Кондак 10","ps":["Спасти́ хотя́щи лю́ди Своя́ от паде́ній гріхо́вних, Ти, Влади́чице, неуси́пно свя́тость честна́го бра́ка охраня́єши і пребива́ющим в бра́ці указу́єши храни́ти за́повіді Госпо́дні: ді́ти своя́ по Бо́гу воспитивати і к ді́лом милосе́рдія приучати. Благодаря́ще Бо́га, дарова́вшаго нам такову́ю му́друю Наста́вницю, от всего́ се́рдця поє́м Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ і Храни́тельниця христия́нських семе́йств благочести́вих, Пресвята́я Ді́во, ві́рующих му́дро наставля́єши бра́чную жизнь я́ко і́го благо́є прийма́ти і ві́рность друг ко дру́гу до кончи́ни храни́ти. Сего́ ра́ди і ми, ра́дующеся Твоєму́ попече́нію о до́брім христия́нстім супру́жестві, та́ко с умиле́нієм Тебі́ глаго́лем:","Ра́дуйся, честни́й брак благословляющая;","ра́дуйся, по уче́нію Христа́ і апо́столов жи́ти супру́гов наставля́ющая.","Ра́дуйся, живу́щим в супру́жестві любо́в і єдиноми́сліє в се́рдця влага́ющая;","ра́дуйся, семейния у́зи охраня́ющая.","Ра́дуйся, блага́я Попечи́тельнице дома́шнія Це́ркве;","ра́дуйся, гро́зная Обличи́тельнице нарушителей супружеськия ві́рности.","Ра́дуйся, Богоро́дице, Стіно́ Неруши́мая, Засту́пнице на́ша і утіше́ніє."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє прино́сить Ті, Преблагослове́нная, весь род христия́нський, ви́дяще Тя, я́ко всеси́льную Моли́твенницю за весь мир. Ти же, Богоро́дице, і ю́них моли́тви приє́млеши, і моле́ніє немощни́х ста́рцев і ста́риць не презира́єши, ю́них на до́брия діла́ ко спасе́нію наставля́єши, ста́рцем же о ско́ром їх преселе́нії в жизнь загробную напоминаєши. Сего́ ра́ди, моля́ще Го́спода о дарова́нії всім нам па́м'яті сме́ртния, взива́єм Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́лом назидательним і світоза́рним в на́шей гріхо́вной жи́зні, уче́ніє Христа́ Спаси́теля о жи́зні бу́дущаго ві́ка, явля́ється, Ти же, Всеми́лостивая, возгреваєши в сердця́х на́ших благода́тноє жела́ніє от гріхо́в покая́нієм очи́ститися і до́брими діла́ми жизнь свою́ украси́ти. Ра́дующеся Твоєму́ о нас попече́нію, о є́же получи́ти нам ві́чноє спасе́ніє, со слеза́ми умиле́нія взива́єм Ті:","Ра́дуйся, ізря́дную любо́в к ста́рцем немощни́м явля́ющая;","ра́дуйся, ві́рним лю́дем, хотя́щим житіє́ своє́ во благоче́стії сконча́ти, Всеблага́я Помо́щнице.","Ра́дуйся, престарі́лих роди́телей, дітьми́ свої́ми оста́вленних, под кров Свой честни́й приє́млющая;","ра́дуйся, такови́х же́стоких чад, небрегу́щих о ста́рціх свої́х, гро́зная Наказательнице.","Ра́дуйся, о стра́шнім Второ́м Христо́вом прише́ствії всім нам напоминающая;","ра́дуйся, о душа́х преста́вльшихся ві́рних рабо́в Бо́жиїх Моли́твеннице те́плая.","Ра́дуйся, Богоро́дице, Стіно́ Неруши́мая, Засту́пнице на́ша і утіше́ніє."]},{"h":"Кондак 12","ps":["Благода́ть Боже́ственная я́вно пребива́єть в Твоє́й чудотво́рній іко́ні, досто́йно і пра́ведно в утіше́ніє на́ше Стіно́ю Неруши́мою імену́ємою. Ізлива́юще пред се́ю іко́ною своя́ ра́дости і печа́лі, мо́лим Тя, Ма́ти Го́спода на́шего Ісу́са Христа́, не оста́ви нас Свої́м заступле́нієм, да благода́рно о Тебі́ взива́єм Го́споду: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоє́ мо́щноє предста́тельство за весь мир, воспомина́юще чудеса́, явле́нная Тобо́ю чрез святу́ю іко́ну Твою́ Стіно́ Неруши́мая, мо́лим Тя, Засту́пнице усе́рдная: бу́ди страні́ на́шей непреста́нная Помо́щниця, умоли́ Си́на Твоєго́, ісполня́ющаго моле́нія Твоя́, водворити во всем ми́рі жела́нний народами мир, да всі благода́рно восхвалють Тя си́це:","Ра́дуйся, явле́нієм Си́на Своєго́ і Єго́ Воскресе́нієм обра́дованная;","ра́дуйся, в безсме́ртнім Успе́нії Твоє́м ду́шу Твою́ ра́достно в ру́ці Єго́ преда́вшая.","Ра́дуйся, па́стирей до́брих на їх кре́стнім путі́ укріпля́ющая;","ра́дуйся, проводящих і́ночеськую жизнь незри́моє поможе́ніє.","Ра́дуйся, храм сей і моля́щихся в нем благода́тію Своє́ю охраня́ющая;","ра́дуйся, оте́честву на́шему неізмі́нний Покро́ве і Стіно́ Неруши́мая.","Ра́дуйся, Богоро́дице, Стіно́ Неруши́мая, Засту́пнице на́ша і утіше́ніє."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти Го́спода на́шего Ісу́са Христа́, прийми́ ни́ні сіє́ ма́лоє моле́ніє, огради́ нас от гріхо́в і вся́кия скве́рни, ізба́ви от находя́щих на нас бід і нужд, сохрани́ от уни́нія і отча́янія, клевети́ челові́чеськія, болі́зней нестерпи́мих, да моли́твами Твої́ми ста́вше на путь спасе́нія ві́чнаго, благода́рно воспоє́м Си́ну Твоєму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел предста́тель по́слан бист от Бо́га к Тебі́, Пречи́стая, благовісти́ти Тебі́ ра́дость всеми́рную, я́ко зачне́ши от Ду́ха Свя́та во утро́бі Твоє́й Бо́га Сло́ва, Спаси́теля ми́ра. Ми же, ві́дуще ісполне́ніє сего́ благові́щенія, ві́руєм, я́ко Госпо́дь Тебі́, Преблагослове́нная, яви́ Стіно́ю Неруши́мою і огражде́ніє нас от всякого гріха́, бід і напа́стей. Сего́ ра́ди ублажа́єм Тя, Богоро́дице, і ра́достно вопіє́м:","Ра́дуйся, я́ко Госпо́дь с Тобо́ю і Тобо́ю с на́ми;","ра́дуйся, я́ко в Ка́ні Галиле́йстій Предста́тельницею к Си́ну Твоєму́ о лю́діх яви́лася єси́.","Ра́дуйся, я́ко омофо́ром Твої́м ширше о́блака покрива́єши ві́рних;","ра́дуйся, я́ко ле́нтієм Твої́м сле́зи стра́ждущих отира́єши.","Ра́дуйся, я́ко воздіва́єши ру́ці Твої́ во огражде́ніє нас от вся́кия скве́рни;","ра́дуйся, я́ко по глаго́лу Твоєму́ ни́ні і при́сно ублажа́єшися.","Ра́дуйся, Богоро́дице, Стіно́ Неруши́мая, Засту́пнице на́ша і утіше́ніє."]},{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Бо́жієй Ма́тері і Цари́ці, пред пречи́стим Єя́ о́бразом, Неруши́мая Стіно́ іменуємим, благода́рственноє хваленноє пі́ніє прино́сим Тебі́, Благода́тная. Ти же, я́ко іму́щая си́лу непостижи́мую і любо́в несказа́нную, от всіх нас бід і скорбе́й сохрани́, да зове́м Ті:","Ра́дуйся, Богоро́дице, Стіно́ Неруши́мая, Засту́пнице на́ша і утіше́ніє."]},{"h":"Молитва","ps":["О, благода́тная Влади́чице на́ша Богоро́дице, Присноді́во, прийми́ от нас сіє́ благода́рственноє хвале́бноє пі́ніє і вознеси́ ко Творцю́ і Зижди́телю на́шему те́плия моли́тви Твоя́ за нас недосто́йних, да прости́ть Он, Милосе́рдий, нам вся гріхи́ на́ша, по́мисли лука́вия і нечи́стия, діла́ скве́рния. О, Госпожі́ Пресвята́я, умилосе́рдися і низпосли́ дар по коєгожде потре́бі: боля́щия ісціли́, скорб'я́щия уті́ши, заблу́ждшия вразуми́, охрани́ младе́нці, воспита́й і научи́ ю́ния, обо́дри і наста́ви му́жи і жени́, поддержи́ і согрі́й ста́рия, бу́ди нам і зді, і в жи́зні ві́чній Стіно́ Неруши́мая, ізба́ви от вся́ких бід і напа́стей і от ві́чнаго муче́нія, да всегда́ воспіва́юще Твою́ Матери́нськую любо́в, восхваля́єм всім се́рдцем Си́на Твоєго́, со Отце́м Єго́ і Святи́м Ду́хом, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Я́ко неруши́мую сті́ну і всемо́щний покро́в стяжа́хом Тя, раби́ Твої́, Влади́чице Богоро́дице, мрак гріхо́в і скорбе́й отгоня́ющую. Ті́мже вопіє́м Ті: мир ми́рові да́руй і душа́м на́шим світ і спасе́ніє."]},{"h":"Кондак, глас 8","ps":["Взбра́нной Воєво́ді побіди́тельная, я́ко ізба́вльшеся от злих, благода́рственная воспису́єм Ті раби́ Твої́, Богоро́дице; но я́ко іму́щая держа́ву непобіди́мую, от вся́ких нас бід свободи́, да зове́м Ті: ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Розчулення» Серафимо-Дівеєвська","e":"Akathist to the Theotokos before her icon “Tenderness” of Seraphim-Diveyevo","secs":[{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Бо́жієй Ма́тері і Цари́ці, умиле́нно моля́щейся за ни ко Го́споду і о́браз Умиле́нія Своєго́ нам дарова́вшей ми́лостиво, похва́льноє пі́ніє і моле́ніє прино́сим Ті, Богоро́дице. Ти же, я́ко Всеми́лостивая на́ша Засту́пниця і Всеблага́я Помо́щниця, от вся́ких бід нас ізба́ви, да зове́м Ті:","Ра́дуйся, Влади́чице, Ра́досте, Умиле́ніє і Спасе́ніє душ на́ших."]},{"h":"Ікос 1","ps":["А́нгел земни́й і челові́к Небе́сний, преподо́бний ста́рець Серафи́м іко́ну Твою́ святу́ю, Богоро́дице Ді́во, я́ко драгоці́нноє сокро́вище в своє́й ке́ллії стяжа́ і пред не́ю усе́рдния моли́тви Тебі́ принося́, Всепі́тая, во вся дні подви́жничеськаго житія́ своєго́ благоумиле́нно, Ра́достію всіх ра́достей Тя найменова́, си́це Тебі́ взива́я:","Ра́дуйся, обра́довавшая па́дшеє челові́чество всесвяти́м Твої́м Рождество́м;","ра́дуйся, Спаси́теля ми́ру нетлі́нно ро́ждшая і ді́вство сохра́ньшая преди́вно.","Ра́дуйся, Ма́ти і Ді́во преблагослове́нная;","ра́дуйся, Богоро́дице препросла́вленная.","Ра́дуйся, пала́то Бо́га Сло́ва прекра́сная;","ра́дуйся, світоно́сная ло́жнице Царя́ царе́й.","Ра́дуйся, проро́чеських глаго́лов сбитіє́ прине́сшая;","ра́дуйся, апо́стольськія про́повіді крі́пкоє вспоможе́ніє.","Ра́дуйся, преподо́бних похвало́ і дів велича́ніє;","ра́дуйся, челові́чеськаго ро́да возвише́ніє.","Ра́дуйся, скорб'я́щих утіше́ніє;","ра́дуйся, боля́щих ісціле́ніє.","Ра́дуйся, Влади́чице, Ра́досте, Умиле́ніє і Спасе́ніє душ на́ших."]},{"h":"Кондак 2","ps":["Ви́дів себі́ болі́знію зі́льною одержи́ма, блаже́нний Серафи́м усе́рдно моля́ше Тя, Богоро́дице Ді́во, о по́мощі і ісціле́нії, і се, а́біє предста́ла єси́ єму́ во сві́ті Небе́снім со апо́столома Петро́м і Іоа́нном Богосло́вом і, ре́кши: «Сей от ро́да На́шего єсть», ісціле́ніє ско́ро єму́ дарова́ла єси́, да поє́ть немо́лчно Си́ну Твоєму́ і Бо́гу хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́в своє́ ісціле́ніє, Твої́м посіще́нієм благода́тним соверши́вшеєся, блаже́нний Серафи́м прославля́ше, Богоро́дице, ве́лію к нему́ Твою́ ми́лость, іко́ну же святу́ю благогові́йно почита́ше і сію́ благода́ті прича́стну іменова́ше, є́йже і ми ни́ні покланя́ющеся, си́це Тебі́ зове́м:","Ра́дуйся, обра́довавшая ізбра́нника Бо́жия Твої́м посіще́нієм;","ра́дуйся, в неду́зі ісціле́ніє єму́ пода́вшая скоропредста́тельно.","Ра́дуйся, при́сним Своєму́ ро́ду ми́лостиво єго́ наре́кшая;","ра́дуйся, открове́нії Боже́ственними єго́ просвіти́вшая.","Ра́дуйся, в тече́нії жи́зні єго́ многокра́тно єму́ явля́вшаяся;","ра́дуйся, на по́двиги поста́ і моли́тви неви́димо єго́ укрепля́вшая.","Ра́дуйся, в пустинножи́тії і затво́рі сла́дкая єго́ Собесі́днице;","ра́дуйся, от враг ви́димих і неви́димих держа́вная єго́ Засту́пнице.","Ра́дуйся, і нам грі́шним явля́ющая от іко́ни Твоєя́ мно́гія ми́лості і щедро́ти;","ра́дуйся, і нас недосто́йних не лиша́ющая Твої́х благодія́ній благода́тних.","Ра́дуйся, неду́ги на́ша врачу́ющая безме́здно;","ра́дуйся, печа́лі на́ша утоля́ющая радостотво́рно.","Ра́дуйся, Влади́чице, Ра́досте, Умиле́ніє і Спасе́ніє душ на́ших."]},{"h":"Кондак 3","ps":["Си́ла Бо́жия ді́йствоваше чрез святу́ю іко́ну Твою́, Умиле́ніє імену́ємую, Богоро́дице Пречи́стая, єгда́ сія́ в ке́ллії преподо́бнаго Серафи́ма пребива́ше і ісціле́нія ві́рним істоча́ше, і́же отвсю́ду к нему́ прихожда́ху і от Тебе́ мно́гія да́ри благода́тния улуча́ху, благода́рно пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я ві́ру і любо́в к Тебі́, Богоро́дице, преподо́бний Серафи́м по Бо́зі всю наде́жду свою́ на Тя возлага́ше, іко́ну же Твою́ святу́ю благогові́йно почита́ше, свіщи́ і єле́й пред не́ю возжига́я і те́плі моля́ся Тебі́, да бу́деши єму́ Помо́щниця во спасе́ніє. О сем і ми Тя мо́лим, Преблага́я, і со усе́рдієм поє́м:","Ра́дуйся, свіще́ всеми́рная, мрак язи́чеський просвіти́вшая Сві́том Христо́вим;","ра́дуйся, Ста́мно всезлата́я, в не́йже угото́вася Хліб Небе́сний.","Ра́дуйся, денни́це Со́лнця пра́вди;","ра́дуйся, заре́ невече́рняя безсме́ртния жи́зні.","Ра́дуйся, па́дшаго челові́чеськаго єстества́ обновле́ніє;","ра́дуйся, дре́внія вражди́ разруше́ніє.","Ра́дуйся, ра́достноє святи́х созерца́ніє;","Ра́дуйся, сла́досте, услади́вшая го́реч гріхо́вную.","Ра́дуйся, о́блаче, ро́су спаси́тельную істочи́вий;","ра́дуйся, алава́стре, ми́ра Боже́ственнаго по́лний.","Ра́дуйся, окамене́нних серде́ць ум'ягче́ніє;","ра́дуйся, ві́ри і благоче́стія возраще́ніє.","Ра́дуйся, Влади́чице, Ра́досте, Умиле́ніє і Спасе́ніє душ на́ших."]},{"h":"Кондак 4","ps":["Бу́ри гріхо́вния ізбіжа́ти і в ти́хоє приста́нище покая́нія прийти́ помози́ нам, Пречи́стая Ді́во, Іскупи́теля і Спаси́теля душ на́ших ро́ждшая і Ма́тернєє дерзнове́ніє к Нему́ іму́щая; простри́ к Нему́ богоно́снеї Твої́ ру́ці і умоли́ Єго́ бла́гость вся ни поми́ловати і спасти́, да благода́рні поє́м Єму́ о Тебі́ славосло́вія піснь: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше о премно́гих чудесі́х Твої́х, Богоро́дице Ді́во, от іко́ни Твоєя́ святи́я явле́нних і присноявля́ємих ві́рним, ра́дуємся ми грі́шнії, я́ко дарова́ла єси́ нам такови́й благода́тний зало́г Твоєго́ к нам благоволе́нія, Всеблага́я, і от ра́достних і благода́рних усте́н сицево́є прино́сим Ті пі́ніє:","Ра́дуйся, оби́тель дів под Ма́терній покро́в Твой ми́лостиво приє́мшая;","ра́дуйся, оби́тель ма́лую і убо́гую распространи́вшая і духо́вно обогати́вшая.","Ра́дуйся, обітова́ніє Твоє́, пра́ведному Серафи́му о ней ізрече́нноє, ві́рно іспо́лнившая;","ра́дуйся, іко́ною Твоє́ю пребива́ти в ней ізво́лившая.","Ра́дуйся, наде́ждо на́ша пресвята́я;","ра́дуйся, Ма́ти на́ша преблага́я.","Ра́дуйся, до́брая Младопита́тельнице ді́вам;","ра́дуйся, вдов і сиро́т Попечи́тельнице благоми́лостивая.","Ра́дуйся, заступле́ніє на́ше от враго́в неви́димих;","ра́дуйся, Помо́щнице на́ша в неча́янних біда́х.","Ра́дуйся, стіно́, огражда́ющая нас от гріхо́вних собла́знов ми́ра;","ра́дуйся, покро́ве, покрива́яй всіх к Тебі́ притека́ющих.","Ра́дуйся, Влади́чице, Ра́досте, Умиле́ніє і Спасе́ніє душ на́ших."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́, свята́я іко́на Твоя́, Богоро́дице Ді́во, лучи́ Бо́жия благода́ті неви́димо іспуща́єть і ду́ші ві́рних озаря́єть. Сію́ і ми с ві́рою і благогові́нієм лобиза́юще, в ско́рбіх утіше́ніє, в болі́зніх врачество́ безме́здноє от Тебе́, Влади́чице, приє́млем, і славосло́в'яще многопі́тоє і преблагослове́нноє і́м'я Твоє́, ра́достно поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів Тя, Богоро́дице, преподо́бний Серафи́м в пресла́вний день Благові́щенія, прише́дшую к нему́ в смире́нную єго́ ке́ллію со А́нгели, Предте́чею, Богосло́вом і ли́ком святи́х дів, ра́дости преми́рния іспо́лнися, і сія́ше лице́ єго́ ста́рчеськоє красото́ю Небе́сною. Ти же, сла́вою Боже́ственною єго́ озаря́ющи, ми́лостиво бесе́довала єси́ с ним, я́коже со дру́гом при́сним, обітова́нії благи́ми возвеселя́ющи ду́шу єго́ і си́ми подвиза́ющи нас вопи́ти Тебі́:","Ра́дуйся, обра́дованная Присноді́во;","ра́дуйся, Неві́сто неневі́стная.","Ра́дуйся, Цари́це Го́рних і до́льних;","ра́дуйся, Предводи́тельнице ді́вственних ликостоя́ній.","Ра́дуйся, от Небе́сних висо́т посіща́ющая земноро́дних;","ра́дуйся, явля́ющая лице́ Твоє́ пречи́стоє ізбра́нником Бо́жиїм.","Ра́дуйся, ли́ки святи́х, спутеше́ствующия Тебі́, імі́вшая;","ра́дуйся, собо́р святи́х дів с Собо́ю приве́дшая.","Ра́дуйся, ді́ві смире́нній і трепе́щущей явле́нія Твоєго́ сла́ву показа́вшая;","ра́дуйся, бесі́ди Твоєя́ Боже́ственния ту удосто́ївшая.","Ра́дуйся, ста́рця Серафи́ма посіще́нієм Твої́м облагода́тствовавшая;","ра́дуйся, с ним і вся ни духо́вно возвесели́вшая.","Ра́дуйся, Влади́чице, Ра́досте, Умиле́ніє і Спасе́ніє душ на́ших."]},{"h":"Кондак 6","ps":["Пропове́дуємо і везді́ похваля́ємо єсть от ві́рних посіще́ніє Твоє́, Ма́ти Бо́жия, єго́же преподо́бнаго Серафи́ма сподо́била єси́. Сіє́ посіще́ніє Твоє́ всеблаго́є і ми днесь благогові́йно воспомина́юще, благода́рственния пі́сні Тебі́ прино́сим, Пречи́стая, і хвале́бно восклиця́єм Си́ну Твоєму́ і Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ сія́ніє сла́ви Небе́сния в смире́нній ке́ллії преподо́бнаго Серафи́ма, єгда́ от Го́рних висо́т пришла́ єси́, Богоро́дице, с ли́ком святи́х того́ посіти́ти. Сего́ же не терп'я́щи зрі́ти, ді́ва сотаї́нниця Боже́ственнаго виді́нія ниць паде́ на зе́млю, но ми́лостиво ту воздви́гла єси́, Влади́чице, і преми́лостивия глаго́ли Твоя́ єй прорекла́ єси́. Таково́му благоснизхожде́нію Твоєму́ див'я́щеся, с любо́вію і благогові́нієм Тебі́ вопіє́м:","Ра́дуйся, Ді́во всеблага́я, ді́вство похвали́вшая ді́ві земні́й;","ра́дуйся, віне́ць Ца́рствія Небе́снаго єй обіща́вшая за ві́рность Жениху́ Христу́.","Ра́дуйся, А́нгели чти́мая і піва́ємая от Херуви́м;","ра́дуйся, Арха́нгели окружа́ємая і сла́вимая от Серафи́м.","Ра́дуйся, Предте́чу, Богосло́ва і лик святи́х дів с Тобо́ю в явле́нії чуде́сно показа́вшая;","ра́дуйся, в явле́нії Твоє́м обітова́нія блага́я ізбра́ннику Бо́жию дарова́вшая.","Ра́дуйся, сбитіє́м обітова́ній Твої́х і́стину явле́нія Твоєго́ засвиде́тельствовавшая;","ра́дуйся, на́ше похвало́ і утвержде́ніє.","Ра́дуйся, оби́телей і́ночеських ми́лостивоє попече́ніє і призрі́ніє;","ра́дуйся, Це́ркве Христо́ви Боже́ственная лі́пота.","Ра́дуйся, по́стников і преподо́бних та́йноє утіше́ніє;","ра́дуйся, христия́нськаго ро́да непости́дноє упова́ніє.","Ра́дуйся, Влади́чице, Ра́досте, Умиле́ніє і Спасе́ніє душ на́ших."]},{"h":"Кондак 7","ps":["Хотя́щим нам, Влади́чице, лобиза́ти святу́ю і всечестну́ю Твою́ іко́ну, не возбрани́ нам сіє́ гріхо́в ра́ди на́ших, і я́ко многоблагоутро́бная Ма́ти ми́лостиваго Бо́га, не возгнуша́йся на́ших нечи́стих усте́н, но прийми́ нас ми́лостиво, припа́дающих к Тебі́ с любо́вію, да́ри благода́тния ще́дро нам подава́ющи от многочуде́снаго Твоєго́ о́браза, да зове́м со умиле́нієм Трієди́ному Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вно і свя́то сконча́тися благоволи́ла єси́, Влади́чице, ізбра́ннику Твоєму́, блаже́нному Серафи́му: той бо коленопреклоне́нний на моли́тві пред іко́ною Твоє́ю свято́ю предаде́ пра́ведную ду́шу свою́ в ру́ці Бо́жії, і оти́де от земни́х на Го́рняя, созерца́ти сла́ву Твою́ Небе́сную і ви́ну зрі́ти Тя, Цари́це А́нгелов, Ю́же ми земні́ї немо́лчно ублажа́єм і поє́м Ті ра́достно:","Ра́дуйся, ми́ра Го́рняго пе́рвійшеє украше́ніє;","ра́дуйся, ми́ра до́льняго всекре́пкоє огражде́ніє.","Ра́дуйся, от Небе́снаго всесвята́го Твоєго́ жили́ща приника́ющая к земноро́дним;","ра́дуйся, от оби́телей Го́рніх снизходя́щая в юдо́ль на́шу многоско́рбную і многогрехо́вную.","Ра́дуйся, отира́ющая сле́зи от оче́с пла́чущих і печа́льних;","ра́дуйся, влива́ющая отра́ду і утіше́ніє в сердця́ огорче́нних.","Ра́дуйся, вдови́ць неіму́щих некра́домоє бога́тство;","ра́дуйся, безма́терніх сиро́т призрі́ніє і покро́ве.","Ра́дуйся, і́ноков Помо́щнице всеізря́дная;","ра́дуйся, і́нокинь Предста́тельнице всесвята́я.","Ра́дуйся, цілому́дрія христия́нськаго нача́ло і основа́ніє;","ра́дуйся, ді́вства пречу́дная красото́.","Ра́дуйся, Влади́чице, Ра́досте, Умиле́ніє і Спасе́ніє душ на́ших."]},{"h":"Кондак 8","ps":["Стра́нно єсть ви́діти, ка́ко іко́на Твоя́ свята́я, Богоро́дице Ді́во, си́лою Бо́жиєю благода́ті преісполня́ється і ди́вная чудеса́ істоча́єть благоволе́нієм Твої́м, Всеблага́я. Сію́ і ми стяжа́вше во утіше́ніє і цільбу́, благода́рственно Тя сла́вим, Влади́чице Пречи́стая, і поє́м ро́ждшемуся от Тебе́ Бо́гу Сло́ву А́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся до́брая і поле́зная да́руєши нам, Богоро́дице, от всечестна́го і многочуде́снаго Твоєго́ о́браза: умиля́єши ду́ші на́ша і врачу́єши болі́зні на́ша, я́ко воі́стину многоблагоутро́бная Ма́ти чад Твої́х, о Христі́ Бо́зі. Ті́мже по достоя́нію блажи́ма єси́ от нас благохвале́нії такови́ми:","Ра́дуйся, от восто́ка і до за́пада сла́вимая і превозноси́мая;","ра́дуйся, от всіх христия́нских родо́в піва́ємая і блажи́мая.","Ра́дуйся, душеполе́зних даро́в Пода́тельнице незави́стная;","ра́дуйся, душе́вних і тіле́сних неду́г Ціли́тельнице благода́тная.","Ра́дуйся, безнаде́жних наде́ждо;","ра́дуйся, огорче́нних отра́до.","Ра́дуйся, гони́мих прибі́жище;","ра́дуйся, ві́рних крі́пкоє заступле́ніє.","Ра́дуйся, неві́рних обраще́ніє;","ра́дуйся, чудеси́ Твої́ми всіх удивля́ющая.","Ра́дуйся, ми́лостію Твоє́ю нас посіща́ющая;","ра́дуйся, преі́скренні спасти́ся всім хотя́щая.","Ра́дуйся, Влади́чице, Ра́досте, Умиле́ніє і Спасе́ніє душ на́ших."]},{"h":"Кондак 9","ps":["Всі ро́ди христия́нстії і́муть Тя, Влади́чице, Помо́щницю ізря́дную: я́коже бо обіща́ла єси́ во всечестні́м Твоє́м успе́нії не оста́вити нас си́рих і безпомо́щних, та́ко і до днесь сіє́ обітова́ніє всеблаго́є ісполня́єши в Це́ркві Христо́ві на землі́, Богоро́дице Ді́во, ущедря́ющи і спаса́ющи лю́ди, ві́рно Тя сла́в'ящия і правосла́вно пою́щия Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Вети́йство челові́чеськоє не мо́жеть ізрещи́ оби́ліє щедро́т і ми́лостей Твої́х, Ма́ти Бо́жия, сла́вити же Тя по достоя́нію недоуміва́ють у́ми безпло́тнії, оба́че Блага́я су́щи, не возгнуша́йся і на́ших недосто́йних похва́л, ї́хже любо́вію Тебі́ прино́сим і дерза́єм воспіва́ти Тя си́це:","Ра́дуйся, луно́ по́лная, нощ гріхо́в на́ших просвіща́ющая;","ра́дуйся, крі́пким сія́нієм Твої́м мглу страсте́й на́ших разгоня́ющая.","Ра́дуйся, Путеводи́тельнице заблу́ждших;","ра́дуйся, Вразуми́тельнице бу́їїх.","Ра́дуйся, ю́них Наста́внице цілому́дрія;","ра́дуйся, ді́вства покро́ве і огражде́ніє.","Ра́дуйся, оби́тель дів благоустро́ївшая пречу́дно;","ра́дуйся, я́вльшая єй Твоє́ благоволе́ніє о́бразом Свої́м всечестни́м.","Ра́дуйся, упова́ющим на Тя коне́ць благи́й да́рующая;","ра́дуйся, лю́б'ящия і чту́щия Тя непосрамля́ющая.","Ра́дуйся, єди́на до́брая і благослове́нная в жена́х;","ра́дуйся, єди́на чи́стая і непоро́чная Присноді́во,","Ра́дуйся, Влади́чице, Ра́досте, Умиле́ніє і Спасе́ніє душ на́ших."]},{"h":"Кондак 10","ps":["Спаси́телю Бо́гу плоть взаїмода́вшая, нетлі́нная і Пречи́стая Ма́ти Бо́жия, очи́сти нас, оскверне́нних гріхи́ мно́гими, іссо́пом моли́тв Твої́х святи́х, в цілому́дрії і чистоті́ утверди́ і сподо́би богоуго́дно і пра́ведно препроводи́ти житіє́ сіє́ земно́є, да благоугоди́вше Христу́ Бо́гу, унаслі́дуєм Ца́рствіє Єго́ Небе́сноє і со святи́ми воспоє́м Єму́ побі́дную піснь: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ ді́вам, Богоро́дице Ді́во, і всім душа́м христия́нським, уневе́стившимся Небе́сному Жениху́, я́же в треволне́нії страсте́й обріта́ють всегда́ крі́пкую Твою́ по́мощ. Мо́лим Тя, Всеблага́я, не попусти́ і нам грі́шним поги́бнути во бла́ті страсте́й, но простри́ нам держа́вную десни́цю Твою́ і возста́ви нас на покая́ніє і цілому́дренноє житіє́, да благода́рно Тебі́ зове́м:","Ра́дуйся, приста́нище ти́хоє пловце́м жите́йськаго мо́ря;","ра́дуйся, прибі́жище благооти́шноє утомле́нним бу́рею страсте́й.","Ра́дуйся, Спору́чнице покая́нія грі́шних;","ра́дуйся, ка́ющихся с Бо́гом примире́ніє.","Ра́дуйся, Судії́ пра́веднаго ізві́стноє умоле́ніє;","ра́дуйся, всежела́тельноє і всесла́дкоє святи́х утіше́ніє.","Ра́дуйся, Го́рніх А́нгельських во́їнств удивле́ніє;","ра́дуйся, му́ченичеських сві́тлих полко́в непрестаю́щеє велича́ніє.","Ра́дуйся, пра́ведних жен всевеселя́щеє ра́дованіє;","ра́дуйся, дів святи́х ві́нче.","Ра́дуйся, преподо́бних многопі́тая сла́во.","Ра́дуйся, святи́телей в пра́вій ві́рі укріпле́ніє.","Ра́дуйся, Влади́чице, Ра́досте, Умиле́ніє і Спасе́ніє душ на́ших."]},{"h":"Кондак 11","ps":["Пі́ніє хвале́бноє прино́сим Ті, Богоро́дице Пречи́стая, свято́ю і многочуде́сною іко́ною Твоє́ю осіня́ємі і моли́твами ста́рця Серафи́ма укріпля́ємі. О держа́вном же заступле́нії Твоє́м ра́дующеся, вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́тлими луча́ми чуде́с Твої́х, Богома́ти Влади́чице, озаря́єши мра́чния на́ша ду́ші среди́ суєві́рія і неві́рія на́ших дній. Зря́ще же ми́лості і щедро́ти Твоя́, от іко́ни Твоєя́ нам істоча́ємия, Всеблага́я, і припа́дающе к ней, си́це Тебі́ вопіє́м:","Ра́дуйся, Правосла́вія утвержде́ніє;","ра́дуйся, ві́ри Христо́ви распростране́ніє.","Ра́дуйся, єресе́й і раско́лов посрамле́ніє;","ра́дуйся, неві́рія іскорене́ніє.","Ра́дуйся, чудеси́ Твої́ми ві́рния утіша́ющая;","ра́дуйся, милосе́рдієм Твої́м грі́шники неоставля́ющая.","Ра́дуйся, в час кончи́ни упова́ющим на Тя помога́ющая;","ра́дуйся, лю́б'ящим Тя любо́вію свято́ю воздаю́щая.","Ра́дуйся, в ско́рбіх і біда́х на по́мощ ускоря́ющая;","ра́дуйся, болі́зні неісці́льния врачу́ющая.","Ра́дуйся, скоропослушли́вая к моли́твам смире́нним;","ра́дуйся, проше́нія блага́я предваря́ющая ісполне́нієм.","Ра́дуйся, Влади́чице, Ра́досте, Умиле́ніє і Спасе́ніє душ на́ших."]},{"h":"Кондак 12","ps":["Благода́ть Бо́жия от і́кони Твоєя́, Богоро́дице Ді́во, ісходя́щая, осіня́єть оби́тель дів, ізбра́нником Твої́м Серафи́мом собра́нную і устро́єнную до́брі. Сію́ іко́ну Твою́, я́ко зало́г благоволе́нія Твоєго́, ди́вно стяжа́вше, сла́вим і велича́єм Тя, Влади́чице преми́лостивая, і ра́бськи вопіє́м всіх Творцю́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще милосе́рдіє Твоє́ неісче́тноє і мно́гая Твоя́ чудеса́, Ді́во Всепі́тая, ра́дуємся ми грі́шнії, зря́ще на іко́ні лик Твой святи́й, умиле́нія преіспо́лненний, і́же і в на́ша ду́ші умиле́ніє влива́єть і к моли́твам усе́рдним нас привлека́єть, да си́це Тебі́ взива́єм:","Ра́дуйся, Ни́во неора́нная, Клас спаси́тельний челові́ком ізрасти́вшая;","ра́дуйся, Лі́ствице Небе́сная, Є́юже сни́де Бог.","Ра́дуйся, Горо́ несіко́мая, усире́нная Ду́хом Святи́м;","ра́дуйся, Ски́ніє селе́нія Ви́шняго.","Ра́дуйся, Свята́я Святи́х превосходя́щая;","ра́дуйся, Клеще́ та́їнственная, угль Божества́ неопа́льно приє́мшая.","Ра́дуйся, хла́дная сердця́ на́ша любо́вію ко Го́споду воспламеня́ющая;","ра́дуйся, нечистоту́ душ на́ших благода́тію очища́ющая.","Ра́дуйся, на по́двиги духо́вния неви́димо нас укріпля́ющая;","ра́дуйся, ісполня́ти велі́нія Христо́ва нам помога́ющая.","Ра́дуйся, душевре́дния на́вики в нас іскореня́ющая.","Ра́дуйся, стра́сті душетлі́нния попаля́ющая.","Ра́дуйся, Влади́чице, Ра́досте, Умиле́ніє і Спасе́ніє душ на́ших."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти! О Цари́ці всеми́лостивая! Богоро́дице Всеблага́я! Умоли́ Си́на Твоєго́, Христа́ Бо́га на́шего, ізба́вити нас геє́нни о́гненния і сподо́бити спасе́нних ча́сти, да со ізбра́нними воспоє́м Єму́ во ві́ки: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел земни́й і челові́к Небе́сний, преподо́бний ста́рець Серафи́м іко́ну Твою́ святу́ю, Богоро́дице Ді́во, я́ко драгоці́нноє сокро́вище в своє́й ке́ллії стяжа́ і пред не́ю усе́рдния моли́тви Тебі́ принося́, Всепі́тая, во вся дні подви́жничеськаго житія́ своєго́ благоумиле́нно, Ра́достію всіх ра́достей Тя найменова́, си́це Тебі́ взива́я:","Ра́дуйся, обра́довавшая па́дшеє челові́чество всесвяти́м Твої́м Рождество́м;","ра́дуйся, Спаси́теля ми́ру нетлі́нно ро́ждшая і ді́вство сохра́ньшая преди́вно.","Ра́дуйся, Ма́ти і Ді́во преблагослове́нная;","ра́дуйся, Богоро́дице препросла́вленная.","Ра́дуйся, пала́то Бо́га Сло́ва прекра́сная;","ра́дуйся, світоно́сная ло́жнице Царя́ царе́й.","Ра́дуйся, проро́чеських глаго́лов сбитіє́ прине́сшая;","ра́дуйся, апо́стольськія про́повіді крі́пкоє вспоможе́ніє.","Ра́дуйся, преподо́бних похвало́ і дів велича́ніє;","ра́дуйся, челові́чеськаго ро́да возвише́ніє.","Ра́дуйся, скорб'я́щих утіше́ніє;","ра́дуйся, боля́щих ісціле́ніє.","Ра́дуйся, Влади́чице, Ра́досте, Умиле́ніє і Спасе́ніє душ на́ших."]},{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Бо́жієй Ма́тері і Цари́ці, умиле́нно моля́щейся за ни ко Го́споду і о́браз Умиле́нія Своєго́ нам дарова́вшей ми́лостиво, похва́льноє пі́ніє і моле́ніє прино́сим Ті, Богоро́дице. Ти же, я́ко Всеми́лостивая на́ша Засту́пниця і Всеблага́я Помо́щниця, от вся́ких бід нас ізба́ви, да зове́м Ті:","Ра́дуйся, Влади́чице, Ра́досте, Умиле́ніє і Спасе́ніє душ на́ших."]},{"h":"Молитва","ps":["О Пресвята́я Ді́во Богоро́дице, Христа́ Царя́ і Бо́га на́шего Ма́ти, умиле́нія сокро́вище і ми́лости істо́чниче, душеспаси́тельних даро́в блага́я Пода́тельнице і скорб'я́щих душ благода́тная Уті́шительнице! К Тебі́ с любо́вію припа́даєм і пред свято́ю іко́ною Твоє́ю смире́нно мо́лимся: умоли́, Влади́чице, возлю́бленнаго Си́на Твоєго́, Христа́ Бо́га на́шего, поми́ловати і спасти́ нас, погиба́ющих во грісі́х; вдохни́ в ду́ші на́ша покая́ніє і́скреннєє і умиле́ніє богоуго́дноє, пода́ждь моли́твам на́шим сле́зи очисти́тельния; благопотре́бная житію́ вре́менному і ві́чному спасе́нію ми́лостиво, Госпоже́, нам да́руй; мир умири́, святи́й храм сей [іли́: святу́ю оби́тель сію́] до́брі сохрани́, безм'яте́жіє і ізоби́ліє плодо́в земни́х нам низпосли́, і при кончи́ні живота́ на́шего не лиши́ нас Ма́терняго Твоєго́ заступле́нія і по́мощі, да предста́тельством Твої́м безбі́дно пре́йдем мита́рства возду́шная і сподо́бимся унаслі́довати Ца́рствіє Небе́сноє. Єй, Цари́це Всеблага́я, всіх ра́достей Ра́досте і всего́ ми́ра христия́нськаго утіше́ніє! Помози́ нам і ни́ні, і єгда́ найпа́че по́мощі Твоєя́ святи́я востре́буєм, і спаси́ нас Ма́терніми мо́литвами Твої́ми ко Христу́ Бо́гу, Єму́же со Отце́м і Святи́м Ду́хом подоба́єть вся́кая сла́ва, честь і поклоне́ніє, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["К Богоро́диці с умиле́нієм припаде́м, / всі, гріхми́ обремене́ннії, / чудотво́рную Єя́ іко́ну Умиле́нія облобиза́юще / і вопію́ще со слеза́ми: / Влади́чице, прийми́ моле́ніє недосто́йних раб Твої́х / і пода́ждь нам, прося́щим, // ве́лію Твою́ ми́лость."]},{"h":"Кондак, глас 3","ps":["Ю́же подража́я непло́дную смоко́вницю, / аз, окая́нний, умиле́нія плода́ отню́д не приношу́ і посіче́нія страшу́ся, / но, взира́я к чудотво́рній іко́ні Твоє́й Умиле́нія, Влади́чице, / стеню́ от се́рдця і вопію́: / умили́ся, Благосе́рдая, / і мні, окамене́нному се́рдцем, // благоволи́ пода́ти душе́вноє і серде́чноє умиле́ніє."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Остробрамська Віленська»","e":"Akathist to the Theotokos before her icon “Ostrobramska” of Vilnius","secs":[{"h":"Кондак 1","ps":["Возбра́нной Воєво́ді і преди́вной Засту́пнице ро́да христия́нськаго, благоізво́лившей от святи́я Своєя́ іко́ни ізлива́ти нам струї́ благода́тних ісціле́ній, похва́льная воспису́єм Ті раби́ Твої́, Богоро́дице. Ти же, я́ко блага́я Засту́пниця чту́щих Тя, от вся́ких нас бід свободи́, да зове́м Ті:","Ра́дуйся, Влади́чице, іко́ною Твоє́ю Остробра́мською благода́ть і ми́лость нам явля́ющая."]},{"h":"Ікос 1","ps":["А́нгел с небесе́ по́слан бисть рещи́ Богоро́дице: Ра́дуйся! Ми же, земноро́днії, див'я́щеся воплоще́нію от Тебе́ Си́на Твоєго́ і Бо́га на́шего, дерза́єм воспіва́ти Тебі́ си́це:","Ра́дуйся, благода́тная Богоро́дице Ді́во;","ра́дуйся, преблагослове́нная в жена́х.","Ра́дуйся, я́ко Спа́са родила́ єси́ душ на́ших;","ра́дуйся, я́ко Свободи́теля яви́ла єси́ нам.","Ра́дуйся, небесе́ і землі́ Цари́це;","ра́дуйся, я́ко преви́шши єси́ вся́каго созда́нія.","Ра́дуйся, а́нгели на небесі́ чти́мая;","ра́дуйся, челові́ки на землі́ прославля́ємая.","Ра́дуйся, я́ко прише́дши ко Єлисаве́ті, Сама́ прорекла́ єси́: «Отни́ні ублажа́ть М'я всі ро́ди»;","ра́дуйся, я́ко воі́стину всі ро́ди до ни́ні Тя непреста́нно ублажа́ють.","Ра́дуйся, ві́рно Тя велича́ющим по́мощ ско́рую да́рующая;","ра́дуйся, чудотво́рними Свої́ми іко́нами, я́ко со́лнцем, світя́щая.","Ра́дуйся, Влади́чице, іко́ною Твоє́ю Остробра́мською благода́ть і ми́лость нам явля́ющая."]},{"h":"Кондак 2","ps":["Ви́дящи, всеблага́я Влади́чице, с висоти́ свята́го жили́ща Своєго́ скорб і тісноту́ житія́ в держа́ві на́шей, восхоті́ла єси́ яви́ти зді сла́ву Твою́, чудотво́рним о́бразом Твої́м подаю́щи скорб'я́щим утіше́ніє, боля́щим ісціле́ніє, бе́дствующим по́мощ, да ви́дяще такову́ю ми́лость Твою́ к нам, благода́рними усти́ воспіва́єм всі Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум богопросвіще́н іму́ще, святі́ї пра́отці і проро́ци в о́бразіх, виді́ніїх і со́ніїх чу́дноє Рождество́ Твоє́ і та́йну Присноді́вства Твоєго́ ізобрази́ша. Апо́столи же Христо́ві, проразумі́вше ду́хом, коль вожделі́нно бу́деть для ві́рующих ізображе́ніє святе́йшего ли́ка Пречи́стия Ді́ви Богома́тере, ізбра́ша із среди́ себі́ боже́ственнаго Луку́, я́ко живопи́сця преди́вна. І той, іспроси́в Ма́тернєє от Тебе́ благослове́ніє, подкрепля́ємий посто́м і моли́твою, написа́ пе́рвую іко́ну Твою́, Влади́чице, к не́йже Сама́ рекла́ єси́: с о́бразом сим бу́дуть благода́ть Моя́ і си́ла. Сего́ ра́ди со умиле́нієм і любо́вію воспіва́єм Тебі́:","Ра́дуйся, Лі́ствице висо́кая, Іа́ковом дре́вле ви́дінная;","ра́дуйся, зе́млю с Не́бом совоку́пльшая;","Ра́дуйся, Бо́га, на землі́ я́вльшагося, во чре́ві Твоє́м поне́сшая;","ра́дуйся, я́ко Неопали́мая Купина́ нетлі́нною преби́вшая.","Ра́дуйся, світоно́сний О́блаче, із него́же всіх Влади́ка, я́ко дождь на руно́, на зе́млю сни́де;","ра́дуйся, чу́дний Же́зле, цвіта́ми доброді́телей ві́рних украша́ющая.","Ра́дуйся, Живоно́сний Істо́чниче;","ра́дуйся, а́лчущим і жа́ждущим ві́чния пра́вди Насище́ніє ро́ждшая.","Ра́дуйся, Христа́, ма́нну жи́зні, во чре́во Своє́ вмісти́вшая;","ра́дуйся, ду́ші на́ша хлі́бом безсме́ртія насища́ющая.","Ра́дуйся, я́ко моля́щієся Тебі́ от вся́каго зла сохраня́ються;","ра́дуйся, я́ко Твоя́ честни́я іко́ни чудеса́ми прославля́ються.","Ра́дуйся, Влади́чице, іко́ною Твоє́ю Остробра́мською благода́ть і ми́лость нам явля́ющая."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіня́єть вся́каго челові́ка, с ві́рою притека́ющаго к Твоє́й цільбоно́сній іко́ні, ю́же дарова́ла єси́ лю́дем на утіше́ніє. Сего́ ра́ди і ми, со умиле́нієм взира́юще на святи́й Твой о́браз, я́ко живі́й Ті су́щей с на́ми, із глубини́ се́рдця вопіє́м: осіни́ і нас си́рих і безпомо́щних, да воспоє́м прославля́ющему Тя Го́споду: Аллилу́я."]},{"h":"Ікос 3","ps":["Іми́й благо́є попече́ніє о лю́діх благосе́рдий Госпо́дь, попусти́ іко́ні Твоє́й святі́й оста́вити на вре́м'я ні́коє храм Правосла́вния Це́ркве, єгда́ мона́си лати́нстії, взе́мше о́браз Твой святи́й, поста́виша єго́ во хра́мі своє́м. Ти же і та́мо яви́ла єси́ то́ки благода́тних чуде́с Твої́х, да позна́ють всі христия́не, коль си́льна єсть по́мощ Богома́тере, і да с ра́достію воспіва́ють Ті си́це:","Ра́дуйся, всіх христия́н помо́щнице;","ра́дуйся, Правосла́вния Це́ркве сла́во і утіше́ніє.","Ра́дуйся, я́ко отрокови́цею вошла́ єси́ в храм Госпо́день;","ра́дуйся, я́ко во хра́мі воспита́лася єси́.","Ра́дуйся, святи́х хра́мов пе́рвійшеє украше́ніє;","ра́дуйся, я́ко і Сама́ соді́лалася єси́ хра́мом Си́на Бо́жия.","Ра́дуйся, в четиредеся́тий день о́трока Ісу́са в храм Бо́жий прине́сшая;","ра́дуйся, я́ко сби́ся предрече́нноє Тебі́ во хра́мі Симео́ном Богоприї́мцем.","Ра́дуйся, лю́б'ящая всіх чту́щих хра́ми Бо́жия;","ра́дуйся, святи́х хра́мов тве́рдоє огражде́ніє.","Ра́дуйся, я́ко во Хра́мі Небе́снім ві́чно ца́рствуєши;","ра́дуйся, я́ко вся ві́рния в храм сей ввести́ тщи́шися.","Ра́дуйся, Влади́чице, іко́ною Твоє́ю Остробра́мською благода́ть і ми́лость нам явля́ющая."]},{"h":"Кондак 4","ps":["Бу́рю земна́го ско́рбнаго житія́ на́шего в не́мощіх і болі́зніх ви́дящи, Премилосе́рдная Ма́ти Бо́жия благоізво́ли би́ти чу́ду явле́нія о́браза своєго́ во гра́ді Ки́єве, ті́мже ми с ра́достію неізрече́нною припа́даєм к Тебі́, Влади́чице, і із глубини́ душі́ благодари́м Тя, ди́вную Засту́пницю, воспіва́юще Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше бли́жнії і да́льнії о ди́вном чудеси́ святи́я іко́ни Твоєя́, Пречи́стая Влади́чице, со усе́рдієм мно́гим притека́ху к цільбоно́сному Твоєму́ о́бразу, приє́мля от него́ да́ри неісче́тних Твої́х благодія́ній. Ті́мже і ми, а́ще і недосто́йни су́ще, со благогові́нієм і ра́достію покланя́ємся Тебі́ пред сим чу́дним о́бразом і достодо́лжно Тя пі́сньми ублажа́єм:","Ра́дуйся, обі́т ді́вства Го́сподеві да́вшая;","ра́дуйся, до конця́ той соблю́дшая.","Ра́дуйся, ді́вство і рождество́ сочета́вшая;","ра́дуйся, я́ко по рождестві́ пребила́ єси́ Ді́ва непоро́чная.","Ра́дуйся, до́брия обі́ти приє́млющая;","ра́дуйся, не соблюда́ющих обі́ти наказу́ющая.","Ра́дуйся, покрови́тельнице притека́ющих к Тебі́ по обі́ту пало́мников;","ра́дуйся, ми́лости да́рующая Тебі́ моля́щимся.","Ра́дуйся, благи́м намі́ренієм спосо́бствующая;","ра́дуйся, зла́я начина́нія разруша́ющая.","Ра́дуйся, во дні земна́го стра́нствія на́шего до́брая Путеводи́тельнице;","ра́дуйся, к ти́хому приста́нищу нас приводя́щая.","Ра́дуйся, Влади́чице, іко́ною Твоє́ю Остробра́мською благода́ть і ми́лость нам явля́ющая."]},{"h":"Кондак 5","ps":["Я́ко лучеза́рная звізда́ возсія́ в страні́ на́шей свята́я Твоя́ чудотво́рная іко́на, Богоро́дице Ді́во. Ми же, озаря́ємії сія́нієм пресві́тлих чуде́с Твої́х, преклоня́юще колі́на се́рдця, вопіє́м Пода́телю чуде́с Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дящи, я́ко тще́тна єсть по́мощ враче́в земни́х, уврачева́ти боля́щаго си́на не могу́щих, боголюби́вая ма́ти єго́ нача́ть возноси́ти усе́рдния моли́тви ко Врачу́ небе́сному. Вразумле́ніє получи́в призва́ти в по́мощ Тя, Богоро́дице, поспіши́ в храм Твой, ко свято́му о́бразу Твоєму́ і, соверши́в пред ним усе́рдноє моле́бноє пі́ніє, іспроси́ чуде́снаго ісціле́нія си́на. Сего́ ра́ди і ми немощні́ї, наді́ющіїся на Твою́ всеси́льную по́мощ, дерза́єм воспіва́ти Ті:","Ра́дуйся, немощни́м здра́віє да́рующая;","ра́дуйся, вся́кия болі́зні ісціля́ющая.","Ра́дуйся, оста́вленних врача́ми под Свой покро́в приє́млющая;","ра́дуйся, ісціле́ніє їм подаю́щая.","Ра́дуйся, огнь лю́тия болі́зні утоля́ющая;","ра́дуйся, от одра́ сме́ртнаго возставля́ющая.","Ра́дуйся, безнаде́жним наді́яніє;","ра́дуйся, упова́ніє на́ше непости́дноє.","Ра́дуйся, не́мощі душе́вния врачу́ющая;","ра́дуйся, грі́шников на путь пра́вий наставля́ющая.","Ра́дуйся, гріхо́вную от'є́млющая скве́рну;","ра́дуйся, ба́не, омива́ющая со́вість.","Ра́дуйся, Влади́чице, іко́ною Твоє́ю Остробра́мською благода́ть і ми́лость нам явля́ющая."]},{"h":"Кондак 6","ps":["Предстоя́ще пред Твої́м о́бразом, архієре́єв сосло́віє, свяще́нници, мона́си і всі лю́діє пропові́дують неісче́тная Твоя́ благодія́нія, я́же оби́льно ізлива́єши от святи́я Твоєя́ іко́ни. Сего́ ра́ди і ми, грі́шнії, предстоя́ще ни́ні пред чудотво́рним Твої́м о́бразом, ві́руєм і упова́єм, я́ко іспро́сиши вся блага́я і поле́зная нам у Си́на Твоєго́ і Бо́га на́шего, Єму́ же дерзнове́нно вопіє́м: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ благода́ть от святи́я Твоєя́ іко́ни, ю́же іногда́ я́ві узрі́ша разбо́йници; ті́ї же че́стно іспові́давше гріхи́ своя́ вся і ізба́вльшеся Тобо́ю от ві́рния сме́рті духо́вния, научи́ша ни воспіва́ти Ті похвали́ сія́:","Ра́дуйся, от напра́сния сме́рті спаса́ющая;","ра́дуйся, от гріха́ сме́ртнаго ізбавля́ющая.","Ра́дуйся, Нача́льника живота́ і сме́рті ро́ждшая;","ра́дуйся, Ма́ти Живота́, смерть умертви́вшаго.","Ра́дуйся, я́ко в час сме́рти Своєя́ ти́хо возлегла́ єси́ на одрі́ Своє́м;","ра́дуйся, я́ко Син Твой і Бог наш кро́тко ду́шу Твою́ от ті́ла отділи́.","Ра́дуйся, я́ко с ті́лом взята́ била́ єси́ на не́бо;","ра́дуйся, я́ко і по сме́рті жи́ва єси́.","Ра́дуйся, непости́дную кончи́ну нам да́рующая;","ра́дуйся, в час кончи́ни на́шея нас заступа́ющая.","Ра́дуйся, і по сме́рті нас не оставля́ющая;","ра́дуйся, от возду́шних мита́рств спаса́ющая.","Ра́дуйся, Влади́чице, іко́ною Твоє́ю Остробра́мською благода́ть і ми́лость нам явля́ющая."]},{"h":"Кондак 7","ps":["Хотя́й яви́ти ве́лію любо́в Свою́ к лю́дям, Человіколю́бець Госпо́дь Тебе́, Ма́тер Свою́ Пренепоро́чную, покро́в і защи́ту ро́ду христия́нському дарова́, да бу́деши печа́льним утіше́ніє, скорб'я́щим ра́дованіє, отча́янним наді́яніє, ві́чния му́ки Свої́м хода́тайством ізбавля́ющи і к небе́сному весе́лію всіх приводя́щи, вопію́щих непреста́нно гла́сом хвале́нія Си́ну Твоєму́ і Бо́гу на́шему: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє чу́до дарова́ла єси́, Ді́во Богоро́дице, от боголі́пния іко́ни Своєя́, єгда́ возвраща́ла ча́да похи́щенния роди́телем їх, усе́рдно к ли́ку Твоєму́ свято́му с моли́твою притека́ющим. Ми же, с любо́вію прославля́юще Тя, Помо́щницю на́шу Всеїзря́дную, немо́лчними гла́си вопіє́м:","Ра́дуйся, Свої́м прише́ствієм нас обогаща́ющая;","ра́дуйся, всіх прибіга́ющих под кров Твой приє́млющая.","Ра́дуйся, ра́ни гріхо́вния благоутро́бно врачу́ющая;","ра́дуйся, пра́ведний гнів Бо́жий на нас, грі́шних, Твої́м моле́нієм ско́ро утоля́ющая.","Ра́дуйся, терпіли́вих страда́льцев дара́ми благода́тними ущедря́ющая;","ра́дуйся, к покая́нію нас призива́ющая.","Ра́дуйся, грі́шников моле́ній не отверга́ющая;","ра́дуйся, жела́нія богоуго́дная ісполня́ющая.","Ра́дуйся, ра́дость ско́рую подаю́щая;","ра́дуйся, на смире́нния призира́ющая.","Ра́дуйся, враго́в на́ших ви́димих і неви́димих побіжда́ющая;","ра́дуйся, лю́б'ящия і чту́щия Тя от вся́ких бід ізбавля́ющая.","Ра́дуйся, Влади́чице, іко́ною Твоє́ю Остробра́мською благода́ть і ми́лость нам явля́ющая."]},{"h":"Кондак 8","ps":["Стра́нно і сумни́тельно неве́рующим сли́шати, ка́ко от святи́я Твоєя́ іко́ни чудеса́ істоча́ються, одебелі́ бо се́рдце люде́й сих, я́ко ви́дяще не ви́дять і сли́шаще не сли́шать і не обратя́ться к Тебі́, да ісціли́ши їх. Ми же, усе́рдно почита́юще чудотво́рний о́браз Твой, прекло́ньше колі́на, уми́льно лобиза́єм єго́, вопію́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь мир преіспо́лнен, я́ко звізда́ми Богосві́тлими, чудотво́рними іко́нами Твої́ми, Богоро́дице Ді́во, в ни́хже я́ко Со́лнце лучеза́рноє, імі́ющеє луну́ подно́жієм і звізд сих зна́меніями окруже́нная, іко́на Твоя́ Остробра́мськая преди́вними чудеси́ благода́тно сія́єть і согріва́єть хла́дния сердця́ на́ша зна́меньми Твоєго́ о нас ми́лостиваго попече́нія. Сего́ ра́ди честву́єм Пречи́стаго Ли́ка Твоєго́ свято́є ізображе́ніє і Тебі́ пред ним вопіє́м:","Ра́дуйся, благочести́вих і́ноков і і́нокинь блага́я покрови́тельнице;","ра́дуйся, ієре́єв благогові́йних похвало́.","Ра́дуйся, во дні ско́рбнаго житія́ на́шего на землі́ ско́рая помо́щнице;","ра́дуйся, во всіх біда́х і напа́стіх всемо́щная защи́тнице.","Ра́дуйся, а́лчущих корми́тельнице;","ра́дуйся, жа́ждущим жи́зні питіє́ неісчерпа́ємоє.","Ра́дуйся, сиро́т незри́мая воспита́тельнице;","ра́дуйся, вдов заступле́ніє.","Ра́дуйся, лі́ствице небе́сная, є́юже Бог к нам сни́де;","ра́дуйся, мо́сте, преводя́й су́щих от землі́ на не́бо.","Ра́дуйся, ключу́ ца́рствія Христо́ва;","ра́дуйся, две́рі ра́йськія нам отверза́ющая.","Ра́дуйся, Влади́чице, іко́ною Твоє́ю Остробра́мською благода́ть і ми́лость нам явля́ющая."]},{"h":"Кондак 9","ps":["Вся́каго єстества́ а́нгельськаго преви́шши єси́, Богоро́дице Ді́во, честні́йшая Херуви́м, і сла́внійшая без сравне́нія Серафи́м, предстоя́щи бо Си́ну Твоєму́ на Небесі́, ви́ну мо́лишися Єму́ за род христия́нський, сего́ ра́ди і начерта́ніє сей пі́сні а́нгельськой на іко́ні Своє́й і́маши. Не преста́ни моли́тися і о нас, недосто́йних, у престо́ла Вседержи́теля, да с ра́достію вопіє́м Го́сподеві: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії не возмо́гуть по достоя́нію восхвали́ти преди́вная чудеса́, от святи́я Твоєя́ іко́ни явля́ємая, ізуміва́єть же ум всяк пі́ти Тя, Богоро́дице. Ти же, я́ко блага́я су́щи, прийми́ от нас похвали́ сія́:","Ра́дуйся, за христия́н Си́ну Твоєму́ усе́рдно моля́щаяся;","ра́дуйся, страну́ на́шу святи́м Твої́м омофо́ром покрива́ющая.","Ра́дуйся, ум наш к Бо́гу приводя́щая;","ра́дуйся, зли́я на́ша по́мисли іскореня́ющая.","Ра́дуйся, се́рдце на́ше любо́вію к Бо́гу воспламеня́ющая;","ра́дуйся, хоті́ніє на́ше ко бла́гу наставля́ющая.","Ра́дуйся, гнів Бо́жий, пра́ведно на ни дви́жимий, ско́ро утоля́ющая;","ра́дуйся, ко́зні духо́в зло́би разруша́ющая.","Ра́дуйся, от їх нападе́нія нас охраня́ющая;","ра́дуйся, во іскуше́ніїх пло́ті і ду́ха крі́пкая помо́щнице.","Ра́дуйся, па́дших ско́роє воста́ніє;","ра́дуйся, к Бо́гу на́ше дерзнове́ніє.","Ра́дуйся, Влади́чице, іко́ною Твоє́ю Остробра́мською благода́ть і ми́лость нам явля́ющая."]},{"h":"Кондак 10","ps":["Спасе́нія і́щуще, к Тебі́ прибіга́єм, Милосе́рдная Ма́ти, і іко́ну Твою́ святу́ю ни́ні обстоя́ще, со благогові́нієм і ві́рою честву́єм, і́бо всім покланя́ющимся Тебі́ ско́роє вспоможе́ніє подає́ши, і во іни́х граді́х і ве́сіх чту́щих Тя поле́зноє проше́ніє ісполня́єши. Ті́мже, воспомина́я неісче́тная чудотворе́нія Твоя́, вопіє́м Всемогу́щему Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ Ти, огражда́ющая нас от вся́ких болі́зней, всім с ві́рою призива́ющим Тя в по́мощ, Пресвята́я Ді́во Богоро́дице. Ти бо, Ма́ти, младе́нцю, зіло́ стра́ждущему, ісціле́ніє дарова́ла єси́. Сего́ ра́ди, прославля́юще Твоє́ Ма́тернеє милосе́рдіє, благода́рственними усти́ вопіє́м Ті всі із глубини́ душі́:","Ра́дуйся, я́ко по моли́тві пред іко́ною Твоє́ю болі́зні лю́тия прекраща́ються;","ра́дуйся, всім во вся́кой потре́бі вся поле́зная і блага́я подава́ющая.","Ра́дуйся, нікого́же отрева́ющая;","ра́дуйся, призива́ющих Тя заступа́ющая.","Ра́дуйся, в семе́йствах мир і дружелю́біє устроя́ющая;","ра́дуйся, ма́терей дітородя́щих ско́ро і безболі́зненно от бре́мені разріша́ющая.","Ра́дуйся, чад їх благода́тно охраня́ющая;","ра́дуйся, ско́рбним вдови́цям і си́рим помога́ющая.","Ра́дуйся, в бра́ні на́шей со духа́ми зло́би нам помога́ющая;","ра́дуйся, от наві́тов вра́жиїх нас спаса́ющая.","Ра́дуйся, от клевети́ і досажде́нія охраня́ющая;","ра́дуйся, блага́я Домострої́тельнице, житіє́ на́ше до́брі устроя́ющая.","Ра́дуйся, Влади́чице, іко́ною Твоє́ю Остробра́мською благода́ть і ми́лость нам явля́ющая."]},{"h":"Кондак 11","ps":["Пі́ніє на́ше, а́ще би́ло би і тьмочи́сленноє, не довлі́єть к досто́йному прославле́нію ми́лостей Твої́х, Всехва́льная Влади́чице, я́же непреста́нно ізлива́єши ро́ду челові́чеському. Мольбу́ безча́дних супру́гов, прише́дших к чудотво́рній іко́ні Твоє́й, не оста́вила тще́тною, но дарова́ла єси́ їм ми́лость діторожде́нія. Тім же, да не неблагода́рни яви́мся пред Тобо́ю, по си́лі на́шей похва́льная воспису́єм Ті с любо́вію, вопія́ Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Я́ко світоприє́мную свіщу́ зрим Твою́ честну́ю іко́ну, Пречи́стая і Преблагослове́нная Ді́во Богоро́дице, невеще́ственний в душа́х на́ших возжига́юще огнь любві́ к Тебі́, Всеблага́я. Ти же прийми́ ві́ру і усе́рдіє на́ше, напра́ви на стезі́ і́стини путь наш, умоли́ Го́спода і Си́на Твоєго́, да спасе́ть нас, і́миже вість судьба́ми, да не поги́бнем в нераска́янії о грісі́х на́ших, і усли́ши моле́ніє к Тебі́ взива́ющих:","Ра́дуйся, чрез іко́ну Твою́ нам благоде́ющая;","ра́дуйся, Ма́тернія щедро́ти Твоя́ на нас ізлива́ющая.","Ра́дуйся, гріхо́вния по́мисли вла́стно отгоня́щая;","ра́дуйся, малове́рних вразумля́ющая.","Ра́дуйся, неві́рних сми́сли просвіща́ющая;","ра́дуйся, милосе́рдіє Бо́жиє разумі́ти нам помога́ющая.","Ра́дуйся, страх Бо́жий в сердця́ ві́рних влага́ющая;","ра́дуйся, о хра́мах Бо́жиїх попече́ніє іму́щих духо́вною ра́достію утіша́ющая.","Ра́дуйся, от сна лі́ности нас возставля́ющая;","ра́дуйся, сві́том Богопозна́нія і благоче́стія омраче́нних озаря́ющая.","Ра́дуйся, бла́га земна́я, су́єтния і скоропреходя́щия, презира́ти нас науча́ющая;","ра́дуйся, к небе́сним і ві́чним сокро́вищам уми́ і сердця́ на́ша возводя́щая.","Ра́дуйся, Влади́чице, іко́ною Твоє́ю Остробра́мською благода́ть і ми́лость нам явля́ющая."]},{"h":"Кондак 12","ps":["Благода́ть да́ти восхоті́в, дарова́ нам Госпо́дь цільбоно́сную іко́ну Твою́, пред не́ю же вознося́ще усе́рдная моле́нія, возводи́м ум свой к Первообра́зній — Тебі́, Богоро́дице, прося́щи дарова́ти нам блага́я і поле́зная во вре́менній жи́зні сей, і в бу́дущей жи́зні блаже́нство безконе́чноє, да воспоє́м со а́нгели і всі́ми святи́ми на небесі́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоя́ чудеса́, я́же оби́льно істоча́єши нам от святи́я Своєя́ іко́ни, хва́лим Тя, Пресвята́я Богоро́дице і, предстоя́ще пред пречи́стим Твої́м о́бразом со слеза́ми, умиле́нною душе́ю і сокруше́нним се́рдцем взива́єм Ті:","Ра́дуйся, Засту́пнице усе́рдная ро́да христия́нськаго;","ра́дуйся, Ма́ти Го́спода і на́ша Ма́ти і покрови́тельнице.","Ра́дуйся, істоча́ющая всім нам неоску́дния ми́лості;","ра́дуйся, ізбавля́ющая от вся́ких бід і напа́стей благонра́вния і богобоя́щіяся раби́ Своя́.","Ра́дуйся, тіле́с на́ших здра́віє;","ра́дуйся, душ на́ших спасе́ніє.","Ра́дуйся, я́ко за всіх мо́лиши Си́на Твоєго́ і Бо́га на́шего;","ра́дуйся, я́ко всім твори́ши спасти́ся.","Ра́дуйся, ізбавле́ніє всіх зол;","ра́дуйся, поле́зная всім да́рующая.","Ра́дуйся, я́ко Тя єди́ну наде́жду і́мами;","ра́дуйся, я́ко Ти єси́ боже́ственний покро́в рабо́м Твої́м.","Ра́дуйся, Влади́чице, іко́ною Твоє́ю Остробра́мською благода́ть і ми́лость нам явля́ющая."]},{"h":"Кондак 13","ps":["О, всепі́тая Ма́ти, ро́ждшая всіх святи́х святі́йшеє Сло́во, ни́нішнєє моле́бноє приє́мши приноше́ніє, і на ну́жди на́ша призира́ющи, пода́ждь нам си́лу Твоєя́ благода́ті, упра́ви нас на путі́ спасе́нія і умоли́ ниспосла́ти нам ми́лости ще́дрия Си́на Твоєго́, Єму́ же хвалу́ ве́лію во умиле́нії возно́сим: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел с небесе́ по́слан бисть рещи́ Богоро́дице: Ра́дуйся! Ми же, земноро́днії, див'я́щеся воплоще́нію от Тебе́ Си́на Твоєго́ і Бо́га на́шего, дерза́єм воспіва́ти Тебі́ си́це:","Ра́дуйся, благода́тная Богоро́дице Ді́во;","ра́дуйся, преблагослове́нная в жена́х.","Ра́дуйся, я́ко Спа́са родила́ єси́ душ на́ших;","ра́дуйся, я́ко Свободи́теля яви́ла єси́ нам.","Ра́дуйся, небесе́ і землі́ Цари́це;","ра́дуйся, я́ко преви́шши єси́ вся́каго созда́нія.","Ра́дуйся, а́нгели на небесі́ чти́мая;","ра́дуйся, челові́ки на землі́ прославля́ємая.","Ра́дуйся, я́ко прише́дши ко Єлисаве́ті, Сама́ прорекла́ єси́: «Отни́ні ублажа́ть М'я всі ро́ди»;","ра́дуйся, я́ко воі́стину всі ро́ди до ни́ні Тя непреста́нно ублажа́ють.","Ра́дуйся, ві́рно Тя велича́ющим по́мощ ско́рую да́рующая;","ра́дуйся, чудотво́рними Свої́ми іко́нами, я́ко со́лнцем, світя́щая.","Ра́дуйся, Влади́чице, іко́ною Твоє́ю Остробра́мською благода́ть і ми́лость нам явля́ющая."]},{"h":"Кондак 1","ps":["Возбра́нной Воєво́ді і преди́вной Засту́пнице ро́да христия́нськаго, благоізво́лившей от святи́я Своєя́ іко́ни ізлива́ти нам струї́ благода́тних ісціле́ній, похва́льная воспису́єм Ті раби́ Твої́, Богоро́дице. Ти же, я́ко блага́я Засту́пниця чту́щих Тя, от вся́ких нас бід свободи́, да зове́м Ті:","Ра́дуйся, Влади́чице, іко́ною Твоє́ю Остробра́мською благода́ть і ми́лость нам явля́ющая."]},{"h":"Молитва","ps":["О, Пресвята́я Ді́во, Ма́ти Го́спода ви́шніх сил, Небесе́ і землі́ Цари́це і гра́да на́шего Ки́єва всемо́щная Засту́пнице!","Прийми́ хвале́бноє пі́ніє сіє́ от нас недосто́йних раб Твої́х, і вознеси́ моли́тви на́ша ко престо́лу Си́на Твоєго́ і Бо́га на́шего, да ми́лостив бу́деть нам, грі́шним, і да проба́вить бла́гость Свою́ чту́щим Тя і с ві́рою і любо́вію покланя́ющимся чудотво́рному о́бразу Твоєму́.","Ко кому́ бо возопії́м Влади́чице? Ко кому́ прибі́гнем в го́рестіх на́ших, а́ще не к Тебі́, Цари́це Небе́сная? Кто плач наш і воздиха́нія на́ша при́йметь, а́ще не Ти, Пренепоро́чная, Наде́ждо христия́н і прибі́жище нам грі́шним? Кто па́че Тебі́ в напа́стіх защити́ть? Тім же мо́лим Тя усе́рдно: покри́й Твої́м хода́тайством на́ша прегріше́нія, защити́ нас от враг ви́димих і неви́димих, ум'ягчи́ сердця́ злих челові́к, возстаю́щих на нас.","О Ма́ти Го́спода на́шего Творця́! Ти єси́ ко́рень ді́вства і неув'яда́ємий цвіт чистоти́. Прийми́ недосто́йную моли́тву на́шу і соблюди́ нас в чистоті́ душе́вній, сохрани́ нас от наві́та злих челові́к і от внеза́пния сме́рти, і да́руй нам пре́жде конця́ покая́ніє. Поми́луй нас в дневни́х часі́х і у́тренних і вече́рніх, і во вся́коє вре́м'я сохрани́ нас: стоя́щих, сідя́щих соблюди́, і на вся́ком путі́ ходя́щих, і в нощни́х часі́х спя́щих снабди́, покри́й і заступи́. На вся́ком мі́сті і на вся́коє вре́м'я бу́ди нам, Ма́ти Преблага́я, стіна́ необори́мая і заступле́ніє крі́пкоє. Ти храни́тельниця жи́зні всея́ нам яви́ся, Пречи́стая; Ти нас ізба́ви от бісо́во в час сме́рти; Ти і по сме́рті упокоє́ніє обрісти́ іспроси́ у Си́на Твоєго́ і Бо́га на́шего.","Ми же, грі́шнії, со упова́нієм моле́нія Тебі́ возно́сим і уми́льно вопіє́м: ра́дуйся, Благода́тная; Ра́дуйся, Обра́дованная; ра́дуйся, Преблагослове́нная; Госпо́дь с Тобо́ю, с Тобо́ю с на́ми. К Тебі́ прибіга́єм, я́ко к несомні́нній і ско́рой Засту́пниці на́шей, і Тебі́, я́ко всемогу́щей Помо́щнице, са́мі себе́ і друг дру́га і весь живо́т наш по Христе́ Бо́зі предає́м, Єму́ же подоба́єть вся́кая сла́ва, честь і поклоне́ніє со безнача́льним Єго́ Отце́м, со Пресвяти́м і благи́м і животворя́щим Єго́ Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Інша молитва","ps":["О Всеми́лостивая Госпоже́, Цари́це Богоро́дице, от всіх родо́в ізбра́нная і всі́ми ро́ди небе́сними ублажа́ємая! Воззри́ ми́лостиво на предстоя́щия пред свято́ю іко́ною Твоє́ю лю́ди сія́, усе́рдно моля́щіяся Тебі́, і сотвори́ предста́тельством Твої́м і заступле́нієм у Си́на Твоєго́ і Бо́га на́шего, да нікто́ же оти́деть от мі́ста сего́ тощ упова́нія своєго́ і посра́млен в наде́жді своє́й, но да при́йметь ки́йждо от Тебе́ вся по благо́му ізволе́нію се́рдця своєго́, по ну́жді і потре́бі своє́й, во спасе́ніє душі́ і во здра́віє ті́лу.","Найпа́че же осіни́ і огради́ покро́вом Твої́м, Милосе́рдная Ма́ти, Це́рков Твою́ Святу́ю, ви́шнім Твої́м благослове́нієм архієре́ї на́ші правосла́вния укріпи́, ми́ром огради́, і Святі́й Твоє́й Це́ркві ці́лих, здра́вих, честни́х, долгоде́нствующих пра́во пра́в'ящих сло́во Своєя́ і́стини да́руй, от всіх же ви́димих і неви́димих враг, со всі́ми правосла́вними христия́ни, ми́лостиво ізба́ви, і во правосла́вії і тве́рдій ві́рі до конця́ віко́в непосту́пно і неізмі́нно сохрани́. Призира́й благосе́рдієм, Всепі́тая, і призрі́нієм ми́лостиваго Твоєго́ заступле́нія на всю страну́ на́шу, гра́ди на́ша і град сей [іли́: храм сей, іли́: і духо́вний вертогра́д, зді су́щий], і на сія́ бога́тия Твоя́ ми́лості неоску́дно ізлива́й. Ти бо єси́ всеси́льная Помо́щниця і Засту́пниця всіх нас. Приклони́ся к моли́твам і всіх раб Твої́х, ко святі́й іко́ні Твоє́й зді притека́ющих, усли́ши воздиха́нія і гла́си, і́миже раби́ Твої́ мо́ляться во святі́м мі́сті сем.","А́ще же і інові́рний, і іноплеме́нник, зді преходя́, помо́литься, усли́ши, чадолюби́вая Госпоже́, і сего́ человіколю́бне і ми́лостивно соді́лай, я́же к по́мощі єму́ і ко спасе́нію. Ожесточе́нния же і разсі́янния се́рдці свої́ми во страна́х на́ших на путь і́стини наста́ви: отпа́дшия от благочести́вия ві́ри обрати́ і па́ки святі́й Правосла́вній Собо́рній і Апо́стольстій Це́ркві сопричти́. В домі́х люде́й Твої́х і во бра́тії святи́я оби́телі сея́ мир огради́ і соблюди́, в ю́них бра́тство і смиренному́дріє утверди́, ста́рость поддержи́, о́троки наста́ви, во во́зрасті соверше́ннім су́щия умудри́, си́рия і вдови́ці заступи́, утісне́нния і в ско́рбіх су́щия уті́ши і охрани́, младе́нці воспита́й, боля́щия уврачу́й, пліне́нния свободи́, огражда́ющи ни при́сно от вся́каго зла бла́гостію Твоє́ю, і уті́ши ми́лостивним Твої́м посіще́нієм і вся благоде́ющия нам. Да́руй же, Блага́я, землі́ плодоно́сіє, возду́ху благорастворе́ніє і вся, я́же на по́льзу на́шу, да́ри благовре́менния і благопотре́бния, всемо́щним Твої́м предста́тельством пред Всесвято́ю Живонача́льною Тро́йцею.","Пре́жде отше́дшия отці́ і ма́тері, бра́тію і сестри́ на́ша, і вся от літ дре́вніх ко святі́й іко́ні Твоє́й сей припа́давшия, упоко́й в селе́ніїх святи́х, в мі́сті зла́чні, в мі́сті поко́йні, іді́же ність печа́ль і воздиха́ніє. Єгда́ же приспі́єть і на́ше от житія́ сего́ отше́ствіє і к ві́чной жи́зні преселе́ніє, предста́ни нам, Преблагослове́нная Ді́во, і да́руй христия́нськую кончи́ну житія́ на́шего, безболі́зненну, непости́дну, ми́рну і Святи́х Та́їн прича́стну, да і в бу́дущем ві́ці сподо́бимся всі, ку́пно со всі́ми святи́ми, безконе́чния блаже́нния жи́зні во Ца́рствії возлю́бленнаго Си́на Твоєго́, Го́спода і Бо́га на́шего Ісу́са Христа́, Єму́же подоба́єть сла́ва, честь і поклоне́ніє со Отце́м і Святи́м Ду́хом, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["К Богоро́диці прилі́жно ни́ні притеце́м, грі́шнії і смире́ннії, і припаде́м, в покая́нії зову́ще із глубини́ душі́: Влади́чице, помози́, на ни милосе́рдовавши, потщи́ся, погиба́єм от мно́жества прегріше́ній, не отврати́ Твоя́ раби́ тщи, Тя бо і єди́ну наде́жду і́мами."]},{"h":"Кондак, глас 6","ps":["Предста́тельство христия́н непости́дноє, хода́тайство ко Творцю́ непрело́жноє, не пре́зри грі́шних моле́ній гла́си, но предвари́, я́ко Блага́я, на по́мощ нас, ві́рно зову́щих Ті, ускори́ на моли́тву, і потщи́ся на умоле́ніє, предста́тельствующи при́сно, Богоро́дице, чту́щих Тя."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Троєручиця»","e":"Akathist to the Theotokos before her icon “Three-handed”","secs":[{"h":"Кондак 1","ps":["Возбра́нной Воєво́ді, Богообра́дованной Присноді́ві Богоро́дице, посети́вшей го́ру Афо́нськую явле́нієм Троєру́чния іко́ни Своєя́ і мно́гія ми́лости є́ю да́рующей ро́ду христия́нському, похва́льноє возглаша́єм ни́ні пі́ніє; Ти же, о Богома́ти, я́ко іму́щая держа́ву непобіди́мую і Ма́тернєє о нас попече́ніє, предвари́ на по́мощ к нам і от вся́ких бід ізба́ви зову́щих Ті:","Ра́дуйся, Помо́щнице на́ша, Троєру́чною іко́ною Твоє́ю нам помога́ющая."]},{"h":"Ікос 1","ps":["А́нгел земни́й і челові́к небе́сний преподо́бний Іоа́нн Дамаски́н от любве́ те́плия к Тебі́, Богома́ти Влади́чице, іко́ну Твою́ святу́ю сооруди́ти потща́ся і сію́ в ке́ллії своє́й благогові́йно поста́вив, пред не́ю си́це Тебі́ в моли́твах усе́рдних глаго́лаше:","Ра́дуйся, Ра́дость ві́чную, Спаси́теля ми́ру ро́ждшая;","ра́дуйся, всегуби́тельнаго а́да си́лу Рождество́м Твої́м попра́вшая.","Ра́дуйся, проро́чеських глаго́лов ісполне́ніє прине́сшая;","ра́дуйся Ада́ма і Є́ви преступле́ніє загла́дившая.","Ра́дуйся, Єди́наго от Тро́йці на руку́ Твоє́ю нетру́дно носи́вшая;","ра́дуйся, огнь Божества́ неопа́льно во чре́ві Твоє́м вмісти́вшая.","Ра́дуйся, Помо́щнице на́ша, Троєру́чною іко́ною Твоє́ю нам помога́ющая."]},{"h":"Кондак 2","ps":["Ви́дящи преподо́бний Іоа́нн Дамаски́н десни́цю свою́, мно́го писа́вшую в защи́ту че́сти і поклоне́нія святи́х іко́н, по наві́ту царя́ іконобо́рця неми́лостиво отсі́ченную, іспроси́ ю от неві́рнаго мучи́теля і, приложи́в к усе́ченному єя́ соста́ву, пред честно́ю іко́ною Твоє́ю, Пречи́стая Ді́во, сле́зно моля́шеся к Тебі́, о є́же ісціли́тися єй. Ти же, всеблага́я і всемо́щная ро́да на́шего Засту́пнице, моли́тву єго́ ско́ро усли́шала єси́ і, предста́в єму́ во сні, ісціле́ніє усе́ченной руці́ єго́ дарова́ла єси́, да благода́рственно поє́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум челові́чеський не мо́жеть пости́гнути си́лу ісціле́ній благода́тних, іко́ною Твоє́ю, о Богома́ти, чуде́сно явля́ємих, не мо́жеть із'ясни́ти і чу́до ве́ліє, ка́ко отсі́ченная десни́ця преподо́бнаго во єди́ну нощ ці́ла і здра́ва обрі́теся, на не́йже то́кмо червле́нний знак би́вшия я́зви оста́влен бисть Враче́бницею благо́ю, сли́шащею от нас сія́ похвали́:","Ра́дуйся, ско́ро явля́ющаяся Уті́шительнице скорб'я́щих душ;","ра́дуйся, радостотво́рная Посіти́тельнице болі́знующих серде́ць.","Ра́дуйся, безнаде́жних страда́льцев наде́ждою ісціле́нія ободря́ющая;","ра́дуйся, врачи́ оста́вленних болі́знующих на Свої́ ру́ці приє́млющая.","Ра́дуйся, усі́ченную десни́цю Бо́жия ізбра́нника ці́лу і здра́ву вишеєсте́ственно соді́лавшая;","ра́дуйся, я́ко нічто́же невозмо́жно Тебі́, милосе́рдая Предста́тельнице, нам всегда́ заступле́ніє показу́ющая.","Ра́дуйся, Помо́щнице на́ша, Троєру́чною іко́ною Твоє́ю нам помога́ющая."]},{"h":"Кондак 3","ps":["Си́лу десни́ці Всеви́шняго в ісціле́нії усі́ченния десни́ці своєя́ позна́в богоглаго́ливий Іоа́нн, пі́сньми кра́сними воспі́ Тя, Влади́чице Всеблага́я, і подо́біє усі́ченния руки́ своєя́ приложи́ к ціле́бному Твоєму́ о́бразу ра́ди па́м'яті всегда́шнія о вели́ком чудеси́. Посему́ ни́ні ви́дима єсть і імену́ється сія́ свята́я іко́на Твоя́ Троєру́чиця, трем'я́ рука́ми, на ней опи́санними, проявля́ющая та́їнство Святи́я Тро́йці, чудеси́ же, от нея́ бива́ющими, всіх приводя́щая хвале́бно взива́ти ко Го́споду: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яй ве́лію ре́вность по Бо́зі, духоно́сний піснопи́сець святи́я Це́ркве і боже́ственний сла́витель єя́, сла́дкий преподо́бний Іоа́нн, хвале́бними пі́нії до конця́ жи́зні своєя́ прославля́ше Твою́ к нему́ ди́вную ми́лость, Богороди́тельнице, в па́м'ять же би́вшаго чудесе́ плать, і́мже усече́нная рука́ єго́ обве́рнута бі, на главі́ своє́й ноша́ше, іко́ну же Твою́ многоціле́бную, я́ко наслі́діє бога́тоє, святі́й Ла́вре преподо́бнаго Са́вви Освяще́ннаго по себі́ оста́ви, да всі ві́рнії зову́ть к ізображе́нной на ней Ціли́тельнице душ і тіле́с си́це:","Ра́дуйся, враго́в святи́я правосла́вния ві́ри крі́пкая Побо́рнице;","ра́дуйся, пропові́дников єва́нгельськаго уче́нія Покрови́тельнице.","Ра́дуйся, благочести́вих христия́н защи́то і похвало́;","ра́дуйся, боголюби́вих і́ноков утіше́ніє.","Ра́дуйся, веду́щим брань проти́ву ми́ра, пло́ті і дия́вола до́брая Споспі́шнице;","ра́дуйся, ревну́ющим о цілому́дрії і чистоті́ ізря́дная Посо́бнице.","Ра́дуйся, Помо́щнице на́ша, Троєру́чною іко́ною Твоє́ю нам помога́ющая."]},{"h":"Кондак 4","ps":["Бу́ря недоумі́нія смуща́єть мі ум, ка́ко возмогу́ недосто́йними усти́ воспі́ти сла́ву Твою́, Пречи́стая Ді́во, ю́же во іко́ні Твоє́й святі́й яви́ла єси́, дарова́вши ю нам в по́мощ і защи́ту от враг ви́димих і неви́димих. Ті́мже, велича́я неісче́тния ми́лості Твоя́ к ро́ду христия́нському, іспові́дую чудеса́ Твоя́ і смиренному́дренно пою́ Вседержи́телю: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше і́ноці святи́я Ла́ври Са́вви Освяще́ннаго о вели́ких доброді́теліх прише́дшаго в Ла́вру на поклоне́ніє первосвяти́теля се́рбськаго Са́вви, по внуше́нію Твоєму́, Богома́ти, дарова́ша єму́ на благослове́ніє святу́ю іко́ну Твою́ Троєру́чицю, ю́же он со благогові́нієм, я́ко дар многоці́нен, в страну́ Се́рбськую принесе́, поуча́я па́ству свою́ зва́ти Тебі́:","Ра́дуйся, от восто́ка і до за́пада си́лу всемогу́щества Христо́ва іко́ною Твоє́ю возвіща́ющая;","ра́дуйся, болі́зні душе́вния і тіле́сния іко́ною Твоє́ю ско́ро врачу́ющая.","Ра́дуйся, Се́рбстій страні́ іко́ну Твою́ в зало́г благоволе́нія дарова́вшая;","ра́дуйся, чудеси́ Твої́ми Правосла́віє в ней крі́пко утверди́вшая.","Ра́дуйся, Симео́на Мироточи́ваго о́бласть благода́тно посіти́вшая;","ра́дуйся, Са́вви первопресто́льнаго па́ству Ма́терним покро́вом Твої́м приосени́вшая.","Ра́дуйся, Помо́щнице на́ша, Троєру́чною іко́ною Твоє́ю нам помога́ющая."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ подо́бна яви́ся іко́на Твоя́, Богороди́тельнице, по во́лі Твоє́й святі́й на осля́ поста́вленная і отпуще́нная із Се́рбії: осля́ти, ники́мже води́му, принесе́ся їм на го́ру Афо́нськую ко врата́м оби́телі Хиланда́рськия, ю́же я́ко дар небе́сний восприї́мше і́ноці, поста́виша в олтари́ собо́рния це́ркве оби́телі, зову́ще во умиле́нії глубо́цім благи́х Пода́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше і́ноці хиланда́рстії Твоє́ к ним благоволе́ніє, Преблагослове́нная Ді́во, в чуде́снім прише́ствії к ним святи́я іко́ни Твоєя́ Троєру́чиці явле́нноє, с ра́достію і любо́вію єй покланя́хуся, цілу́юще і пі́сненно возглаша́юще Ті благохвале́нія сицева́я:","Ра́дуйся, Путеводи́тельнице подви́жников благоче́стія ко го́рнему Сіо́ну;","ра́дуйся, пустиннолюби́вих і́ноков приводя́щая к небе́сному Ієрусали́му.","Ра́дуйся, безслове́сноє осля́ во́лі Твоє́й святі́й чуде́сно покори́вшая;","ра́дуйся, на осля́ти іко́ну Твою́ благода́тную от Се́рбії на Афо́н ди́вно прине́сшая.","Ра́дуйся, пусти́ню Афо́на благоуха́нієм святи́ні іспо́лнившая;","ра́дуйся, Хиланда́рськую оби́тель благоволе́нієм Твої́м облагода́тствовавшая.","Ра́дуйся, Помо́щнице на́ша, Троєру́чною іко́ною Твоє́ю нам помога́ющая."]},{"h":"Кондак 6","ps":["Пропові́дуєть оби́тель Хиланда́рськая на Афо́ні бога́тство ми́лостей і щедро́т Твої́х, Богоро́дице Ді́во, і сві́тло красу́ється, іму́щи святу́ю іко́ну Твою́ Троєру́чицю во ігу́мена себі́, і́бо такова́я бисть во́ля Твоя́, є́же пребива́ти іко́ні Твоє́й та́мо на ігу́мена мі́сті во хра́мі Бо́жиєм і в душа́х бра́тій, от Тебе́ єди́ния благослове́ніє на вся́коє послуша́ніє приє́млющих і хвале́бно зову́щих та́ко благоволи́вшему о них Творцю́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возвісти́ла єси́ во́лю Твою́, Богома́ти, і́ноком хиланда́рським, разногла́сієм во ізбра́нії ігу́мена смуще́нним, чуде́сно поста́вивши святу́ю іко́ну Твою́ на ігу́менстем мі́сті во хра́мі Бо́жиєм і откри́вши єди́ному от них во виді́нії, я́ко Сама́ Ти хо́щеши пребива́ти настоя́тельствующею в оби́телі їх іко́ною Твоє́ю честно́ю, і да про́чеє не ізбира́ють себі́ ігу́мена. Они́ же во умиле́нії душ і серде́ць, обра́дованнії возопи́ша к Тебі́:","Ра́дуйся, і́ноков благоподвиза́ющихся ізві́стная і всемо́щная Покрови́тельнице;","ра́дуйся, к Си́ну Твоєму́ і Бо́гу те́плая о них Предста́тельнице.","Ра́дуйся, жезл ігу́менський в Хиланда́рстей оби́телі неви́димо приє́мшая;","ра́дуйся, оби́тель сію́ досе́лі ці́лу і благоустро́єну сохраня́ющая.","Ра́дуйся, стра́хом і благогові́нієм сердца́ бра́тій, благослове́ніє от іко́ни Твоєя́ приє́млющих, ісполня́ющая;","ра́дуйся, неблагогове́йния і де́рзостния гро́зно наказу́ющая.","Ра́дуйся, Помо́щнице на́ша, Троєру́чною іко́ною Твоє́ю нам помога́ющая."]},{"h":"Кондак 7","ps":["Хотя́ соді́лати не то́кмо Афо́н, но і вся іни́я страни́ правосла́вния прича́стними благода́ті вели́ких чуде́с, іко́ною Твоє́ю Троєру́чною ізлива́ємих і бива́ємих, Пречи́стая Влади́чице, ту́ю во всіх граді́х, ве́сіх, це́рквах і оби́теліх і́ночеських распространи́ла і ди́вними чудеси́ просла́вила єси́. Ті́мже вся ві́рная ча́да святу́ю іко́ну Твою́ Троєру́чицю любо́вію честву́ють і на ней вку́пі с Тобо́ю ізображе́нному Христу́ усе́рдно зову́ть: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вно явля́єши, Преблагослове́нная Ді́во, ми́лости ві́рним лю́дем і свято́ю іко́ною Твоє́ю Троєру́чицею пресла́вния чудеса́ содіва́єши си́лою благода́ті Христо́ви: сліпи́я просвіща́єши, разсла́бленния укріпля́єши, неду́жния врачу́єши і всім прибега́ющим к ціле́бному Твоєму́ о́бразу ско́рую по́мощ Твою́ при́сно явля́єши, подвиза́я зва́ти к Тебі́:","Ра́дуйся, Святу́ю го́ру Афо́нськую в жре́бій Себе́ ізбра́вшая;","ра́дуйся, і вся страни́ правосла́вния покро́вом ми́лости Твоєя́ осіни́вшая.","Ра́дуйся, Хиланда́рськия оби́телі Настоя́тельниці неізмі́нная;","ра́дуйся, мно́гих міст і пу́стинь сокро́вище ісціле́ній неоску́дноє.","Ра́дуйся, на Афо́ні, в Россі́ї, Се́рбії і іни́х страна́х іко́ною Твоє́ю пресла́вно чудоде́йствующая;","ра́дуйся, лю́б'ящия і чту́щия Тя от вся́ких бід ізбавля́ющая.","Ра́дуйся, Помо́щнице на́ша, Троєру́чною іко́ною Твоє́ю нам помога́ющая."]},{"h":"Кондак 8","ps":["Стра́нно єсть ви́діти і́ноки хиланда́рськия, к іко́ні Твоє́й, я́ко к ігу́мену приходя́щия і от нея́ благослове́нія на послуша́нія своя́ приє́млющия. Но, о Всеблага́я, я́коже приє́млеши їх ми́лостивно і благословля́єши, та́ко і нас, недосто́йних, не лиши́ Ма́терняго Твоєго́ милосе́рдія і попече́нія, прийми́ благоутро́бно моли́тви на́ша пред свято́ю іко́ною Твоє́ю возноси́мия, осіни́ нас благослове́нієм Твої́м благода́тним, ізба́ви от вся́ких бід і скорбе́й і научи́ богоуго́дно пі́ти Трієди́ному Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь мир преіспо́лнен, я́ко звізда́ми богосві́тлими, чудотво́рними іко́нами Твої́ми, Богоро́дице Ді́во, в ни́хже, я́ко денни́ця лучеза́рная, іко́на Твоя́ Троєру́чиця преди́вними чудеси́ благода́тно сія́єть і согріва́єть хла́дния сердця́ на́ша зна́меньми Твоєго́ к нам ми́лостиваго призрі́нія. Сего́ ра́ди честву́єм пречи́стаго ли́ка Твоєго́ свято́є ізображе́ніє і Тебі́ пред ним вопіє́м:","Ра́дуйся, богообра́дованная і пренепоро́чная Присноді́во;","ра́дуйся, єди́на чи́стая і благослове́нная в жена́х.","Ра́дуйся, нетлі́нная і неіскусобра́чная А́гнця і Па́стиря Ма́ти;","ра́дуйся, прекра́сная і світоно́сная пала́то святи́х святі́йшаго Сло́ва.","Ра́дуйся, кри́не білосні́жний і благово́нний ді́вства і чистоти́;","ра́дуйся, Цари́це і Влади́чице небесе́ і землі́.","Ра́дуйся, Помо́щнице на́ша, Троєру́чною іко́ною Твоє́ю нам помога́ющая."]},{"h":"Кондак 9","ps":["Всяк во́зраст ві́рних благопо́льзується Твої́м Ма́тернім попече́нієм, всеблага́я Влади́чице: младе́нці милосе́рдно окормля́єши, о́троки неви́димо руково́дствуєши, му́жи во благоче́стії утвержда́єши, ста́рці в не́мощіх укріпля́єши, всім же вся блага́я і душеполе́зная да́руєши всеси́льним хода́тайством Твої́м у Престо́ла Пресвяти́я Тро́йці, Є́йже благода́рно поє́м: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії челові́честії не мо́гуть досто́йно восхвали́ти Тя, Богоро́дице, честні́йшую херуви́м і сла́внійшую серафи́м, ро́ждшую Єди́наго от Тро́йці Христа́ Жизнода́вця. Ми же, любо́вію к Тебі́ воодушевле́ннії, смиренному́дренно дерза́єм приноси́ти Тебі́ пі́сні такови́я:","Ра́дуйся, держа́вная Засту́пнице ро́да христия́нськаго;","ра́дуйся, благосе́рдая Ма́ти всіх скорб'я́щих і обремене́нних.","Ра́дуйся, кро́тким сія́нієм Твої́м мрак гріхо́в і страсте́й на́ших разгоня́ющая;","ра́дуйся, на стезі́ покая́нія нас прему́дро наставля́ющая.","Ра́дуйся, в гро́зний час сме́рти всім нам крі́пкая Защи́тнице;","ра́дуйся, до́браго отві́та нам пред Судіє́ю пра́ведним усе́рдная Хода́тайце.","Ра́дуйся, Помо́щнице на́ша, Троєру́чною іко́ною Твоє́ю нам помога́ющая."]},{"h":"Кондак 10","ps":["Спасе́нія зало́г дарова́ся нам свята́я і всечестна́я іко́на Твоя́, Богороди́тельнице Ді́во, і́бо, я́коже дре́вле прорекла́ єси́ боже́ственному євангели́сту Луці́, с не́ю і дони́ні си́ла Твоя́ благода́тно пребива́єть, чудеси́ пресла́вними ві́ру в нас утвержда́єть, неду́жния безме́здно врачу́єть і на путь спасе́нія ду́ші на́ша приво́дить, да зове́м просла́вльшему і́м'я Твоє́ во вселе́нній Царю́ небесе́ і землі́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ ді́вам і лико́м і́ночеським, Богоневі́стная Ді́во, і всім усе́рдно к Тебі́ прибега́ющим, іко́ну же Твою́ святу́ю благогові́йно честву́ющим, і́бо сію́ дарова́ нам благи́х пода́тель Госпо́дь в по́мощ і врачевство́ неду́гом душе́вним і тіле́сним і сим внуша́єть пі́ти Тебі́:","Ра́дуйся, до́брая Младопита́тельнице дів і безма́терніх сиро́т;","ра́дуйся, і́ноков і і́нокинь благоскорб'я́щих Предводи́тельнице к награ́дам небе́сним.","Ра́дуйся, в у́зах і темни́ці сідя́щих посіща́ющая утіше́нієм благода́тним;","ра́дуйся, благослове́ніє домо́в і супру́жеств благочести́вих.","Ра́дуйся, ю́них наста́внице цілому́дрія і воздержа́нія;","ра́дуйся, ста́рцев приводя́щая к благо́му житію́ і ми́рной кончи́ні.","Ра́дуйся, Помо́щнице на́ша, Троєру́чною іко́ною Твоє́ю нам помога́ющая."]},{"h":"Кондак 11","ps":["Пі́ніє моле́бноє на́ше, Тебі́ пред пречи́стим о́бразом Твої́м с ві́рою і любо́вію возноси́моє, ми́лостивно усли́ши, Госпоже́ Всеми́лостивая, і сохрани́ нас от тлітво́рних уче́ній, неві́рія і суєві́рія, і́миже наві́тується в нас святооте́чеськая правосла́вная ві́ра, ізба́ви нас от лука́вих совраще́ній, сохрани́ нас і оте́чество на́ше от вся́ких крамо́л і от вся́ких нестроє́ній і злих развраще́ній, врага́ми ві́ри і оте́чества на́шего воздвиза́ємих, і сподо́би в любві́ і єдиноми́слії со всі́ми ві́рними ча́дами святи́я Христо́ви Це́ркве богоприя́тно пі́ти Созда́телю на́шему: Аллилу́я."]},{"h":"Ікос 11","ps":["Светоприє́млемая свіща́ іко́на Твоя́ свята́я, Богоро́дице Ді́во, мир весь сія́нієм чуде́с просвіща́єть, сердця́ же на́ша любо́вію воспламеня́єть к Тебі́, Пречи́стій і Преблагослове́нній Ма́тері Сладча́йшаго Го́спода на́шего Ісу́са Христа́, дарова́вшаго нам Тебі́ в покро́в і защи́ту проти́ву по́лчищ сатани́нських, і́же боя́ться і трепе́щуть са́маго і́мене Твоєго́, ве́дающе си́лу Твою́, ю́же велича́єм і Тебі́ зове́м:","Ра́дуйся, враги́ на́ша ви́димия і неви́димия прему́дро запина́ющая;","ра́дуйся, хули́телей святи́я правосла́вния ві́ри неви́димо кара́ющая.","Ра́дуйся, духо́в зло́би от нас держа́вно отгоня́ющая;","ра́дуйся, преовладе́ти їм над на́ми не попуска́ющая.","Ра́дуйся, любо́вію к Бо́гу і бли́жнім нас воодушевля́ющая;","ра́дуйся, вся блага́я проше́нія на́ша ско́ро ісполня́ющая.","Ра́дуйся, Помо́щнице на́ша, Троєру́чною іко́ною Твоє́ю нам помога́ющая."]},{"h":"Кондак 12","ps":["Благода́ть сви́ше дарова́ся святі́й іко́ні Твоє́й Троєру́чице, Влади́чице Преблага́я: скорб'я́щия утіша́ти, боля́щия ісціля́ти, сліпи́я просвіща́ти, разсла́бленния укріпля́ти, ві́рния во благоче́стії утвержда́ти, неві́рния к позна́нію і́стини приводи́ти, зна́меньми і чудеси́ от нея́ бива́ємими, я́же воі́стину превосхо́дять разумі́ніє челові́чеськоє і то́кмо ві́рою постига́ються, приводя́ще ві́рния ду́ші к немо́лчному славосло́вію Творця́ богокра́сною пі́снію: Аллилу́я."]},{"h":"Ікос 12","ps":["Поє́м чудеса́ Твоя́, благода́тная Богороди́тельнице, не таї́м щедро́т Твої́х, іспові́дуєм благодія́нія Твоя́, прославля́єм неісче́тную ми́лость Твою́ к ро́ду христия́нському, ю́же ві́дять всі конці́ землі́, і́бо от восто́ка до за́пада хва́льно і́м'я Твоє́ свято́є, благословля́ємоє от всіх родо́в і в моли́твах призива́ємоє во всіх страна́х. Тебе́ у́бо, си́це просла́вленній і превознесе́нней Си́ном Твої́м і Бо́гом, і ми хвале́бно вопіє́м:","Ра́дуйся, ти́хоє приста́нище пла́вающих в пучи́ні жите́йськаго мо́ря;","ра́дуйся, треволне́ніє страсте́й умиротворя́ющая Свої́м сердобо́льним уча́стієм.","Ра́дуйся, во уни́ніє і отча́яніє впа́дших под'є́млющая наде́ждою спасе́нія;","ра́дуйся, сомне́ніями во ві́рі коле́блющихся вразумля́ющая зна́меньми і чудеси́.","Ра́дуйся, в оби́теліх і́ночеських подвиза́ющимся богоуго́дно Пода́тельнице блаже́ннаго упокоє́нія;","ра́дуйся, і в ми́рі благоче́стно живу́щих не лиша́ющая Твоєго́ заступле́нія.","Ра́дуйся, Помо́щнице на́ша, Троєру́чною іко́ною Твоє́ю нам помога́ющая."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти Сладча́йшаго Іскупи́теля на́шего Го́спода Ісу́са Христа́! Воньми́ гла́су моле́бному, Тебі́ пред свято́ю іко́ною Твоє́ю на́ми смире́нно возноси́мому, і Ма́тернею моли́твою Твоє́ю к ро́ждшемуся от Тебе́ святи́х святі́йшему Сло́ву от вся́кия ізба́ви напа́сти і ві́чния му́ки всіх і́м'я Твоє́ моли́твенно призива́ющих і о Тебі́ благода́рно зову́щих Бо́гу: Аллилу́я","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел земни́й і челові́к небе́сний преподо́бний Іоа́нн Дамаски́н от любве́ те́плия к Тебі́, Богома́ти Влади́чице, іко́ну Твою́ святу́ю сооруди́ти потща́ся і сію́ в ке́ллії своє́й благогові́йно поста́вив, пред не́ю си́це Тебі́ в моли́твах усе́рдних глаго́лаше:","Ра́дуйся, Ра́дость ві́чную, Спаси́теля ми́ру ро́ждшая;","ра́дуйся, всегуби́тельнаго а́да си́лу Рождество́м Твої́м попра́вшая.","Ра́дуйся, проро́чеських глаго́лов ісполне́ніє прине́сшая;","ра́дуйся Ада́ма і Є́ви преступле́ніє загла́дившая.","Ра́дуйся, Єди́наго от Тро́йці на руку́ Твоє́ю нетру́дно носи́вшая;","ра́дуйся, огнь Божества́ неопа́льно во чре́ві Твоє́м вмісти́вшая.","Ра́дуйся, Помо́щнице на́ша, Троєру́чною іко́ною Твоє́ю нам помога́ющая."]},{"h":"Кондак 1","ps":["Возбра́нной Воєво́ді, Богообра́дованной Присноді́ві Богоро́дице, посети́вшей го́ру Афо́нськую явле́нієм Троєру́чния іко́ни Своєя́ і мно́гія ми́лости є́ю да́рующей ро́ду христия́нському, похва́льноє возглаша́єм ни́ні пі́ніє; Ти же, о Богома́ти, я́ко іму́щая держа́ву непобіди́мую і Ма́тернєє о нас попече́ніє, предвари́ на по́мощ к нам і от вся́ких бід ізба́ви зову́щих Ті:","Ра́дуйся, Помо́щнице на́ша, Троєру́чною іко́ною Твоє́ю нам помога́ющая."]},{"h":"Молитва перша","ps":["О Пресвята́я і Преблагослове́нная Ді́во Богоро́дице Марі́є! Припа́даєм і покланя́ємся Тебі́ пред свято́ю Троєру́чною іко́ною Твоє́ю, воспомина́юще пресла́вноє чу́до Твоє́ ісціле́нієм усі́ченния десни́ці преподо́бнаго Іоа́нна Дамаски́на, от іко́ни сея́ явле́нноє, єго́же зна́меніє дони́ні ви́димо єсть на ней, во о́бразі тре́тія руки́, к ізображе́нію Твоєму́ приложе́нния. Мо́лимся Ті і про́сим Тя, Всеблагу́ю і Всеще́друю ро́да на́шего Засту́пницю: усли́ши нас, моля́щих Тебі́, і я́коже блаже́ннаго Іоа́нна, в ско́рбі і болі́зні к Тебі́ возопи́вшаго, усли́шала єси́, та́ко і нас не пре́зри, скорб'я́щих і болі́знующих ра́нами страсте́й многоразли́чних і к Тебі́ от душі́ сокруше́нния і смире́нния усе́рдно прибіга́ющих. Ти зри́ши, Госпоже́ Всеми́лостивая, не́мощі на́ша, озлобле́ніє на́ше, ну́жду, потре́бу на́шу в Твоє́й по́мощі і заступле́нії, я́ко отвсю́ду враги́ окруже́ні єсьми́, і ність помога́ющаго, ніже́ заступа́ющаго, а́ще не Ти умилосе́рдишися о нас, Влади́чице. Єй, мо́лим Ті ся, воньми́ гла́су болі́зненному на́шему і помози́ нам святооте́чеськую Правосла́вную ві́ру до конця́ дній на́ших непоро́чно сохрани́ти, во всіх за́повідіх Госпо́дніх неукло́нно ходи́ти, покая́ніє і́стинноє о грісі́х на́ших всегда́ Бо́гу приноси́ти і сподо́битися ми́рния христия́нськия кончи́ни і до́браго отві́та на Стра́шнім Суді́ Си́на Твоєго́ і Бо́га на́шего, Єго́же умоли́ за нас Ма́тернею моли́твою Твоє́ю, да не осу́дить нас по беззако́нієм на́шим, но да поми́луєть нас по вели́цій і неізрече́нній ми́лості Своє́й. О Всеблага́я! Усли́ши нас і не лиши́ нас по́мощі Твоєя́ держа́вния, да, Тобо́ю спасе́ніє получи́вше, воспоє́м і просла́вим Тя на землі́ живи́х і ро́ждшагося от Тебе́ Іскупи́теля на́шего, Го́спода Ісу́са Христа́, Єму́же подоба́єть сла́ва і держа́ва, честь і поклоне́ніє, ку́пно со Отце́м і Святи́м Ду́хом, всегда́, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О Пресвята́я Госпоже́ Влади́чице Богоро́дице, ве́ліє чу́до свято́му Іоа́нну Дамаски́ну яви́вшая, я́ко ві́ру і́стинную і наде́жду несумні́нную показа́вшему! Усли́ши нас, грі́шних, пред чудотво́рною Твоє́ю іко́ною усе́рдно моля́щихся і прося́щих Твоєя́ по́мощі: не отри́ни моле́нія сего́ мно́гих ра́ди прегріше́ній на́ших, но, я́ко Ма́ти милосе́рдія і щедро́т, ізба́ви нас от болі́зней, скорбе́й і печа́лей, прости́ соді́янния на́ми гріхи́, іспо́лни ра́дости і весе́лія всіх, чту́щих святу́ю іко́ну Твою́, да ра́достно воспоє́м і любо́вію просла́вим і́м'я Твоє́, я́ко Ти єси́ от всіх родо́в ізбра́нная і благослове́нная во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Днесь всеми́рная ра́дость возсія́ нам ве́лія: / дарова́ся святі́й Горі́ Афо́нстій / цільбоно́сная Твоя́, Влади́чице Богоро́дице, іко́на, / со ізображе́нієм тричи́сленно і неразді́льно пречи́стих рук Твої́х, / в прославле́ніє Святи́я Тро́йці, / созива́єши бо ві́рних і моля́щихся Тебі́ о сем позна́ти, / я́ко двіма́ Си́на і Го́спода держи́ши, / тре́тію же яви́ на прибі́жище і покро́в чту́щих Тя, / от вся́ких напа́стей і бід ізбавля́ти, / да всі, притека́ющії к Тебі́ ві́рою приє́млють неоску́дно от всіх зол свобожде́ніє, / от враго́в защище́ніє, / сего́ ра́ди і ми вку́пі с Афо́ном вопіє́м: // ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю."]},{"h":"Кондак, глас 8","ps":["Днесь весе́лоє наста́ ни́ні Твоє́ торжество́, Богома́ти Пречи́стая, / всі ві́рнії іспо́лнишася ра́дости і весе́лія, / я́ко сподо́бльшеся ізря́дно воспі́ти / преди́вноє явле́ніє честна́го о́браза Твоєго́ / і ро́ждшагося із Тебе́ Младе́нця, і́стинна же Бо́га, / Єго́же двіма́ рука́ма об'є́млеши, / і тре́тією от напа́стей і бід нас ізима́єши, // і ізбавля́єши от всіх зол і обстоя́ній."]},{"h":"Величання","ps":["Велича́єм Тя, / Пренепоро́чная Ді́во, / і чтим чудеса́ о́браза свята́го Твоєго́, / трех пречи́стих рук Твої́х явле́ніє // в сла́ву Божества́, в Тро́йці Бо́га на́шего."]},{"h":"Інше величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / і чтим тричи́сленноє ізображе́ніє пречи́стих рук Твої́х, / Ти бо двіма́ Си́на і Го́спода держи́ши, // тре́тією от напа́стей і бід нас ізбавля́єши."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Мінська»","e":"Akathist to the Theotokos before her icon “Minsk”","secs":[{"h":"Кондак 1","ps":["Ізбра́нная от всіх родо́в, Влади́чице Ді́во Богоро́дице, ни́ні, припа́дающе к чудотво́рному о́бразу Твоєму́, хвале́бноє пі́ніє і благодаре́ніє прино́сим Ті:","Ра́дуйся, Пренепоро́чная Отрокови́це, гра́да на́шего Небе́сная Засту́пнице."]},{"h":"Ікос 1","ps":["А́нгельськія си́ли, прилі́жно моля́щіїся і благогові́йно служа́щії Ті, Пресвята́я Ді́во, от літ дре́вніх на ге́рбі Богоспаса́ємаго гра́да Ми́нська ізображе́ні би́ша во свиді́тельство чу́днаго Твоєго́ о нас попече́нія. Ми же земноро́днії, дерза́я подража́ти пі́сні а́нгельстій, благода́рственно Тебі́ поє́м:","Ра́дуйся, о зача́тії Си́на от Ду́ха Свята́го Арха́нгелом предвозвіще́нная;","ра́дуйся, благові́стія Арха́нгелова восприє́мнице смире́нная.","Ра́дуйся, Херуви́мов і Серафи́мов честні́йшая;","ра́дуйся, Арха́нгелов і А́нгелов сла́внійшая.","Ра́дуйся, преви́ше сил небе́сних вознесе́нная;","ра́дуйся, от го́рних во́їнств почита́ємая.","Ра́дуйся, ли́ки а́нгельськими песносло́вимая;","ра́дуйся, от всіх родо́в при́сно ублажа́ємая.","Ра́дуйся, прибі́жище на́ше і заступле́ніє;","ра́дуйся, в ско́рбіх і напа́стіх вспоможе́ніє.","Ра́дуйся, за христия́н усе́рдная моли́твеннице;","ра́дуйся, за ни пред Бо́гом ми́лостивая предста́тельнице.","Ра́дуйся, Пренепоро́чная Отрокови́це, гра́да на́шего Небе́сная Засту́пнице."]},{"h":"Кондак 2","ps":["Ви́дівши святи́й о́браз Твой, Пречи́стая, святи́м Луко́ю первопи́санний, рекла́ єси́: «С сим о́бразом благода́ть Моя́ і си́ла да пребу́деть». І во Ми́нстем о́бразе зря́ще сби́тіє слове́с Твої́х, о Тебі́ просла́вим Го́спода, пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́ти не мо́жно ди́внаго Про́мисла Бо́жия, ка́ко чу́дная іко́на Твоя́, Богоро́дице, насади́телю ві́ри правосла́вния, благові́рному кня́зю Влади́миру, на по́мощ даде́ся во апо́стольстві єго́ от Царгра́да і Корсу́ни да́же до Ки́єва. Ми же, преі́скренні умиля́ющеся Твоєму́ о ро́ді на́шем предста́тельству, ві́рно вопіє́м:","Ра́дуйся, і́стиннаго благоче́стія наста́внице;","ра́дуйся, язи́чеськаго нече́стія іскорени́тельнице.","Ра́дуйся, чудотво́рною іко́ною а́ки драгоці́нним да́ром кня́зя Влади́мира обогати́вшая;","ра́дуйся, в равноапо́стольних труді́х єго́ укріпи́вшая.","Ра́дуйся, власть де́монськую сокруши́вшая;","ра́дуйся, ві́ру правосла́вную в землі́ на́шей утверди́вшая.","Ра́дуйся, Тобо́ю от пре́лести дия́воли свобожда́ємся;","ра́дуйся, Тобо́ю же позна́нія Творця́ сподобля́ємся.","Ра́дуйся, ко́зней вра́жиїх посіче́ніє;","ра́дуйся, ві́рних чад Отцю́ Небе́сному усиновле́ніє.","Ра́дуйся, злові́рія і́дольськаго попра́ніє;","ра́дуйся, уче́нія Христо́ва насажде́ніє.","Ра́дуйся, Пренепоро́чная Отрокови́це, гра́да на́шего Небе́сная Засту́пнице."]},{"h":"Кондак 3","ps":["Си́лу благода́ті, явле́нния в честні́й іко́ні Твоє́й, Влади́чице, ви́ді святи́й равноапостольний князь Влади́мир і со благогові́нієм ве́ліїм поста́ви ю в Десяти́нней це́ркві гра́да Ки́єва, вопію́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи попече́ніє ма́тернєє о просвіще́нних лю́діх землі́ Ру́ськия, соді́лала єси́ ю До́мом Свої́м, і то́ки чуде́с от іко́ни Твоєя́ преізоби́льно істочи́ла єси́, Богоро́дице, сего́ ра́ди взива́єм Ті си́це:","Ра́дуйся, притека́ющих к іко́ні Твоє́й луча́ми чуде́с озаря́ющая;","ра́дуйся, обраща́ющимся к ней безчи́сленния ми́лости подаю́щая.","Ра́дуйся, всім прося́щим мо́ре щедро́т ізлива́ющая;","ра́дуйся, духо́вную ра́дость нам соде́ловающая.","Ра́дуйся, о лю́діх правосла́вних при́сноє попече́ніє;","ра́дуйся, о́браз Твой дарова́вшая нам я́ко зало́г спасе́нія.","Ра́дуйся, істо́чник благода́ті неістощи́мий;","ра́дуйся, кла́дезю сокро́вищ многоці́нний.","Ра́дуйся, крі́посте тве́рдая ві́ри правосла́вния;","ра́дуйся, всім чту́щим Си́на Твоєго́ по́моще пресла́вная.","Ра́дуйся, путь і́стини указу́ющая заблу́ждшим;","ра́дуйся, ско́ро поспе́шствующая на по́мощ Тя призива́ющим.","Ра́дуйся, Пренепоро́чная Отрокови́це, гра́да на́шего Небе́сная Засту́пнице."]},{"h":"Кондак 4","ps":["Бу́ри бід і напа́стей за гріхи́ на́ша мно́гажди на Русь воздвиза́ємі би́ша, та́кожде і град Ки́єв огню́ і мечу́ предава́єм бі от нечести́вих ага́рян, не ві́дущих пі́ти і́стинному Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав о бога́тстві Ки́єва, хан ага́рянський во єди́но лі́то устреми́ся расхи́тити є, і град той пожже́. Во́їн же ні́кий злочести́вий, взяв ри́зу многоці́нную, Всеблага́я Ма́ти, іко́ну же Твою́ вве́рже в Днепр, оба́че сія́ неврежде́нна во вода́х сохрани́ся, подвиза́ющи нас восхвали́ти Тя си́це:","Ра́дуйся, о́браз Твой, я́ко купину́ неопа́льну яви́вшая;","ра́дуйся, іко́ну Твою́ от пла́мене сохрани́вшая.","Ра́дуйся, по вода́м а́ки по су́ху от Ки́єва да́же до Ми́нська іко́ну Твою́ прене́сшая;","ра́дуйся, во́ди Неми́ги і Сви́слочі явле́нієм Свої́м освяти́вшая.","Ра́дуйся, Цари́це небесе́ і землі́, Є́йже вся стіхі́ї покоря́ються;","ра́дуйся, Тобо́ю же на спаси́тельния стезі́ лю́ди наставля́ються.","Ра́дуйся, пото́па гріхо́внаго усмире́ніє;","ра́дуйся, свирі́пих страсте́й укроще́ніє.","Ра́дуйся, мо́ря жите́йськаго благонаде́жноє прохожде́ніє;","ра́дуйся, от землі́ на не́бо ві́рних возведе́ніє.","Ра́дуйся, ди́вноє благода́ті зна́меніє;","ра́дуйся, си́ли чудотво́рния явле́ніє.","Ра́дуйся, Пренепоро́чная Отрокови́це, гра́да на́шего Небе́сная Засту́пнице."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ уподо́билася єси́ пречестна́я іко́на Твоя́, Богороди́тельнице, лучи́ чу́дними осія́вшая насе́льники гра́да Ми́нська. Они́ же, зря́ще таї́нственноє явле́ніє єя́ на вода́х Сви́слочі, со умиле́нієм воспі́ша Си́ну Твоєму́ і Бо́гу на́шему: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше чу́дную іко́ну сію́, о Всеми́лостивая, і приє́млюще я́ко дар Бо́жий, лю́ди христия́нстії взя́ша ю от води́ і поста́виша в це́ркві за́мковой в честь Пресла́внаго Рождества́ Твоєго́, і а́біє благода́рні воззва́ша:","Ра́дуйся, от іко́ни Твоєя́ да́ри многоразли́чнії істоча́ющая;","ра́дуйся, я́ко Само́й Ті су́щей во іко́ні Твоє́й благода́ть нам ізлива́ющая.","Ра́дуйся, грі́шников не отмета́ющая;","ра́дуйся, ка́ющихся те́плі приє́млющая.","Ра́дуйся, гра́да на́шего неуси́пная храни́тельнице;","ра́дуйся, за нас пред Бо́гом любвеоби́льная хода́тайце.","Ра́дуйся, ві́ри і благоче́стія ісправле́ніє;","ра́дуйся, в моли́твах ко Го́споду всемо́щноє дерзнове́ніє.","Ра́дуйся, боля́щих і немощству́ющих ісціле́ніє;","ра́дуйся, заблу́ждших на путь пра́вий наставле́ніє.","Ра́дуйся, благода́ті оби́льноє дарова́ніє;","ра́дуйся, люде́й христоімени́тих непости́дноє упова́ніє.","Ра́дуйся, Пренепоро́чная Отрокови́це, гра́да на́шего Небе́сная Засту́пнице."]},{"h":"Кондак 6","ps":["Пропове́дниками чуде́с ве́ліїх, от іко́ни Ми́нськия істека́ющих, яви́шася мно́зі лю́діє, ї́хже Ти, Премилосе́рдная Влади́чице, поклоня́тися святи́не сей научи́ла єси́, да нело́жно воспою́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ і возвели́чися ві́ра на́ша по мно́зіх лі́тіх пліне́нія ле́стнаго і непра́ваго, і па́ки возврати́ся іко́на Ми́нськая лю́дем правосла́вним, і́же с ра́достію воспі́ша Богоро́дице:","Ра́дуйся, Правосла́вія щі́те і огражде́ніє;","ра́дуйся, оте́чеських уста́вов нези́блемоє утвержде́ніє.","Ра́дуйся, малове́рних вразумле́ніє;","ра́дуйся, в сомні́нії су́щим снисхожде́ніє.","Ра́дуйся, ві́рних чад Це́ркве Правосла́вния духо́вноє услажде́ніє;","ра́дуйся, отсту́пников пра́вия ві́ри посрамле́ніє.","Ра́дуйся, правосла́вних немо́лчная похвало́;","ра́дуйся, гони́мим за ві́ру несокруши́моє забра́ло.","Ра́дуйся, утесня́ємим ско́роє вспоможе́ніє;","ра́дуйся, му́чеников і іспові́дников неізглаго́ланная отра́до.","Ра́дуйся, іскуша́ємим по́моще;","ра́дуйся, обурева́ємим приста́нище.","Ра́дуйся, Пренепоро́чная Отрокови́це, гра́да на́шего Небе́сная Засту́пнице."]},{"h":"Кондак 7","ps":["Хотя́ Влади́ка наш і Судія́ Пра́веднійший вразуми́ти зе́млю Ру́ськую за беззако́нія тьмочи́сленния, попусти́ мучи́телем гна́ти Це́рков Правосла́вную, да всі, в покая́ніє прише́дше, возопії́м Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє наста́ іспита́ніє от Го́спода, єгда́ собо́рний храм во гра́ді Ми́нске разруше́н бисть от неі́стових гони́телей. Іко́на же Твоя́, о Богома́ти, от'я́та і сокри́та бі от ві́рних. Лю́діє же правосла́внії в сокруше́нії серде́ць возопи́ша к Богоро́диці:","Ра́дуйся, во дні правосу́днаго Бо́жия посіще́нія гнів Єго́ отводя́щая;","ра́дуйся, в тя́жких злострада́ніях нас не оставля́ющая.","Ра́дуйся, лю́тия крамо́ли облича́ющая;","ра́дуйся, душегуби́тельния уче́нія низлага́ющая.","Ра́дуйся, благосе́рдая на́ша вразуми́тельнице;","ра́дуйся, непам'ятозло́бная на́ша настави́тельнице.","Ра́дуйся, в злих обстоя́ніїх неістощи́моє терпі́ніє;","ра́дуйся, с правосу́дієм Бо́жиїм смире́нноє примире́ніє.","Ра́дуйся, малоду́шних і па́дших возста́ніє;","ра́дуйся, ду́ха уни́нія і боя́зні отгна́ніє.","Ра́дуйся, гріхо́в на́ших отпуще́ніє;","ра́дуйся, Бо́жиє к нам благоволе́ніє.","Ра́дуйся, Пренепоро́чная Отрокови́це, гра́да на́шего Небе́сная Засту́пнице."]},{"h":"Кондак 8","ps":["Стра́нноє і ужа́сноє наше́ствіє іноплеме́нних пости́же нас. Милосе́рдієм же Бо́жиїм одолі́во враги́, лю́діє, предста́тельством Богома́тері, отверзо́ша хра́ми правосла́внії і возда́ша благодаре́ніє Го́сподеві, воспіва́я Єму́: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся іспо́лнися ра́дости неізрече́нния, єгда́ раба́ Бо́жия Варва́ра обрі́те чу́дний о́браз Твой, Ма́ти Ді́во, сокри́тий посреді́ пра́ха і тлі́нія. Ми же, див'я́щеся таково́му неча́ємому обрі́тенію, восхваля́єм Тя:","Ра́дуйся, ві́ру Христо́ву от поруга́нія защища́ющая;","ра́дуйся, пра́ведний гнів Бо́жий на ми́лость претворя́ющая.","Ра́дуйся, отсту́пников ві́ри постижа́ющая;","ра́дуйся, нече́стіє грі́шников облича́ющая.","Ра́дуйся, броне́ неуязви́мая;","ра́дуйся, воєво́до непобіди́мая.","Ра́дуйся, от наше́ствія іноплеме́нних ізбавле́ніє;","ра́дуйся, от рабо́ти вра́жия свобожде́ніє.","Ра́дуйся, ви́димих і неви́димих супоста́ть одолі́ніє;","ра́дуйся, вражду́ющих ско́роє вразумле́ніє.","Ра́дуйся, упокоє́ніє за дру́ги своя́ ду́ші положи́вших;","ра́дуйся, прославле́ніє за Ві́ру і Оте́чество на по́лі бра́ні убіє́нних.","Ра́дуйся, Пренепоро́чная Отрокови́це, гра́да на́шего Небе́сная Засту́пнице."]},{"h":"Кондак 9","ps":["Вся́коє разумі́ніє челові́чеськоє не возмо́жеть ісчести́ страда́нія, ко́ї претерпі́ли гра́ждане Оте́чества на́шего в годи́ну во́їн, лихоле́тій і в послі́днєє вре́м'я от біди́ черно́бильськия. Взира́я же на іко́ну Твою́, Богома́ти, я́ко на цельбоно́сноі утіше́ніє, непреста́нно поє́м: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я суєму́дренния соблазня́ються о дре́вности іко́ни Ми́нськия і недоумі́ють пости́гнути та́їнственний Про́мисл Бо́жий, сохрани́вший ю в огні́ і вода́х, от рук іноплеме́нних і злоумишле́ній супроти́вних. Ми же, прославля́юще Богоро́дицю пред чудотво́рним о́бразом Єя́, вопіє́м такова́я:","Ра́дуйся, почита́нія святи́х іко́н увенча́ніє;","ра́дуйся, іконобо́рнаго злоче́стія обличе́ніє.","Ра́дуйся, душеполе́зних зна́ній преізоби́льноє ізлія́ніє;","ра́дуйся, душевре́днаго мра́ка сві́тлоє озаре́ніє.","Ра́дуйся, неві́рних сми́слов ми́лостивоє просвіще́ніє;","ра́дуйся, непра́во му́дрствующих внеза́пноє низверже́ніє.","Ра́дуйся, ві́рних нези́блемоє увіре́ніє;","ра́дуйся, от'є́млющая духо́вноє помраче́ніє.","Ра́дуйся, Про́мисла Бо́жия прославле́ніє;","ра́дуйся, прего́рдих хули́телей устраше́ніє.","Ра́дуйся, суєму́дренних прему́дро смиря́ющая;","ра́дуйся, заблу́ждших кро́тко вразумля́ющая.","Ра́дуйся, Пренепоро́чная Отрокови́це, гра́да на́шего Небе́сная Засту́пнице."]},{"h":"Кондак 10","ps":["Спаси́тельноє приста́нище от жите́йських треволне́ній і́мами во хра́мі Ду́ха Свята́го Богоспаса́ємаго гра́да на́шего, іді́же світоза́рная іко́на Твоя́, Влади́чице, неотсту́пно дони́ні пребива́єть, всіх нас путеводя́ к жи́зні ві́чній. Сего́ ра́ди о Тебі́ возглаша́єм Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і заступле́ніє не то́кмо гра́ду на́шему, но і всім с ві́рою притека́ющим к Тебі́, Преблагослове́нная, даде́ся свята́я іко́на Твоя́, є́юже мно́гажди благоді́яла єси́ нам і отце́м на́шим, да вознесе́м Ті пі́ніє таково́є:","Ра́дуйся, і́щущим спасе́нія пра́вий путь указу́ющая;","ра́дуйся, снисше́дших да́же до дна а́дова моли́твами Свої́ми спаса́ющая.","Ра́дуйся, супроти́в наше́ствія іноплеме́нних нас воздвиза́ющая;","ра́дуйся, от враго́в Оте́чество на́ше ізбавля́ющая.","Ра́дуйся, отча́янних ско́роє усли́шаніє;","ра́дуйся, неду́гов душе́вних і тіле́сних безме́здноє врачева́ніє.","Ра́дуйся, печа́лей жите́йських утоле́ніє;","ра́дуйся, гріхо́вних язв очище́ніє.","Ра́дуйся, во обстоя́ніях су́щим всегда́шняя помо́щнице;","ра́дуйся, лю́дем благові́рним усе́рдная споспі́шнице.","Ра́дуйся, неча́янная Ра́досте;","ра́дуйся, непости́дная Наде́ждо.","Ра́дуйся, Пренепоро́чная Отрокови́це, гра́да на́шего Небе́сная Засту́пнице."]},{"h":"Кондак 11","ps":["Пі́ніє і моле́ніє о Богохрани́мій страні́ на́шей, властеіх, во́їнстві і наро́ді єя́, прийми́ пред чудотво́рним о́бразом Твої́м, Влади́чице, і спаси́ нас, я́ко держа́щая ски́петр в руці́ Своє́й. Богомладе́нець же Ісу́с, імі́яй в десни́ці держа́ву, да да́руєть нам ти́хоє і безмо́лвноє житіє́, сли́шаще от нас: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́тлий пра́здник явле́нія іко́ни Твоєя́, Присноді́во, во гра́ді Ми́нске, ісполня́єть ликова́нієм сердця́ на́ша. Сего́ ра́ди с ві́рою припа́дающе і с любо́вію лобиза́юще чу́дний о́браз Твой, вопіє́м Ті:","Ра́дуйся, Богоспаса́ємому гра́ду на́шему ми́лость показа́вшая;","ра́дуйся, нас грі́шних сія́нієм Свої́м просвіти́вшая.","Ра́дуйся, при́сно си́лу Свою́ явля́ющая;","ра́дуйся, предста́тельством Свої́м нас спаса́ющая.","Ра́дуйся, моли́тви на́ша приє́млющая;","ра́дуйся, хвале́нія на́ша не отверга́ющая.","Ра́дуйся, небожи́телями при́сно прославля́ємая;","ра́дуйся, собо́ром белору́ських святи́х і новому́чеников сугу́бо воспіва́ємая.","Ра́дуйся, людьми́ благочести́вими в позлаще́нную ри́зу облече́нная;","ра́дуйся, мно́гими би́серами і адама́нтами преукраше́нная.","Ра́дуйся, серде́ць на́ших ти́хоє умиле́ніє;","ра́дуйся, житія́ на́шего до́броє устроє́ніє.","Ра́дуйся, Пренепоро́чная Отрокови́це, гра́да на́шего Небе́сная Засту́пнице."]},{"h":"Кондак 12","ps":["Благода́ті Своєя́, о Всеми́лостивая Ма́ти, не лиши́ нас грі́шних, претерпіва́єм бо днесь но́вия ско́рби і нестроє́нія, ніка́коже іму́ще наде́жди оправди́тися, но помози́ нам возста́ти от поги́бельних смуть, да, о Тебі́ ра́дующеся, воспоє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Небе́сную Засту́пницю на́шу, ві́руєм і іспові́дуєм, я́ко і в послі́дняя времена́ яви́ши благода́тную по́мощ, і ї́миже ві́си судьба́ми сохрани́ши нас от собла́знов ми́ра сего́, да благода́рні восхва́лим Тя:","Ра́дуйся, ізбавле́ніє на́ше от наві́т вра́жиїх;","ра́дуйся, спасе́ніє от кова́рств лука́ваго.","Ра́дуйся, от сна гріхо́внаго пробужде́ніє;","ра́дуйся, беззако́ній на́ших проще́ніє.","Ра́дуйся, пред Всеви́шнім благогові́йноє предстоя́ніє;","ра́дуйся, по́лчищ сатани́нських благомо́щноє разсі́яніє.","Ра́дуйся, поги́бших взиска́ніє;","ра́дуйся, прельще́нних вразумле́ніє.","Ра́дуйся, напра́сную смерть от нас отводя́щая;","ра́дуйся, о кончи́ні христия́нстій нам хода́тайствующая.","Ра́дуйся, врата́ небе́сная нам отверза́ющая;","ра́дуйся, к жи́зні ві́чній нас приводя́щая.","Ра́дуйся, Пренепоро́чная Отрокови́це, гра́да на́шего Небе́сная Засту́пнице."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти, Засту́пнице Небе́сная гра́да на́шего, прийми́ сію́ ма́лую моли́тву і умоли́ Си́на Твоєго́, Судію́ Пра́веднаго, да сподо́бит десна́го стоя́нія нас, вопію́щих Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельськія си́ли, прилі́жно моля́щіїся і благогові́йно служа́щії Ті, Пресвята́я Ді́во, от літ дре́вніх на ге́рбі Богоспаса́ємаго гра́да Ми́нська ізображе́ні би́ша во свиді́тельство чу́днаго Твоєго́ о нас попече́нія. Ми же земноро́днії, дерза́я подража́ти пі́сні а́нгельстій, благода́рственно Тебі́ поє́м:","Ра́дуйся, о зача́тії Си́на от Ду́ха Свята́го Арха́нгелом предвозвіще́нная;","ра́дуйся, благові́стія Арха́нгелова восприє́мнице смире́нная.","Ра́дуйся, Херуви́мов і Серафи́мов честні́йшая;","ра́дуйся, Арха́нгелов і А́нгелов сла́внійшая.","Ра́дуйся, преви́ше сил небе́сних вознесе́нная;","ра́дуйся, от го́рних во́їнств почита́ємая.","Ра́дуйся, ли́ки а́нгельськими песносло́вимая;","ра́дуйся, от всіх родо́в при́сно ублажа́ємая.","Ра́дуйся, прибі́жище на́ше і заступле́ніє;","ра́дуйся, в ско́рбіх і напа́стіх вспоможе́ніє.","Ра́дуйся, за христия́н усе́рдная моли́твеннице;","ра́дуйся, за ни пред Бо́гом ми́лостивая предста́тельнице.","Ра́дуйся, Пренепоро́чная Отрокови́це, гра́да на́шего Небе́сная Засту́пнице."]},{"h":"Кондак 1","ps":["Ізбра́нная от всіх родо́в, Влади́чице Ді́во Богоро́дице, ни́ні, припа́дающе к чудотво́рному о́бразу Твоєму́, хвале́бноє пі́ніє і благодаре́ніє прино́сим Ті:","Ра́дуйся, Пренепоро́чная Отрокови́це, гра́да на́шего Небе́сная Засту́пнице."]},{"h":"Молитва","ps":["О Всепі́тая і Всеблага́я Ді́во Богоро́дице, Небе́сная на́ша Засту́пнице! К Тебі́ по Бо́зі, я́ко Премилосе́рдей Госпоже́, собо́рні прибіга́єм і вопіє́м: прийми́ сіє́ ма́лоє хвале́бноє пі́ніє, сохрани́ Богоспаса́ємий град сей, єму́ же чудотво́рная іко́на Твоя́ во отра́ду і утіше́ніє даде́ся. Сего́ ра́ди мо́лим Тя: ізба́ви нас от враг ви́димих і неви́димих, от наше́ствія іноплеме́нних і междоусо́бния бра́ні, от зла́го обстоя́нія і ско́рби, от іскуше́ній, бід і болі́зней.","Спаси́ і поми́луй раби́ Твоя́: Вели́каго Господи́на і Отця́ на́шего Святі́йшаго Патріа́рха Моско́вськаго і всея́ Руси́, Преосвяще́нния митрополи́ти, архієпи́скопи, єпи́скопи, весь свяще́нничеський і мона́шеський чин, і весь при́чет церко́вний. Прийми́ под кров Твой вла́сті і во́їнство богохрани́мия страни́ на́шея, вразуми́ і наста́ви їх пра́во пра́вити, за́повіді Бо́жия соблюда́юще, да ти́хоє і безмо́лвноє житіє́ поживе́м во вся́ком благоче́стії і чистоті́. О Пречи́стая Влади́чице! Не забу́ди нас во вся дні жи́зні на́шея і да пребива́єть с на́ми неотсту́пно о́браз Твой честни́й. Во вре́м'я же ісхо́да на́шего проле́й те́плую Твою́ моли́тву ко Пра́ведному Судії́, да, презрі́в безчи́сленная прегріше́нія, поми́луєть і спасе́ть нас, я́ко Благ і Человіколю́бець. Амі́нь."]},{"h":"Тропар, глас 5","ps":["На дре́ві кре́стнім яви́лася єси́, Пренепоро́чная Отрокови́це, / от Царгра́да і Ки́єва / Богоспаса́ємому гра́ду Ми́нську ми́лость показа́вши. / Просвіти́ нас, грі́шних, сія́нієм Свої́м, / яви́, я́ко при́сно, си́лу Свою́, / спаси́ нас предста́тельством Свої́м / і ізбавля́й от наві́т вра́жиїх, // Тя бо Необори́мую Сті́ну і єди́ну Наде́жду і́мами."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]}];
export default D;
